INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-llanganatis-atahualpa-gold',
      'คำสาปสมบัติลยานกานาเตส (ทองคำไถ่ชีวิตกษัตริย์อาตาอวลปา)',
      'The Curse of Llanganatis Treasure (The Gold of Atahualpa)',
      'curse',
      'ตุงกูราอัว',
      'Tungurahua',
      'เทือกเขาลยานกานาเตส',
      'Llanganates National Park',
      -1.2167,
      -78.3333,
      'jungle_curse',
      'เมื่อกษัตริย์อินคา ''อาตาอวลปา'' ถูกกองทัพสเปนของฟรันซิสโก ปิซาร์โร จับตัวในปี 1532 พระองค์ได้เสนอทองคำเต็มห้องเพื่อแลกกับอิสรภาพ แต่กลับถูกสังหารก่อน ขุนพลรูมิญาอุยจึงนำทองคำมหาศาลหนักหลายสิบตันไปซ่อนไว้ในเทือกเขาลอยฟ้าลยานกานาเตสอันลึกลับของเอกวาดอร์ พร้อมคำสาปแช่งให้ผู้ที่พยายามตามหาต้องพบจุดจบอย่างทุกข์ทรมาน ในเวลาต่อมา นักสำรวจทั้งริชาร์ด สปรุซ และเออร์เนสต์ บาร์โธโลมิวที่เข้าไปตามล่าลายแทงต่างล้มตายหรือสาบสูญไปอย่างไร้ร่องรอย',
      'When Inca Emperor Atahualpa was captured and executed by Francisco Pizarro in 1532, general Ruminahui hid a colossal hoard of golden treasures deep in the treacherous, fog-shrouded Llanganatis mountains of Ecuador. Chronicled by botanist Richard Spruce and prospector Valverde, an enduring hex is said to doom all treasure hunters who venture into the trackless paramo, resulting in madness, fatal landslides, and unexplained disappearances.',
      'มีบันทึกลายแทงวัลแวร์เด (Valverde Derrotero) ในศตวรรษที่ 18 ที่อ้างเส้นทางสู่ถ้ำสมบัติ แต่ทุกคนที่พยายามแกะรอยมักเสียชีวิตด้วยอุบัติเหตุประหลาดหรือจิตฟั่นเฟือน',
      'The 18th-century Valverde guide sent dozens of expeditions into the high Andes; virtually every leader suffered untimely death, drowning, or starvation in the peat bogs.',
      'ห้ามขุดค้นหรือเคลื่อนย้ายทองคำโบราณในเขตเทือกเขาลยานกานาเตสโดยไม่มีพิธีขอขมาผืนป่า',
      'Never attempt to exhume the lost Inca gold from the sacred paramo without traditional offering rites.',
      'https://i.ytimg.com/vi/K4U9t6ela0c/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/K4U9t6ela0c/hqdefault.jpg","title":"คำสาปสมบัติลยานกานาเตส (ทองคำไถ่ชีวิตกษัตริย์อาตาอวลปา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=K4U9t6ela0c","title":"The Treasure of the Llanganates | A Hidden Inca Fortune | 5 Minute World History","thumbnail":"https://i.ytimg.com/vi/K4U9t6ela0c/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-screaming-tunnel-niagara',
      'อุโมงค์เสียงกรีดร้องแห่งไนแอการา (อาถรรพ์เด็กหญิงในเปลวเพลิง)',
      'The Screaming Tunnel of Niagara Falls (The Burned Girl Hex)',
      'curse',
      'ออนแทรีโอ',
      'Ontario',
      'ไนแอการาฟอลส์',
      'Niagara Falls',
      43.1466,
      -79.1463,
      'creepy_wind',
      'อุโมงค์หินโบราณใต้รางรถไฟแกรนด์ทรังก์ สร้างขึ้นในช่วงต้นทศวรรษ 1900 ใกล้กับน้ำตกไนแอการา ตำนานเล่าว่ามีเด็กหญิงคนหนึ่งวิ่งหนีออกมาจากบ้านไร่ใกล้เคียงที่ถูกไฟไหม้ ร่างของเธอถูกเปลวไฟเผาไหม้จนทนทุกข์และเสียชีวิตอยู่ภายในอุโมงค์มืดแห่งนี้ เชื่อกันว่าหากใครจุดไม้ขีดไฟภายในอุโมงค์ในยามค่ำคืน เปลวไฟจะดับวูบลงทันที พร้อมกับมีเสียงกรีดร้องโหยหวนของเด็กหญิงดังก้องสะท้อนมาจากความมืดมิด',
      'The Screaming Tunnel is a limestone railway passage constructed around 1900 beneath the Grand Trunk Railway near Niagara Falls, Ontario. According to chilling local legend, a young girl fleeing an engulfed farmhouse died screaming in the tunnel. It is said that anyone who lights a wooden match in the tunnel at midnight will witness the flame immediately blow out followed by blood-curdling phantom screams.',
      'อุโมงค์แห่งนี้สร้างขึ้นเพื่อระบายน้ำและเป็นทางลอดของปศุสัตว์ แต่ชื่อเสียงเรื่องความเฮี้ยนทำให้ถูกนำไปใช้เป็นฉากถ่ายทำภาพยนตร์สยองขวัญของเดวิด โครเนนเบิร์ก เรื่อง The Dead Zone (1983)',
      'Originally designed as a drainage tunnel for locomotives, its paranormal notoriety attracted filmmaker David Cronenberg, who filmed an iconic death scene for ''The Dead Zone'' inside.',
      'ห้ามจุดไม้ขีดไฟตรงกึ่งกลางอุโมงค์ในยามเที่ยงคืน',
      'Never strike a wooden match in the dead center of the tunnel at midnight.',
      'https://i.ytimg.com/vi/k63_zskunjw/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/k63_zskunjw/hqdefault.jpg","title":"อุโมงค์เสียงกรีดร้องแห่งไนแอการา (อาถรรพ์เด็กหญิงในเปลวเพลิง)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=k63_zskunjw","title":"Creepy.Canada.S02E06","thumbnail":"https://i.ytimg.com/vi/k63_zskunjw/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-witch-of-yazoo-mississippi',
      'แม่มดแห่งยาซู (คำสาปเพลิงมรณะแห่งมิสซิสซิปปี)',
      'The Witch of Yazoo (The Fiery Vengeance of Glenwood)',
      'curse',
      'มิสซิสซิปปี',
      'Mississippi',
      'เมืองยาซูซิตี ยาซู',
      'Yazoo City, Yazoo County',
      32.8596,
      -90.4082,
      'creepy_wind',
      'ตำนานแม่มดชั่วร้ายที่อาศัยอยู่ริมแม่น้ำยาซูในศตวรรษที่ 19 เธอหลอกล่อกะลาสีเรือและชาวบ้านเข้าไปสังหารในป่าพรุ จนกระทั่งนายอำเภอและชาวบ้านนำกำลังล้อมจับ เธอได้วิ่งหนีลงไปในหล่มโคลนดูด ก่อนจมหายไปเธอได้สาปแช่งว่าจะกลับมาเผาทำลายเมืองยาซูซิตีให้วอดวายในอีก 20 ปีข้างหน้า ชาวบ้านได้นำโซ่เหล็กเส้นใหญ่มาล่ามหลุมศพของเธอไว้ในสุสานเกลนวูด แต่ในวันที่ 25 พฤษภาคม 1904 ไฟไหม้ครั้งประวัติศาสตร์ได้เผาผลาญเมืองจนวอดวาย และเมื่อชาวบ้านไปดูหลุมศพ พบว่าโซ่เหล็กขนาดใหญ่ได้ถูกตัดขาดออกจากกัน',
      'The Witch of Yazoo is an ominous legend popularized by author Willie Morris. Accused of luring fishermen into the swamp to their deaths, the dying witch cursed Yazoo City, swearing to return in twenty years and burn it to ash. Her grave in Glenwood Cemetery was encircled by heavy iron chains, yet on May 25, 1904, a ferocious fire incinerated the entire downtown, and residents found the massive cemetery chains snapped in two.',
      'หลุมศพที่มีโซ่เหล็กขาดล้อมรอบยังคงตั้งอยู่ในสุสานเกลนวูด และกลายเป็นหนึ่งในสัญลักษณ์อาถรรพ์ที่โด่งดังที่สุดของรัฐมิสซิสซิปปี',
      'The grave of the Yazoo Witch, complete with broken chain links encircling the mossy slab, remains an eerie tourist draw in Glenwood Cemetery.',
      'ห้ามปีนข้ามโซ่เหล็กที่ล้อมหลุมศพแม่มด',
      'Do not step over or disturb the broken iron chain links surrounding the witch''s grave.',
      'https://i.ytimg.com/vi/pmMSxn903ys/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/pmMSxn903ys/hqdefault.jpg","title":"แม่มดแห่งยาซู (คำสาปเพลิงมรณะแห่งมิสซิสซิปปี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=pmMSxn903ys","title":"The Evil Witch who Burned Down a City | Witch of Yazoo","thumbnail":"https://i.ytimg.com/vi/pmMSxn903ys/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-haunted-pillar-augusta-georgia',
      'เสาอาถรรพ์แห่งออกัสตา (เสาคำสาปมฤตยูแห่งจอร์เจีย)',
      'The Haunted Pillar of Augusta (The Cursed Market Column)',
      'curse',
      'จอร์เจีย',
      'Georgia',
      'เมืองออกัสตา ริชมอนด์',
      'Augusta, Richmond County',
      33.4735,
      -81.9654,
      'jungle_curse',
      'เสาปูนโบราณต้นเดียวที่หลงเหลือจากตลาดเกษตรกรเก่าในเมืองออกัสตา รัฐจอร์เจีย ตำนานเล่าว่าในปี 1878 นักเทศน์พเนจรคนหนึ่งถูกสั่งห้ามไม่ให้เทศนาในตลาด เขาจึงโกรธแค้นและชี้นิ้วสาปแช่งว่าจะมีพายุทอร์นาโดมาทำลายตลาดจนราบคาบ และหากใครพยายามรื้อถอนเสาต้นนี้จะต้องตาย ต่อมาเกิดพายุพัดถล่มตลาดพังทลายลงจริงเหลือเพียงเสาต้นนี้ และผู้รับเหมาหรือคนงานที่พยายามรื้อถอนเสาต่างถูกฟ้าผ่าหรือประสบอุบัติเหตุเสียชีวิตจนไม่มีใครกล้าแตะต้องนานกว่าศตวรรษ',
      'The Haunted Pillar of Augusta was the sole standing remnant of an open-air market built in 1829. Legend tells of an itinerant evangelist who was denied permission to preach, placing a dark curse that a tornado would obliterate the market leaving only the pillar, and that anyone seeking to move it would die immediately. In 1878, a freak tornado flattened the market, and subsequent laborers attempting demolition reportedly suffered fatal lightning strikes.',
      'เสาต้นนี้ยืนตระหง่านอยู่ริมถนนบรอดสตรีทจนถึงปี 2016 ก่อนที่อุบัติเหตุรถยนต์จะพุ่งชนจนเสาพังทลายลง แต่ตำนานคำสาปของเสายังคงเป็นที่จดจำ',
      'Standing eerily on 5th and Broad Street until accidentally destroyed by a car in 2016, city planners intentionally diverted streets around the cursed column for over a century.',
      'ห้ามท้าทายหรือสัมผัสเศษซากเสาอาถรรพ์ด้วยเจตนาร้าย',
      'Never utter curses or mock the legacy of the fallen Augusta column.',
      'https://i.ytimg.com/vi/--rVDB7pGQc/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/--rVDB7pGQc/hqdefault.jpg","title":"เสาอาถรรพ์แห่งออกัสตา (เสาคำสาปมฤตยูแห่งจอร์เจีย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=--rVDB7pGQc","title":"American Super/Natural - Legend of the Cursed Pillar","thumbnail":"https://i.ytimg.com/vi/--rVDB7pGQc/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-devils-tree-bernards-nj',
      'ต้นไม้ของพญามารแห่งเบอร์นาร์ดส์ (อาถรรพ์ต้นไม้ผูกคอตายแห่งนิวเจอร์ซีย์)',
      'The Devil''s Tree of Bernards (The Hanging Oak of Somerset)',
      'curse',
      'นิวเจอร์ซีย์',
      'New Jersey',
      'เบอร์นาร์ดส์ ซัมเมอร์เซต',
      'Bernards Township, Somerset County',
      40.6385,
      -74.5772,
      'creepy_wind',
      'ต้นโอ๊กโดดเดี่ยวรูปร่างบิดเบี้ยวบนถนนเมาน์เทนแทร็ค ในเมืองเบอร์นาร์ดส์ รัฐนิวเจอร์ซีย์ ตำนานท้องถิ่นระบุว่ามันเคยเป็นสถานที่แขวนคอทาสในยุคอาณานิคม และต่อมามีชาวนาที่สังหารคนในครอบครัวก่อนจะมาผูกคอตายบนต้นไม้ต้นนี้ ผู้คนเชื่อว่าต้นไม้มีพลังชั่วร้ายสิงสถิต ลำต้นจะอุ่นตลอดเวลาแม้ในฤดูหนาวที่หิมะตกหนาทึบ หิมะรอบโคนต้นจะละลายอย่างรวดเร็ว และใครก็ตามที่พยายามตัดหรือทำลายต้นไม้จะประสบอุบัติเหตุทางรถยนต์อย่างรุนแรงในเวลาไม่นาน',
      'The Devil''s Tree is a solitary, twisted white oak standing in an open field in Bernards Township, New Jersey. Local folklore alleges that lynchings occurred on its gnarled limbs and a desperate farmer hanged himself after murdering his family. Legend holds that the bark remains unnaturally warm to the touch in dead winter, and anyone who vandalizes or disrespects the tree encounters catastrophic car accidents shortly after.',
      'มีรอยโซ่และรอยขวานฟันที่เปลือกไม้มากมายจากผู้คนที่พยายามโค่น แต่รถตัดไม้ของเทศบาลเคยขัดข้องและเกิดอุบัติเหตุจนต้องปล่อยต้นไม้ทิ้งไว้',
      'Heavily featured in Weird NJ lore, the scarred oak is bordered by chain-link fences after numerous supernatural retaliations were reported by vandals.',
      'ห้ามใช้ขวานฟันหรือลบหลู่ต้นไม้ของพญามาร',
      'Never strike, carve, or disrespect the trunk of the Devil''s Tree.',
      'https://i.ytimg.com/vi/R1VF8t_BRfA/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/R1VF8t_BRfA/hqdefault.jpg","title":"ต้นไม้ของพญามารแห่งเบอร์นาร์ดส์ (อาถรรพ์ต้นไม้ผูกคอตายแห่งนิวเจอร์ซีย์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=R1VF8t_BRfA","title":"THE HAUNTING OF THE DEVIL''S TREE IN NJ","thumbnail":"https://i.ytimg.com/vi/R1VF8t_BRfA/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-centralia-mine-fire-ghost-town',
      'เมืองผีสิงเซนทราเลีย (คำสาปเพลิงใต้พิภพที่ไม่มีวันดับ)',
      'Centralia Mine Fire (The Real-Life Silent Hill Ghost Town)',
      'curse',
      'เพนซิลเวเนีย',
      'Pennsylvania',
      'เซนทราเลีย โคลัมเบีย',
      'Centralia, Columbia County',
      40.8042,
      -76.3408,
      'jungle_curse',
      'เมืองเหมืองถ่านหินร้างในรัฐเพนซิลเวเนียที่กลายเป็นแรงบันดาลใจหลักของเกมและภาพยนตร์ ''ไซเลนต์ฮิลล์'' (Silent Hill) จุดเริ่มต้นของคำสาปย้อนไปในปี 1869 เมื่อบาทหลวงแดเนียล อิกเนเชียส แม็คเดอร์มอตต์ ถูกกลุ่มมาเฟียเหมือง ''มอลลี แม็กไกวร์'' รุมทำร้ายจนบาดเจ็บ เขาได้ลุกขึ้นสาปแช่งว่าเมืองนี้จะถูกไฟเผาทำลายจนไม่มีใครอยู่อาศัยได้ ในปี 1962 เกิดไฟไหม้ขยะลุกลามลงสู่ชั้นถ่านหินใต้ดินและลุกไหม้อย่างต่อเนื่องจนแผ่นดินแยก ปล่อยควันพิษซัลเฟอร์จนชาวเมืองต้องอพยพทิ้งเมืองร้างไปตลอดกาล',
      'Centralia is an infamous Pennsylvania ghost town engulfed by an underground coal seam fire burning since 1962. Folklore traces the catastrophe to an 1869 curse by Catholic priest Father Daniel McDermott, who was beaten by Molly Maguires and swore the town would one day burn to the ground. Today, steam and toxic sulfur vent from fissures across deserted highways, inspiring the acclaimed video game ''Silent Hill''.',
      'ไฟใต้ดินยังคงลุกไหม้ลึกลงไปหลายร้อยฟุต และผู้เชี่ยวชาญคาดว่าจะมีเชื้อเพลิงถ่านหินแอนทราไซต์เพียงพอให้ไฟลุกไหม้ต่อไปอีกกว่า 250 ปี',
      'With underground temperatures surpassing 1,000°F and roads collapsing into smoking chasms, Centralia''s postal zip code 17927 was permanently revoked in 2002.',
      'ห้ามสูดดมควันซัลเฟอร์หรือเดินออกนอกแนวถนนคอนกรีตเก่าเพราะเสี่ยงดินยุบตัว',
      'Do not inhale fumes from smoking ground fissures or traverse sinkhole hazard zones.',
      'https://i.ytimg.com/vi/Qj5LjacccJ0/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/Qj5LjacccJ0/hqdefault.jpg","title":"เมืองผีสิงเซนทราเลีย (คำสาปเพลิงใต้พิภพที่ไม่มีวันดับ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=Qj5LjacccJ0","title":"CENTRALIA, PA - America''s Burning Ghost Town (Documentary)","thumbnail":"https://i.ytimg.com/vi/Qj5LjacccJ0/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-hornet-spooklight-ozarks',
      'แสงผีสิงฮอร์เน็ต (ดวงไฟวิญญาณปริศนาแห่งช่องเขาโอซาร์ก)',
      'The Hornet Spooklight (The Ghost Light of the Devil''s Promenade)',
      'curse',
      'มิสซูรี',
      'Missouri',
      'ฮอร์เน็ต นิวตัน',
      'Hornet, Newton County',
      36.9667,
      -94.65,
      'creepy_wind',
      'ปรากฏการณ์ดวงไฟลึกลับที่ปรากฏขึ้นบนถนนลูกรังเปลี่ยวแนวพรมแดนระหว่างรัฐมิสซูรีและโอคลาโฮมา หรือที่เรียกว่า ''เดวิลส์พรอมเมอนาด'' (The Devil''s Promenade) มีการบันทึกมาตั้งแต่ปี 1881 ดวงไฟทรงกลมสีส้ม แดง หรือฟ้า จะลอยขึ้นเหนือผิวดิน หมุนวน พุ่งเข้าหาพยาน และแยกตัวออกเป็นหลายดวงก่อนจะรวมร่างกันใหม่ ตำนานอินเดียนเล่าว่าเป็นวิญญานของคู่รักชาวเผ่าควาพอว์ (Quapaw) ที่กระโดดหน้าผาตาย หรือเป็นวิญญาณทหารสเปนโบราณที่ถือคบเพลิงตามหาศีรษะที่ถูกตัดขาด',
      'The Hornet Spooklight, also known as the Joplin Ghost Light, is an unexplained luminous phenomenon witnessed along a secluded gravel road on the Missouri-Oklahoma border since 1881. Appearing as an orb of fiery light dancing and shifting hues between orange, green, and cobalt blue, folklore attributes the light to Quapaw maiden spirits or a headless Spanish conquistador searching for his severed head.',
      'กองทัพสหรัฐฯ และนักฟิสิกส์เคยลงพื้นที่ตรวจสอบในปี 1946 แต่ไม่สามารถหาข้อสรุปทางวิทยาศาสตร์ที่ชัดเจนได้ ดวงไฟยังคงปรากฏให้เห็นในคืนมืดมิด',
      'Investigated by the US Army Corps of Engineers and countless university scientists, no definitive atmospheric or geological explanation has ever explained its erratic movements.',
      'ห้ามดับไฟหน้ารถแล้วเดินมุ่งหน้าเข้าหาดวงไฟเพียงลำพัง',
      'Never turn off headlights and chase the spooklight into the darkness on foot.',
      'https://i.ytimg.com/vi/iq_1QlZn7bU/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/iq_1QlZn7bU/hqdefault.jpg","title":"แสงผีสิงฮอร์เน็ต (ดวงไฟวิญญาณปริศนาแห่งช่องเขาโอซาร์ก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=iq_1QlZn7bU","title":"The mysterious Joplin spook light","thumbnail":"https://i.ytimg.com/vi/iq_1QlZn7bU/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-hex-house-tulsa-oklahoma',
      'บ้านคุณไสยเฮ็กซ์เฮาส์ (ลัทธิสะกดจิตและทาสมนต์ดำแห่งทัลซา)',
      'The Hex House of Tulsa (The House of Mind Control Horrors)',
      'curse',
      'โอคลาโฮมา',
      'Oklahoma',
      'เมืองทัลซา',
      'Tulsa, Tulsa County',
      36.1485,
      -95.9865,
      'whisper',
      'เรื่องจริงอันน่าสะพรึงกลัวในปี 1944 ณ บ้านเลขที่ 1310 ถนนนอร์ทบอสตัน เมืองทัลซา รัฐโอคลาโฮมา เมื่อเจ้าหน้าที่บุกค้นบ้านพักของนางแครอล แอนน์ สมิธ หญิงผู้อ้างตนเป็นผู้ถือสารแห่งพระเจ้า แต่กลับใช้การสะกดจิต พิธีกรรมไสยศาสตร์มนต์ดำ และการทารุณกรรม กักขังหญิงสาวสองคนไว้ในห้องใต้ดินอันมืดมิดนานหลายปี บังคับให้พวกเธอทำงานหนักและมอบเงินเดือนทั้งหมดให้เธอโดยไม่ได้รับอนุญาตให้เห็นแสงเดือนแสงตะวัน กลายเป็นตำนานสยองขวัญที่หลอกหลอนเมืองทัลซามาจนถึงปัจจุบัน',
      'The Hex House was the site of a shocking 1944 investigation in Tulsa, Oklahoma, where police unearthed a house of occult torment run by Carol Ann Smith. Posing as a spiritual prophetess, Smith utilized intense psychological manipulation, hypnosis, and dark hexes to enslave two young women in an unheated basement crawlspace for years, confiscating their assets under threats of demonic curses.',
      'คดีนี้สร้างความตื่นตระหนกไปทั่วสหรัฐฯ จนสื่อมวลชนขนานนามบ้านหลังนี้ว่า ''Hex House'' และต่อมาถูกนำมาตั้งเป็นชื่อบ้านผีสิงระดับตำนานของเมืองทัลซา',
      'The sensational 1944 trial transfixed the nation, giving birth to Tulsa''s long-running and award-winning extreme haunted attraction named in its honor.',
      'ห้ามทำพิธีกรรมสะกดจิตหรือเรียกชื่อลัทธิมืดในบริเวณสถานที่เกิดเหตุ',
      'Never practice black magic or occult binding rituals invoking the Hex House matriarch.',
      'https://i.ytimg.com/vi/XwvoVjVKWlM/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/XwvoVjVKWlM/hqdefault.jpg","title":"บ้านคุณไสยเฮ็กซ์เฮาส์ (ลัทธิสะกดจิตและทาสมนต์ดำแห่งทัลซา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XwvoVjVKWlM","title":"The Real Hex House in Tulsa Oklahoma","thumbnail":"https://i.ytimg.com/vi/XwvoVjVKWlM/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-bernardo-galvez-haunted-portrait',
      'ภาพวาดผีสิงเบอร์นาร์โด เด กัลเบซ (สายตาอาถรรพ์แห่งโรงแรมกัลเบซ)',
      'The Haunted Portrait of Bernardo de Galvez (The Ghostly Gaze)',
      'curse',
      'เท็กซัส',
      'Texas',
      'เกาะกัลเวสตัน',
      'Galveston Island',
      29.2889,
      -94.7956,
      'creepy_wind',
      'ภาพวาดสีน้ำมันขนาดเท่าตัวจริงของนายพลเบอร์นาร์โด เด กัลเบซ ผู้นำกองทัพสเปนในศตวรรษที่ 18 ที่แขวนอยู่ปลายสุดของห้องโถงในโรงแรมกัลเบซ (Hotel Galvez) เกาะกัลเวสตัน รัฐเท็กซัส ผู้คนเล่าขานว่าดวงตาในภาพวาดจะขยับจ้องมองตามผู้คนที่เดินผ่านไปมาตลอดเวลา และหากใครถ่ายภาพวาดนี้โดยไม่เอ่ยปากขออนุญาตภาพจะออกมาเบลอ มืดดำ หรือมีรูปเงาหัวกะโหลกซ้อนทับ รวมถึงผู้ถ่ายจะพบกับโชคร้ายหรืออาการเจ็บป่วยกะทันหัน',
      'The Portrait of Bernardo de Galvez hangs at the end of the lower hallway in Galveston''s historic Hotel Galvez. Depicting the Spanish general for whom the island is named, guests and staff report that his painted eyes follow onlookers across the carpet. Crucially, taking a photograph of the portrait without politely asking his permission results in ruined, corrupted photos or an immediate streak of terrifying misfortune.',
      'นักท่องเที่ยวและนักล่าผีต่างรายงานตรงกันว่าเมื่อยืนหน้าภาพวาด อุณหภูมิจะลดฮวบลงอย่างรวดเร็ว และกล้องดิจิทัลมักจะแบตเตอรี่หมดทันที',
      'Paranormal investigators universally adhere to the protocol of greeting the portrait and requesting permission aloud before clicking the shutter to avoid cursed camera malfunctions.',
      'ห้ามถ่ายภาพวาดนายพลกัลเบซโดยไม่กล่าวขออนุญาตก่อน',
      'Never photograph the Bernardo de Galvez painting without verbally requesting his permission first.',
      'https://i.ytimg.com/vi/T_v8HwVRHZo/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/T_v8HwVRHZo/hqdefault.jpg","title":"ภาพวาดผีสิงเบอร์นาร์โด เด กัลเบซ (สายตาอาถรรพ์แห่งโรงแรมกัลเบซ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=T_v8HwVRHZo","title":"Texas Chronicles: The Historic Haunted Hotel Galvez","thumbnail":"https://i.ytimg.com/vi/T_v8HwVRHZo/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-st-michan-crypt-mummies-dublin',
      'มัมมี่ใต้สุสานเซนต์มิแคน (อาถรรพ์คำสาปนักรบครูเสดแห่งดับลิน)',
      'The Crypt Mummies of St. Michan (The Dublin Crusader Curse)',
      'curse',
      'ดับลิน',
      'Dublin',
      'โบสถ์เซนต์มิแคน ถนนเชิร์ชสตรีท',
      'Church Street, Dublin 7',
      53.3486,
      -6.2764,
      'creepy_wind',
      'ใต้ถุนโบสถ์เซนต์มิแคนในกรุงดับลิน ประเทศไอร์แลนด์ เป็นที่ตั้งของห้องเก็บศพใต้ดินโบราณที่มีสภาพอากาศแห้งจากหินปูน ทำให้ร่างของผู้เสียชีวิตไม่เน่าเปื่อยแต่กลายสภาพเป็นมัมมี่ธรรมชาติ หนึ่งในร่างที่โด่งดังที่สุดคือ ''เดอะครูเซเดอร์'' (The Crusader) อัศวินร่างยักษ์สูงกว่า 6 ฟุตครึ่งในยุคสงครามครูเสด มีตำนานเล่าว่าใครที่กล้าลบหลู่ ขโมย หรือทำลายกระดูกของมัมมี่ในสุสานแห่งนี้จะต้องเผชิญกับคำสาปแช่งแห่งความวิบัติและหลอนประสาทจนกว่าจะนำชิ้นส่วนกลับมาคืน',
      'Beneath St. Michan''s Church in Dublin lies a vault where methane gas and dry limestone walls have naturally mummified centuries of corpses. The most famous remains belong to ''The Crusader'', a massive 800-year-old medieval knight with broken legs arranged to fit his coffin. Lore warns of severe psychological afflictions and relentless curses falling upon grave robbers who dare disturb the entombed nobles.',
      'ในปี 2019 มีโจรบุกเข้าไปตัดศีรษะของมัมมี่อัศวินครูเสดออกไป จนกระทั่งเกิดความกลัวในอาถรรพ์และตำรวจสามารถติดตามศีรษะกลับคืนมาได้ในเวลาต่อมา',
      'In February 2019, a vandal desecrated the vault and stole the Crusader''s severed skull; intense media outcry and superstitious dread led to the rapid anonymous recovery of the artifact.',
      'ห้ามจับต้องหรือพยายามนำชิ้นส่วนมัมมี่ออกจากห้องใต้ดินเซนต์มิแคน',
      'Never touch or desecrate the desiccated remains in the St. Michan limestone crypt.',
      'https://i.ytimg.com/vi/J6iSmTeGZTQ/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/J6iSmTeGZTQ/hqdefault.jpg","title":"มัมมี่ใต้สุสานเซนต์มิแคน (อาถรรพ์คำสาปนักรบครูเสดแห่งดับลิน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=J6iSmTeGZTQ","title":"Mummified Remains at St Michan''s est 1095 open vaults for visitors. 4K 60FPS","thumbnail":"https://i.ytimg.com/vi/J6iSmTeGZTQ/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-rehmeyer-hollow-hex-murder',
      'คดีฆาตกรรมเฮ็กซ์ฮอลโลว์ (คำสาปหมอผีพาววาแห่งยอร์กเคาน์ตี)',
      'The Hex Hollow Murder of Rehmeyer''s Hollow (The Powwow Hex)',
      'curse',
      'เพนซิลเวเนีย',
      'Pennsylvania',
      'หุบเขาเรห์ไมเยอร์ ยอร์กเคาน์ตี',
      'Rehmeyer''s Hollow, York County',
      39.8167,
      -76.65,
      'creepy_wind',
      'หนึ่งในคดีฆาตกรรมไสยศาสตร์ที่โด่งดังที่สุดในประวัติศาสตร์อเมริกา เกิดขึ้นในเดือนพฤศจิกายน 1928 ในแถบเพนซิลเวเนียดัตช์ เมื่อจอห์น บลายไมเยอร์ ชายหนุ่มที่เชื่อว่าตนเองถูกคำสาปมนต์ดำจากเนลสัน เรห์ไมเยอร์ หมอผีไสยศาสตร์พื้นบ้าน (Powwow) เขาและพวกอีกสองคนจึงบุกเข้าไปในบ้านไม้กลางป่าลึกของเรห์ไมเยอร์เพื่อหาหนังสือมนต์ดำและเส้นผมมาทำพิธีถอนคำสาป จนเกิดการต่อสู้และสังหารเรห์ไมเยอร์อย่างโหดเหี้ยมก่อนจุดไฟเผาบ้าน กลายเป็นตำนานอาถรรพ์ของหุบเขาเฮ็กซ์ฮอลโลว์ที่ยังคงมีวิญญาณวนเวียนอยู่',
      'The Hex Hollow Murder of 1928 remains America''s most sensational folklore homicide. Believing he was cursed with poverty and illness by reclusive Pennsylvania Dutch folk-healer (Powwow practitioner) Nelson Rehmeyer, John Blymire and two accomplices invaded Rehmeyer''s remote farmhouse to steal his spellbook, ''The Long Lost Friend''. The confrontation ended in Rehmeyer''s brutal murder and a failed arson, leaving the hollow haunted by dark sorcery lore.',
      'คดีนี้เปิดเผยความเชื่อเรื่องไสยศาสตร์พื้นบ้านพาววา (Powwowing) ที่สืบทอดมาจากเยอรมนีในชุมชนเพนซิลเวเนียดัตช์ และดึงดูดความสนใจจากสื่อทั่วโลก',
      'The trial illuminated centuries of German folk magic beliefs in modern America, inspiring books, films, and paranormal investigations around the surviving Rehmeyer homestead.',
      'ห้ามอ่านมนต์ดำในหนังสือ ''เพื่อนผู้สาบสูญ'' (The Long Lost Friend) ในยามค่ำคืนในหุบเขา',
      'Do not recite Powwow incantations from ''The Long Lost Friend'' within Rehmeyer''s Hollow after dark.',
      'https://i.ytimg.com/vi/erVNJTuT5PM/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/erVNJTuT5PM/hqdefault.jpg","title":"คดีฆาตกรรมเฮ็กซ์ฮอลโลว์ (คำสาปหมอผีพาววาแห่งยอร์กเคาน์ตี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=erVNJTuT5PM","title":"Hex Hollow | Documentary | Full Movie | Pennsylvania Witch Hunt","thumbnail":"https://i.ytimg.com/vi/erVNJTuT5PM/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-manchac-swamp-voodoo-julia-brown',
      'คำสาปบึงแมนแชคของจูเลีย บราวน์ (คำพยากรณ์มรณะแห่งหนองน้ำลุยเซียนา)',
      'The Curse of Manchac Swamp (Aunt Julia Brown''s Voodoo Hex)',
      'curse',
      'ลุยเซียนา',
      'Louisiana',
      'บึงแมนแชค แซงต์จอห์นเดอะแบปทิสต์',
      'Manchac Swamp, St. John the Baptist',
      30.2922,
      -90.3958,
      'water_spirit',
      'ในป่าพรุแมนแชค รัฐลุยเซียนา มีเรื่องเล่าของ ''ป้าจูเลีย บราวน์'' หมอผีวูดูที่มักร้องเพลงเล่นกีตาร์อยู่หน้าระเบียงบ้านริมน้ำ เธอทำนายอนาคตและรักษาโรคให้ชาวบ้าน แต่เมื่อรู้สึกว่าผู้คนไม่กตัญญู เธอจึงร้องเพลงทำนายว่า ''เมื่อฉันตาย ฉันจะพาทุกคนในเมืองไปด้วย'' ในวันที่ 29 กันยายน 1915 วันที่มีพิธีฝังศพของเธอ พายุเฮอริเคนระดับ 4 ได้พัดถล่มบึงแมนแชค ทำให้เกิดคลื่นยักษ์กวาดล้างหมู่บ้านเฟรเนียร์และรูดด็อกจนราบคาบ มีผู้เสียชีวิตหลายร้อยคนตามคำสาปของเธอ',
      'Deep within Manchac Swamp lies the watery graveyard of Frenier, Louisiana. Aunt Julia Brown, a revered yet feared local Voodoo priestess, used to sing ominous verses on her porch: ''One day I''m gonna die, and I''m gonna take all of you with me.'' On the exact day of her funeral in September 1915, a ferocious Category 4 hurricane tore through the cypress swamps, generating a tidal surge that wiped out the entire community, claiming hundreds of lives.',
      'ร่างของผู้เสียชีวิตจากพายุเฮอริเคนปี 1915 ถูกฝังรวมกันในหลุมศพนิรนามกลางป่าพรุ ทัวร์ล่องเรือบึงแมนแชคยังคงได้ยินเสียงหัวเราะและเสียงเพลงของป้าจูเลียแว่วมาตามสายลม',
      'Mass graves of the 1915 hurricane victims lie hidden beneath moss-draped cypress trees; swamp boat captains frequently report eerie guitar strums and female voices floating across the bayou.',
      'ห้ามร้องเพลงคำทำนายของจูเลีย บราวน์ ขณะล่องเรือในบึงแมนแชค',
      'Never chant or sing Aunt Julia Brown''s funeral verses while navigating Manchac Swamp.',
      'https://i.ytimg.com/vi/_5lO-fLWdYM/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/_5lO-fLWdYM/hqdefault.jpg","title":"คำสาปบึงแมนแชคของจูเลีย บราวน์ (คำพยากรณ์มรณะแห่งหนองน้ำลุยเซียนา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=_5lO-fLWdYM","title":"The Voodoo Priestess who Destroyed her Town | Julia Brown","thumbnail":"https://i.ytimg.com/vi/_5lO-fLWdYM/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-pirates-house-savannah-rum',
      'โรงเตี๊ยมโจรสลัดแห่งซาวันนาห์ (อุโมงค์ลักพาตัวและคำสาปเหล้ารัม)',
      'The Pirates'' House of Savannah (The Shanghai Tunnel Curse)',
      'curse',
      'จอร์เจีย',
      'Georgia',
      'เมืองซาวันนาห์ ชัทแฮม',
      'Savannah, Chatham County',
      32.0772,
      -81.0844,
      'creepy_wind',
      'อาคารที่เก่าแก่ที่สุดแห่งหนึ่งในรัฐจอร์เจีย ก่อตั้งขึ้นในปี 1753 เพื่อเป็นโรงเตี๊ยมสำหรับกะลาสีและโจรสลัด ใต้ถุนอาคารมีอุโมงค์ลับเชื่อมต่อไปยังแม่น้ำซาวันนาห์ ซึ่งถูกใช้เป็นเส้นทางลักพาตัวกะลาสีขี้เมา (Shanghaiing) ขึ้นเรือสินค้า ตำนานเล่าว่ากัปตันฟลินต์ ตัวละครโจรสลัดชื่อดังจากวรรณกรรม Treasure Island ได้สิ้นใจในห้องชั้นบนของโรงเตี๊ยมแห่งนี้หลังดื่มเหล้ารัมจนหมด และวิญญาณของเขายังคงสิงสู่อยู่พร้อมกับส่งเสียงตะโกนเรียก ''ดาร์บี มักกรอว์ ขอน้ำรัมอีกขวด!''',
      'Operating since 1753, The Pirates'' House in Savannah was a notorious sailors'' inn famous for illicit shanghaiing tunnels running straight to the Savannah River. Robert Louis Stevenson even immortalized the tavern in ''Treasure Island'' as the final dying place of the ruthless Captain Flint. Staff and guests frequently experience apparitions of peg-legged buccaneers and phantom curses demanding rum echoing from the cellar.',
      'อุโมงค์โบราณใต้ดินยังคงปรากฏให้เห็นบางส่วน และได้รับการจัดอันดับให้เป็นหนึ่งในสถานที่ผีดุที่มีประวัติศาสตร์มืดมนที่สุดของเมืองซาวันนาห์',
      'Original rum cellars and shanghaiing trapdoors remain preserved inside the restaurant, frequently visited by ghost tours investigating spectral manifestations.',
      'ห้ามหยิบฉวยเหรียญหรือสิ่งของโบราณในอุโมงค์ใต้ดินโรงเตี๊ยมโจรสลัด',
      'Never pocket artifacts or undisturbed relics from the historic shanghai tunnel cellar.',
      'https://i.ytimg.com/vi/VemCsCPksGM/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/VemCsCPksGM/hqdefault.jpg","title":"โรงเตี๊ยมโจรสลัดแห่งซาวันนาห์ (อุโมงค์ลักพาตัวและคำสาปเหล้ารัม)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=VemCsCPksGM","title":"The Pirates House | Savannah Hauntings Series","thumbnail":"https://i.ytimg.com/vi/VemCsCPksGM/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-hulk-prison-ships-wallabout',
      'เรือนจำลอยน้ำแห่งวอลลาเบาต์ (คำสาปหมื่นวิญญาณแห่งสงครามกู้ชาติ)',
      'The Wallabout Bay Prison Ships (The Hex of HMS Jersey)',
      'curse',
      'นิวยอร์ก',
      'New York',
      'อ่าววอลลาเบาต์ บรูกลิน',
      'Wallabout Bay, Brooklyn',
      40.7042,
      -73.9744,
      'jungle_curse',
      'ในช่วงสงครามปฏิวัติอเมริกา กองทัพอังกฤษใช้เรือรบเก่าดัดแปลงเป็นเรือนจำลอยน้ำ จอดทอดสมออยู่ในอ่าววอลลาเบาต์ (บรูกลินในปัจจุบัน) ลำที่น่าสะพรึงกลัวที่สุดคือเรือ HMS Jersey หรือ ''นรกบนน้ำ'' นักโทษชาวอเมริกันกว่า 11,000 คนต้องทนทุกข์ทรมานจากความอดอยาก โรคระบาด และการทรมานจนเสียชีวิต ศพของพวกเขาถูกโยนทิ้งลงในโคลนริมชายฝั่ง เชื่อกันว่าผืนน้ำแห่งนี้เต็มไปด้วยความเคียดแค้นและมีวิญญาณนักโทษคอยวนเวียนร้องขอความยุติธรรม',
      'During the American Revolutionary War, the British military moored rotten, decommissioned warships in Brooklyn''s Wallabout Bay to house prisoners of war. The most notorious, HMS Jersey (''Hell afloat''), was a floating slaughterhouse where over 11,000 patriots perished from yellow fever, dysentery, and starvation. The mudflats were choked with skeletal remains, inspiring dark urban folklore of vengeful spirits haunting the Brooklyn Navy Yard.',
      'อนุสาวรีย์ Prison Ship Martyrs'' Monument ถูกสร้างขึ้นในสวนสาธารณะฟอร์ตกรีน เพื่อเก็บรวบรวมโครงกระดูกของเหล่าวีรชนที่ขุดพบจากอ่าววอลลาเบาต์',
      'The Fort Greene Prison Ship Martyrs'' Monument enshrines crypts containing bone fragments washed ashore long after the infamous British hulks were burned.',
      'ห้ามทิ้งขยะหรือกระทำการดูหมิ่นบริเวณอนุสรณ์สถานคุกเรือลอยน้ำ',
      'Show solemn reverence when standing near the martyrs'' crypt at Fort Greene.',
      'https://i.ytimg.com/vi/eEbrLrZFccI/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/eEbrLrZFccI/hqdefault.jpg","title":"เรือนจำลอยน้ำแห่งวอลลาเบาต์ (คำสาปหมื่นวิญญาณแห่งสงครามกู้ชาติ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=eEbrLrZFccI","title":"The HMS Jersey | American rebels starved to death aboard a notorious prison ship | HIH Ep. 11","thumbnail":"https://i.ytimg.com/vi/eEbrLrZFccI/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-cursed-portrait-delphine-lalaurie',
      'ภาพวาดคำสาปมาดามลาลอรี (อาถรรพ์ใบหน้าปีศาจแห่งนิวออร์ลีนส์)',
      'The Cursed Portrait of Madame LaLaurie (The Screaming Canvas)',
      'curse',
      'ลุยเซียนา',
      'Louisiana',
      'เฟรนช์ควอเตอร์ นิวออร์ลีนส์',
      'French Quarter, New Orleans',
      29.9614,
      -90.0617,
      'creepy_wind',
      'ภาพวาดสีน้ำมันโบราณรูปมาดามเดลฟีน ลาลอรี สตรีชนชั้นสูงชาวฝรั่งเศสผู้ก่อคดีทรมานทาสอย่างโหดเหี้ยมในคฤหาสน์ของเธอในปี 1834 ภาพวาดนี้ถูกส่งต่อมายังผู้ครอบครองหลายคนในนิวออร์ลีนส์ และสร้างความสยองขวัญให้กับเจ้าของบ้านทุกคน มีรายงานว่าดวงตาของเธอในภาพจะกะพริบ ใบหน้าจะค่อยๆ บิดเบี้ยวเป็นภาพหัวกะโหลก และมักเกิดเพลิงไหม้หรือข้าวของแตกกระจายในห้องที่แขวนภาพวาดนี้ไว้ จนในที่สุดไม่มีใครกล้านำภาพนี้ไปไว้ในบ้านอีกต่อไป',
      'Madame Delphine LaLaurie remains New Orleans'' most infamous historic sadist following the 1834 discovery of tortured enslaved captives in her Royal Street mansion. A cursed vintage portrait depicting LaLaurie is reputed to cause horrific poltergeist activity: moving across walls, shifting into a demonic scowl, and sparking spontaneous electrical fires in whatever private gallery or home dares to display it.',
      'คฤหาสน์ลาลอรีในย่านเฟรนช์ควอเตอร์ได้รับการขนานนามว่าเป็นบ้านผีดุที่สุดในอเมริกา และภาพวาดจำลองของเธอมักถูกนำมาแสดงในพิพิธภัณฑ์ลี้ลับ',
      'The LaLaurie mansion on 1140 Royal Street has changed hands dozens of times (even owned briefly by actor Nicolas Cage), forever tethered to stories of psychic trauma and cursed artwork.',
      'ห้ามจ้องตาภาพวาดมาดามลาลอรีตรงๆ ในความมืด',
      'Never stare unblinking into the eyes of Madame LaLaurie''s likeness in candle-lit rooms.',
      'https://i.ytimg.com/vi/NxBEOLA5m8I/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/NxBEOLA5m8I/hqdefault.jpg","title":"ภาพวาดคำสาปมาดามลาลอรี (อาถรรพ์ใบหน้าปีศาจแห่งนิวออร์ลีนส์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=NxBEOLA5m8I","title":"The Dark & Sinister Crimes of Delphine LaLaurie | The Haunted Mansion of New Orleans","thumbnail":"https://i.ytimg.com/vi/NxBEOLA5m8I/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-grave-of-midnight-mary-new-haven',
      'หลุมศพมิดไนท์แมรี่ (คำสาปฝังทั้งเป็นแห่งสุสานเอเวอร์กรีน)',
      'The Curse of Midnight Mary (The Buried Alive Hex of Evergreen)',
      'curse',
      'คอนเนตทิคัต',
      'Connecticut',
      'เมืองนิวฮาเวน',
      'New Haven, New Haven County',
      41.3083,
      -72.9417,
      'creepy_wind',
      'ป้ายหลุมศพหินสีชมพูขนาดใหญ่ของแมรี่ อี. ฮาร์ท ในสุสานเอเวอร์กรีน เมืองนิวฮาเวน รัฐคอนเนตทิคัต ผู้เสียชีวิตเมื่อวันที่ 15 ตุลาคม 1872 ด้วยวัย 47 ปี ข้อความบนแผ่นหินจารึกคำเตือนอันน่าขนลุกว่า ''ผู้คนทั้งหลายโปรดจำไว้ เมื่อท่านเดินผ่านไป ชะตากรรมที่น่าสะพรึงกลัวที่สุดกำลังรอคอยผู้ที่ทำร้ายข้า'' ตำนานเล่าว่าเธอตกอยู่ในภาวะโคม่าแต่ถูกเข้าใจผิดว่าตายและถูกฝังทั้งเป็น เธอกรีดร้องและสาปแช่งอยู่ในโลงศพใต้ดิน เชื่อว่าหากใครไปเคาะหลุมศพของเธอในยามเที่ยงคืนจะถูกดึงวิญญาณลงสู่ความตาย',
      'The colossal pink granite monument of Mary E. Hart in New Haven''s Evergreen Cemetery bears one of the most chilling epitaphs in the world: ''The people at midnight from the most hallowed rest were taken away...''. Folklore recounts that Mary was buried alive during a cataleptic trance. Known as ''Midnight Mary'', local superstition warns that striking her tombstone at the stroke of midnight guarantees a fatal accident before sunrise.',
      'ข้อความบนป้ายหลุมศพที่คลุมเครือและมีคำว่า ''Midnight'' ทำให้เกิดตำนานสยองขวัญในหมู่นักศึกษามหาวิทยาลัยเยลที่อยู่ใกล้เคียงมาหลายชั่วอายุคน',
      'Generations of Yale students and Connecticut youths have traded dares to visit the towering pink tombstone at midnight, fueling dozens of eerie urban legends.',
      'ห้ามเคาะป้ายหลุมศพของมิดไนท์แมรี่ในเวลาเที่ยงคืน',
      'Never knock on the pink granite slab of Midnight Mary when the church bells toll twelve.',
      'https://i.ytimg.com/vi/Ef3dwWDl6IE/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/Ef3dwWDl6IE/hqdefault.jpg","title":"หลุมศพมิดไนท์แมรี่ (คำสาปฝังทั้งเป็นแห่งสุสานเอเวอร์กรีน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=Ef3dwWDl6IE","title":"LEGEND OF MIDNIGHT MARY! | EVERGREEN CEMETERY","thumbnail":"https://i.ytimg.com/vi/Ef3dwWDl6IE/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-tomb-of-al-khasneh-petra',
      'คำสาปมหาสมบัติอัล-คาซเนห์ (รอยกระสุนแห่งวิหารเปตรา)',
      'The Curse of Al-Khazneh (The Bullet-Scarred Urn of Petra)',
      'curse',
      'มาอัน',
      'Ma''an',
      'นครหินโบราณเปตรา วาดีมูซา',
      'Petra, Wadi Musa',
      30.3222,
      35.4517,
      'temple_bell',
      'วิหารหินสลักหน้าผาสีชมพูอันงดงาม ''อัล-คาซเนห์'' (Al-Khazneh) หรือคลังสมบัติของฟาโรห์แห่งนครเปตรา ประเทศจอร์แดน ยอดบนสุดของวิหารมีโถหินโบราณขนาดใหญ่ ซึ่งชนเผ่าเบดูอินในอดีตเชื่อว่าเป็นที่ซ่อนทองคำของฟาโรห์อียิปต์ผู้ใช้เวทมนตร์สร้างวิหาร นักรบเผ่าเบดูอินจึงใช้ปืนยิงกระหน่ำใส่โถหินเพื่อหวังให้ทองคำทะลักออกมา แต่แท้จริงโถนั้นเป็นหินทรายตัน ตำนานเล่าว่าผู้ที่ยิงปืนใส่โถหินศักดิ์สิทธิ์ต่างต้องเผชิญกับคำสาปแห่งทะเลทราย ล้มป่วยด้วยโรคประหลาดและสูญสิ้นวงศ์ตระกูล',
      'Al-Khazneh (''The Treasury'') is the breathtaking rock-cut temple carved into the rose-red cliffs of Petra. Crowning the upper facade is a giant ornamental sandstone funerary urn. Local Bedouin tribes historically believed the urn concealed the magical gold hoard of an Egyptian Pharaoh, repeatedly firing rifles at the carving to break it open. The bullet pockmarks remain visible today, accompanied by legends of deadly desert plagues afflicting those who shot at the urn.',
      'รอยกระสุนปืนจากศตวรรษที่ 19 ยังคงปรากฏเป็นรอยพรุนชัดเจนบนโถหินทราย เป็นอนุสรณ์ของความละโมบและตำนานอาถรรพ์แห่งเปตรา',
      'Heavy rifle bullet scars riddle the solid stone urn to this day, an enduring physical testament to Bedouin folklore and archaeological treasure hunts.',
      'ห้ามยิงปืนหรือปีนป่ายขึ้นไปบนซุ้มหินโบราณของวิหารอัล-คาซเนห์',
      'Do not climb or attempt to damage the sacred funerary urn carved high upon the Treasury.',
      'https://i.ytimg.com/vi/PDP5P2cRjLg/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/PDP5P2cRjLg/hqdefault.jpg","title":"คำสาปมหาสมบัติอัล-คาซเนห์ (รอยกระสุนแห่งวิหารเปตรา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=PDP5P2cRjLg","title":"What Was Petra’s Treasury Really Built For? | Forbidden Mysteries","thumbnail":"https://i.ytimg.com/vi/PDP5P2cRjLg/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-devils-chair-cassadaga-florida',
      'เก้าอี้พญามารแห่งแคสซาดากา (เก้าอี้อาถรรพ์แห่งค่ายคนทรง)',
      'The Devil''s Chair of Cassadaga (The Haunted Cemetery Throne)',
      'curse',
      'ฟลอริดา',
      'Florida',
      'แคสซาดากา วอลูเซีย',
      'Cassadaga, Volusia County',
      28.9667,
      -81.2333,
      'creepy_wind',
      'ในสุสานเลกเฮเลน-แคสซาดากา ใกล้กับหมู่บ้านคนทรงวิญญาณที่มีชื่อเสียงระดับโลกในรัฐฟลอริดา มีเก้าอี้หินอนุสรณ์ทรงบัลลังก์ตั้งอยู่ข้างหลุมศพ ชาวบ้านขนานนามมันว่า ''เก้าอี้ของพญามาร'' ตำนานเล่าว่าในยามเที่ยงคืน ซาตานจะลงมานั่งบนเก้าอี้ตัวนี้เพื่อฟังเสียงสวดของคนตาย หากใครวางกระป๋องเบียร์ที่ยังไม่เปิดไว้บนเก้าอี้ข้ามคืน รุ่งเช้าจะพบว่าเบียร์ในกระป๋องว่างเปล่าโดยไม่มีรอยเปิด และหากใครกล้านั่งลงบนเก้าอี้ตอนเที่ยงคืนจะได้ยินเสียงกระซิบแห่งความบ้าคลั่ง',
      'In the cemetery bordering Cassadaga, the famed psychic capital of the world in central Florida, sits a brick and stone mourning bench known as the Devil''s Chair. Folklore claims that Satan himself visits the chair at midnight to converse with the spirits. Legend holds that leaving an unopened can of beer on the seat will result in the can being emptied by morning without breaking the seal, and sitting in it invites demonic auditory hallucinations.',
      'แคสซาดากาเป็นชุมชนผู้นับถือลัทธิวิญญาณนิยม (Spiritualist) ที่ก่อตั้งขึ้นในปี 1894 ทำให้พื้นที่นี้เต็มไปด้วยเรื่องเล่าเรื่องการสื่อสารกับคนตาย',
      'The town was founded in 1894 by medium George Colby; the cemetery chair remains one of Florida''s most notorious folkloric dare sites.',
      'ห้ามนั่งบนเก้าอี้หินแห่งแคสซาดากาในยามเที่ยงคืน',
      'Never sit upon the Devil''s Chair at the strike of midnight.',
      'https://i.ytimg.com/vi/Yyy8FUlbA8Q/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/Yyy8FUlbA8Q/hqdefault.jpg","title":"เก้าอี้พญามารแห่งแคสซาดากา (เก้าอี้อาถรรพ์แห่งค่ายคนทรง)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=Yyy8FUlbA8Q","title":"The Devils Chair.  Cassadaga, Florida. The most haunted cemetery in the United States. reup","thumbnail":"https://i.ytimg.com/vi/Yyy8FUlbA8Q/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-devils-hole-massacre-niagara',
      'ถ้ำเดวิลส์โฮล (คำสาปการสังหารหมู่แห่งโตรกผาไนแอการา)',
      'The Devil''s Hole Massacre (The Ambush of the Niagara Gorge)',
      'curse',
      'นิวยอร์ก',
      'New York',
      'โตรกผาไนแอการา ไนแอการา',
      'Niagara Gorge, Niagara County',
      43.1367,
      -79.0433,
      'creepy_wind',
      'ถ้ำหินปูนลึกลับริมโตรกผาแม่น้ำไนแอการา ชนเผ่าเซเนกา (Seneca) เชื่อว่าเป็นที่สถิตของอสูรปีศาจแห่งความชั่วร้าย ในวันที่ 14 กันยายน 1763 ระหว่างสงครามพอนทิแอก นักรบอินเดียนแดงได้ซุ่มโจมตีกองเกวียนทหารอังกฤษและผลักทหารพร้อมม้าตกลงไปในหน้าผาลึกกว่า 80 นายจนน้ำในลำธารกลายเป็นสีเลือดกลายเป็น ''บลัดดีรัน'' เชื่อกันว่าถ้ำแห่งนี้มีคำสาปของวิญญาณทหารที่ตายโหงคอยลากผู้มาเยือนให้พลัดตกหน้าผา',
      'Devil''s Hole is a dark cavern overlooking the Niagara River Gorge, revered by the Seneca as the domain of an evil spirit. On September 14, 1763, during Pontiac''s War, Seneca warriors executed a devastating ambush against a British supply convoy, massacring over 80 soldiers and driving wagons off the sheer cliff into Bloody Run ravine. The cavern is cursed with recurring visions of falling redcoat ghosts and sudden dizzying auras.',
      'ประธานาธิบดีโรเบิร์ต คาวาเลียร์ เดอ ลา ซาล เคยเข้าไปสำรวจถ้ำนี้และได้รับคำเตือนจากหมอผีพื้นเมืองว่าเขาจะพบจุดจบอันน่าเศร้า ซึ่งเขาก็ถูกลอบสังหารจริงในเวลาต่อมา',
      'French explorer La Salle visited the cave in 1679 against tribal warnings; local legend credits his subsequent murder by mutineers in Texas to the cavern''s lingering curse.',
      'ห้ามก้าวเข้าไปในโพรงถ้ำเดวิลส์โฮลเพียงลำพังหลังพระอาทิตย์ตกดิน',
      'Do not enter the mouth of Devil''s Hole cave alone after twilight.',
      'https://i.ytimg.com/vi/8Z0P9BfGQqw/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/8Z0P9BfGQqw/hqdefault.jpg","title":"ถ้ำเดวิลส์โฮล (คำสาปการสังหารหมู่แห่งโตรกผาไนแอการา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=8Z0P9BfGQqw","title":"Cursed Mysteries Behind Niagara Falls - The Devils Hole - Channel IGM","thumbnail":"https://i.ytimg.com/vi/8Z0P9BfGQqw/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-black-hope-cemetery-crosby',
      'หมู่บ้านแบล็กโฮป (คำสาปสร้างบ้านทับสุสานทาสแห่งเท็กซัส)',
      'The Curse of Black Hope Cemetery (The Haunting of Poindexter)',
      'curse',
      'เท็กซัส',
      'Texas',
      'ครอสบี แฮร์ริส',
      'Crosby, Harris County',
      29.9133,
      -95.0617,
      'creepy_wind',
      'เรื่องราวสยองขวัญที่เกิดขึ้นจริงในยุคทศวรรษ 1980 ในหมู่บ้านจัดสรรโพอินเดกซ์เตอร์ เมืองครอสบี รัฐเท็กซัส เมื่อครอบครัวฮานีย์และครอบครัววิลเลียมส์ซื้อที่ดินสร้างบ้านและสระว่ายน้ำ แต่ระหว่างขุดดินกลับพบโครงกระดูกมนุษย์และป้ายหลุมศพไม้ผุพังจำนวนมาก ปรากฏว่าหมู่บ้านแห่งนี้สร้างทับสุสานโบราณของทาสผิวดำชื่อ ''แบล็กโฮป'' หลังจากนั้นทุกครอบครัวต้องเผชิญกับปรากฏการณ์ผีหลอกหลอนขั้นรุนแรง คนในบ้านล้มป่วยด้วยโรคมะเร็งและเสียชีวิตอย่างรวดเร็ว จนกลายเป็นคดีฟ้องร้องประวัติศาสตร์',
      'In the 1980s, residents of the Newport subdivision in Crosby, Texas, began digging backyard pools only to uncover pine coffins and human remains from a forgotten historic Black cemetery known as Black Hope. The desecration triggered terrifying poltergeist manifestations, unexplainable electrical phenomena, and an extraordinary cluster of sudden, fatal illnesses among families living directly over the unmarked graves.',
      'ครอบครัวผู้เสียหายชนะคดีทางกฎหมายบางส่วน และเรื่องราวได้รับการบันทึกเป็นหนังสือและภาพยนตร์สารคดี ''The Black Hope Horror''',
      'The harrowing ordeal was chronicled in the bestselling book ''The Black Hope Horror'' and dramatized in television specials as one of America''s definitive desecrated cemetery accounts.',
      'ห้ามขุดดินหรือเคลื่อนย้ายป้ายหลุมศพในเขตสุสานเก่าแบล็กโฮป',
      'Never desecrate or excavate unmarked cemetery plots in Crosby.',
      'https://i.ytimg.com/vi/d-VEoIHUGzk/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/d-VEoIHUGzk/hqdefault.jpg","title":"หมู่บ้านแบล็กโฮป (คำสาปสร้างบ้านทับสุสานทาสแห่งเท็กซัส)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=d-VEoIHUGzk","title":"Black Hope Curse","thumbnail":"https://i.ytimg.com/vi/d-VEoIHUGzk/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-curse-of-the-bambino-boston',
      'คำสาปแห่งแบมบิโน (อาถรรพ์ 86 ปีแห่งทีมเรดซ็อกซ์)',
      'The Curse of the Bambino (The 86-Year Red Sox Hex)',
      'curse',
      'แมสซาชูเซตส์',
      'Massachusetts',
      'สนามเฟนเวย์พาร์ก บอสตัน',
      'Fenway Park, Boston',
      42.3467,
      -71.0972,
      'jungle_curse',
      'หนึ่งในคำสาปที่โด่งดังที่สุดในประวัติศาสตร์กีฬาโลก เริ่มต้นในปี 1920 เมื่อเจ้าของทีมเบสบอล บอสตัน เรดซ็อกซ์ ตัดสินใจขาย ''เบบ รูธ'' (เจ้าของฉายา เดอะ แบมบิโน) ให้กับทีมคู่ปรับอย่าง นิวยอร์ก แยงกีส์ เพื่อนำเงินไปลงทุนในละครบรอดเวย์ หลังจากนั้นเรดซ็อกซ์ที่เคยเป็นแชมป์โลกเวิลด์ซีรีส์หลายสมัยกลับตกอยู่ในคำสาปไม่เคยชนะเลิศเลยนานถึง 86 ปี เผชิญกับโชคร้ายและข้อผิดพลาดเหลือเชื่อในวินาทีสุดท้ายซ้ำแล้วซ้ำเล่า จนกระทั่งสามารถล้างคำสาปได้สำเร็จในปี 2004',
      'The Curse of the Bambino is legendary baseball folklore explaining the 86-year championship drought of the Boston Red Sox. Initiated when owner Harry Frazee sold superstar Babe Ruth to the New York Yankees in 1920 to finance a Broadway musical, the Red Sox endured decades of heartbreaking, improbable postseason collapses (such as the 1986 Bill Buckner error) until finally exorcising the hex in 2004.',
      'แฟนเบสบอลเคยทำพิธีถอนคำสาปสารพัดวิธี ทั้งการงมเปียโนของเบบ รูธ ขึ้นมาจากบ่อน้ำ และการนำหมอผีมาทำพิธีชำระล้างบนหลังคาสนามเฟนเวย์พาร์ก',
      'From throwing exorcism rituals atop Fenway Park to retrieving an alleged Babe Ruth piano from a pond, the legend became deeply woven into American popular culture.',
      'ห้ามนำเสื้อแข่งนิวยอร์กแยงกีส์ไปฝังไว้ใต้คอนกรีตสนามเฟนเวย์พาร์ก',
      'Never bury rival memorabilia beneath the foundations of Fenway Park.',
      'https://i.ytimg.com/vi/QPht0ZlbUX8/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/QPht0ZlbUX8/hqdefault.jpg","title":"คำสาปแห่งแบมบิโน (อาถรรพ์ 86 ปีแห่งทีมเรดซ็อกซ์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=QPht0ZlbUX8","title":"HBO Sports - The Curse Of The Bambino (2003)","thumbnail":"https://i.ytimg.com/vi/QPht0ZlbUX8/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-franklin-lost-expedition-arctic',
      'คำสาปคณะสำรวจแฟรงคลิน (โศกนาฏกรรมเรือเอเรบัสและเทอร์เรอร์)',
      'The Curse of the Franklin Expedition (The Arctic Ice Trap)',
      'curse',
      'นูนาวุต',
      'Nunavut',
      'เกาะคิงวิลเลียม มหาสมุทรอาร์กติก',
      'King William Island, Arctic Ocean',
      68.95,
      -98.8833,
      'creepy_wind',
      'ในปี 1845 เซอร์จอห์น แฟรงคลิน นำเรือสำรวจราชนาวีอังกฤษสองลำคือ HMS Erebus และ HMS Terror พร้อมลูกเรือ 129 นาย ออกเดินทางเพื่อค้นหาเส้นทางเดินเรือเฉียงเหนือผ่านอาร์กติก แต่เรือทั้งสองลำกลับติดอยู่ในแผ่นน้ำแข็งขั้วโลกอันหนาวเหน็บนานกว่าสองปี ลูกเรือทั้งหมดต้องเผชิญกับความหนาวติดลบ พิษจากสารตะกั่วในอาหารกระป๋อง ความคุ้มคลั่ง และการกินเนื้อพวกเดียวกันเองจนเสียชีวิตหมดทั้งคณะ ชาวอินูอิตเล่าว่าวิญญาณของพวกเขายังคงเดินแถวโซซัดโซเซอยู่บนผืนน้ำแข็งสีขาวอันไร้ที่สิ้นสุด',
      'In 1845, Sir John Franklin led 129 men aboard HMS Erebus and HMS Terror into the Canadian Arctic to chart the Northwest Passage. Trapped in pack ice off King William Island for years, the crew succumbed to starvation, scurvy, hypothermia, lead poisoning, and cannibalism. Inuit oral histories preserved memories of desperate, emaciated ghosts wandering the barren tundra, creating an enduring saga of frozen tragedy.',
      'ซากเรือเอเรบัสและเทอร์เรอร์ถูกค้นพบในปี 2014 และ 2016 ภายใต้ความร่วมมือกับผู้เฒ่าชาวอินูอิตที่บอกเล่าตำแหน่งตามคำบอกเล่าของบรรพบุรุษ',
      'The historic shipwrecks were rediscovered in 2014 and 2016, guided by centuries-old Inuit oral histories that preserved the exact locations of the sunken vessels.',
      'ห้ามรบกวนกองหินหรือหลุมศพของคณะสำรวจแฟรงคลินบนเกาะร้างขั้วโลก',
      'Do not disturb the lonely stone cairns and graves of Franklin''s crew on the frozen tundra.',
      'https://i.ytimg.com/vi/8q4e89BmcIg/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/8q4e89BmcIg/hqdefault.jpg","title":"คำสาปคณะสำรวจแฟรงคลิน (โศกนาฏกรรมเรือเอเรบัสและเทอร์เรอร์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=8q4e89BmcIg","title":"The Disturbing Disappearance of the Franklin Expedition","thumbnail":"https://i.ytimg.com/vi/8q4e89BmcIg/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-dead-mans-island-halifax',
      'เกาะคนตายแห่งแฮลิแฟกซ์ (คำสาปสุสานนักโทษสงครามเมลวิลล์)',
      'The Curse of Dead Man''s Island (The Melville Island Prison Hex)',
      'curse',
      'โนวาสโกเชีย',
      'Nova Scotia',
      'อ่าวทวิลลิงเกต แฮลิแฟกซ์',
      'Northwest Arm, Halifax',
      44.6311,
      -63.6067,
      'jungle_curse',
      'เกาะเล็กๆ ริมอ่าวนอร์ธเวสต์อาร์ม ในเมืองแฮลิแฟกซ์ ประเทศแคนาดา ในช่วงสงครามปี 1812 เกาะเมลวิลล์ที่อยู่ติดกันถูกใช้เป็นเรือนจำคุมขังนักโทษสงครามชาวอเมริกันและทหารฝรั่งเศส นักโทษหลายร้อยคนที่เสียชีวิตจากโรคไข้รากสาดใหญ่และความเป็นอยู่อันเลวร้ายถูกนำมาฝังไว้บนเกาะแห่งนี้โดยไม่มีป้ายชื่อ ชาวบ้านเล่าขานว่าผืนดินของเกาะเต็มไปด้วยอาถรรพ์ มีพยานพบเห็นเงาร่างโปร่งแสงสวมเครื่องแบบทหารโบราณเดินขึ้นมาจากชายหาดในคืนหมอกลงหนาทึบ',
      'Deadman''s Island is a secluded point in Halifax''s Northwest Arm used as an unmarked burial ground for American and French prisoners of war imprisoned on adjacent Melville Island during the War of 1812. Nearly 200 captives who died of typhus were interred in shallow, unmarked graves. Local maritime folklore speaks of spectral military figures patrolling the misty shoreline and ghostly moans carrying over the water.',
      'เกาะแห่งนี้เกือบถูกนำไปพัฒนาเป็นโครงการอสังหาริมทรัพย์ในทศวรรษ 1990 แต่ชาวเมืองและนักประวัติศาสตร์ได้ร่วมกันอนุรักษ์ไว้เป็นอนุสรณ์สถานศักดิ์สิทธิ์',
      'Citizens successfully halted residential development in the 1990s, preserving Deadman''s Island as a historic memorial park honoring the interred soldiers.',
      'ห้ามขุดดินหรือส่งเสียงเอะอะในบริเวณหลุมศพนิรนามบนเกาะคนตาย',
      'Maintain strict silence and do not disturb the unmarked earth across Deadman''s Island.',
      'https://i.ytimg.com/vi/72Ilzyz1XsQ/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/72Ilzyz1XsQ/hqdefault.jpg","title":"เกาะคนตายแห่งแฮลิแฟกซ์ (คำสาปสุสานนักโทษสงครามเมลวิลล์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=72Ilzyz1XsQ","title":"Connaught Battery & Deadman''s Island  -  WW 1 Guns & P.O.W. Grave Sites From The War of 1812","thumbnail":"https://i.ytimg.com/vi/72Ilzyz1XsQ/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-cursed-phone-number-bulgaria',
      'หมายเลขโทรศัพท์มรณะ 0888 (คำสาปเบอร์โทรสังหารแห่งบัลแกเรีย)',
      'The 0888 Cursed Phone Number (The Bulgarian Mobile Death Hex)',
      'curse',
      'โซเฟีย',
      'Sofia',
      'กรุงโซเฟีย',
      'Sofia City',
      42.6977,
      23.3219,
      'whisper',
      'หมายเลขโทรศัพท์มือถือ ''+359 888 888 888'' ของบริษัทโมบิเทลในประเทศบัลแกเรีย กลายเป็นหนึ่งในตำนานร่วมสมัยที่น่าสะพรึงกลัวที่สุด เมื่อผู้ครอบครองหมายเลขนี้ทุกคนต่างเสียชีวิตอย่างกะทันหันในเวลาอันสั้น เริ่มจากซีอีโอของบริษัทที่เสียชีวิตด้วยโรคมะเร็งชนิดร้ายแรงในวัย 48 ปี ต่อมาหัวหน้าแก๊งมาเฟียที่ได้รับเบอร์นี้ถูกมือปืนลอบสังหาร และผู้ครอบครองคนที่สามซึ่งเป็นพ่อค้าของเถื่อนก็ถูกยิงเสียชีวิตหน้าร้านอาหาร จนในที่สุดบริษัทต้องตัดสินใจระงับหมายเลขนี้อย่างถาวร',
      'The Bulgarian mobile phone number ''+359 888 888 888'' achieved infamous folklore status in the 2000s after every individual assigned the digits met a sudden, violent demise. Beginning with Mobitel''s former CEO Vladimir Grashnov, who died of sudden cancer at 48, the number was reassigned to a mafia lord gunned down in Amsterdam, and then a contraband trafficker assassinated in Sofia, prompting the telecom to permanently suspend the cursed number.',
      'เมื่อมีคนโทรเข้าเบอร์นี้ในปัจจุบัน จะได้ยินเพียงข้อความอัตโนมัติแจ้งว่า ''หมายเลขนี้อยู่นอกพื้นที่ให้บริการ'' โดยบริษัทปฏิเสธที่จะให้สัมภาษณ์ถึงเหตุผล',
      'Callers dialing the number are met with a standard recorded message stating the telephone is out of network coverage, cementing its status as an internet horror legend.',
      'ห้ามพยายามโทรออกหรือเปิดใช้งานหมายเลข 0888 888 888',
      'Do not attempt to dial or reactivate the suspended 0888 mobile death sequence.',
      'https://i.ytimg.com/vi/M0yhcEs8uao/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/M0yhcEs8uao/hqdefault.jpg","title":"หมายเลขโทรศัพท์มรณะ 0888 (คำสาปเบอร์โทรสังหารแห่งบัลแกเรีย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=M0yhcEs8uao","title":"Calling Scary Number (0888-888-888) From Bulgaria Again","thumbnail":"https://i.ytimg.com/vi/M0yhcEs8uao/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-bleeding-column-san-clemente',
      'เสาหินหลั่งเลือดแห่งซานเคลเมนเต (คำสาปมรณะแห่งบาซิลิกาโบราณ)',
      'The Bleeding Column of San Clemente (The Weeping Pillar of Rome)',
      'curse',
      'โรม',
      'Rome',
      'บาซิลิกาซานเคลเมนเต อัลเล ลาเตรัสต์',
      'Piazza di San Clemente, Rome',
      41.8894,
      12.4975,
      'whisper',
      'ใต้บาซิลิกาซานเคลเมนเตในกรุงโรม ซึ่งสร้างซ้อนทับกันถึงสามชั้นย้อนไปถึงวิหารบูชาเทพมิธรัสในยุคโรมันโบราณ มีเสาหินโบราณต้นหนึ่งในห้องใต้ดินลึกที่ชาวบ้านเชื่อว่ามีหยดของเหลวสีแดงคล้ายเลือดซึมออกมาจากเนื้อหินในวันครบรอบการทรมานของนักบุญ ตำนานเล่าว่าเสาต้นนี้เคยถูกใช้เป็นหลักประหารและมัดนักโทษในยุคจักรวรรดิโรมัน ผู้ที่สัมผัสของเหลวบนเสาหินด้วยความลบหลู่จะถูกคำสาปทำให้เกิดแผลเน่าเปื่อยตามร่างกายและล้มป่วยอย่างไม่อาจรักษาได้',
      'Deep within the subterranean archaeological layers of the Basilica of San Clemente in Rome, beneath the 12th-century church and 4th-century basilica, lies a 1st-century Roman pagan temple of Mithras. Lore speaks of an ancient stone column embedded in the deep masonry said to weep reddish, blood-like moisture on holy martyr feast days, carrying an ancient curse of festering illness for any who touch it with profane curiosity.',
      'ชั้นใต้ดินของซานเคลเมนเตเป็นหนึ่งในแหล่งโบราณคดีที่ลึกลับที่สุดในโรม โดยมีเสียงน้ำไหลใต้ดินจากท่อระบายน้ำยุคโรมันส่งเสียงดังก้องตลอดเวลา',
      'The subterranean complex sits directly above underground rivers and Roman apartments, creating a claustrophobic, echo-laden acoustic environment steeped in legend.',
      'ห้ามแตะต้องหยดคราบสีแดงบนเสาหินในห้องใต้ดินชั้นลึกของซานเคลเมนเต',
      'Do not touch the weeping mineral residue on the subterranean columns of San Clemente.',
      'https://i.ytimg.com/vi/gTaRvh0PfwU/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/gTaRvh0PfwU/hqdefault.jpg","title":"เสาหินหลั่งเลือดแห่งซานเคลเมนเต (คำสาปมรณะแห่งบาซิลิกาโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=gTaRvh0PfwU","title":"Rome underground: San Clemente Basilica","thumbnail":"https://i.ytimg.com/vi/gTaRvh0PfwU/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-old-fort-erie-siege',
      'ป้อมโอลด์ฟอร์ตอีรี (วิญญาณสนามรบและการปิดล้อมนองเลือดปี 1814)',
      'The Ghosts of Old Fort Erie (The Bloody Siege of 1814)',
      'ghost',
      'ออนแทรีโอ',
      'Ontario',
      'ฟอร์ตอีรี ไนแอการา',
      'Fort Erie, Niagara Region',
      42.8953,
      -78.9242,
      'creepy_wind',
      'สมรภูมิที่นองเลือดที่สุดในประวัติศาสตร์แคนาดาระหว่างสงครามปี 1812 เมื่อกองทัพอังกฤษและอเมริกันต่อสู้กันอย่างดุเดือดในการปิดล้อมป้อมอีรี เหตุการณ์ระเบิดครั้งใหญ่ที่คลังแสงคร่าชีวิตทหารไปหลายร้อยนายในพริบตา ปัจจุบันป้อมโบราณแห่งนี้ได้รับการยอมรับว่าเป็นสถานที่ผีดุที่สุดแห่งหนึ่งในแคนาดา เจ้าหน้าที่และผู้มาเยือนพบเห็นวิญญาณทหารไร้หัว นายพลกอร์ดอน ดรัมมอนด์ และเสียงกรีดร้องโหยหวนจากห้องพยาบาลตัดแขนขาโบราณ',
      'Old Fort Erie was the bloodiest battlefield on Canadian soil during the War of 1812. The climactic explosion of the northeast bastion pulverized hundreds of soldiers instantaneously. Revered as Canada''s most haunted historic fortress, night guides and reenactors routinely report apparitions of headless soldiers, phantom fife music, and cold spots inside the former surgeon''s amputation quarters.',
      'โครงกระดูกของทหารผ่านศึกทั้งฝ่ายอเมริกันและอังกฤษถูกขุดพบเรื่อยมาตลอดศตวรรษที่ 20 และถูกนำไปประกอบพิธีทางศาสนาอย่างสมเกียรติ',
      'Archaeological digs continually unearth military skeletons, which are interred with full honors in the nearby military cemetery amidst ongoing poltergeist reports.',
      'ห้ามเดินสำรวจแนวกำแพงค่ายดินปืนเก่าเพียงลำพังหลังปิดทำการ',
      'Never wander the earthworks and bastion grounds alone after the historic park gates lock.',
      'https://i.ytimg.com/vi/mI76PeaOz1A/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/mI76PeaOz1A/hqdefault.jpg","title":"ป้อมโอลด์ฟอร์ตอีรี (วิญญาณสนามรบและการปิดล้อมนองเลือดปี 1814)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=mI76PeaOz1A","title":"Old Fort Erie - Haunted & History","thumbnail":"https://i.ytimg.com/vi/mI76PeaOz1A/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-fort-delaware-pea-patch',
      'ป้อมฟอร์ตเดลาแวร์ (วิญญาณนักโทษสงครามแห่งเกาะพีแพตช์)',
      'The Ghosts of Fort Delaware (The Pea Patch Island POW Hex)',
      'ghost',
      'เดลาแวร์',
      'Delaware',
      'เกาะพีแพตช์ แม่น้ำเดลาแวร์',
      'Pea Patch Island, Delaware River',
      39.5897,
      -75.5683,
      'creepy_wind',
      'ป้อมปราการรูปห้าเหลี่ยมบนเกาะพีแพตช์กลางแม่น้ำเดลาแวร์ ถูกใช้เป็นเรือนจำคุมขังเชลยศึกฝ่ายสมาพันธรัฐกว่า 33,000 นายในช่วงสงครามกลางเมืองอเมริกา ด้วยสภาพความเป็นอยู่ที่แออัดและโรคฝีดาษ อหิวาตกโรค ระบาด ทำให้นักโทษเสียชีวิตไปกว่า 2,700 นาย เจ้าหน้าที่อุทยานและนักท่องเที่ยวรายงานการพบเห็นเงาร่างนักโทษในชุดเครื่องแบบสีเทา ประตูคุกใต้ดินปิดเองอย่างรุนแรง และเสียงโซ่ตรวนลากไปตามพื้นหินแกรนิต',
      'Erected on Pea Patch Island in the Delaware River, Fort Delaware served as a notorious Union prison holding over 33,000 Confederate captives. Nicknamed ''the Andersonville of the North'', nearly 2,700 soldiers succumbed to cholera, smallpox, and malnutrition. Paranormal investigators frequently record Class-A EVPs, phantom footsteps in the subterranean casemates, and spectral sentries guarding empty ramparts.',
      'เรือนจำแห่งนี้เคยถูกจัดอันดับในรายการล่าท้าผี Ghost Hunters ว่าเป็นหนึ่งในสถานที่ที่มีกิจกรรมเหนือธรรมชาติหนาแน่นที่สุดในแถบชายฝั่งตะวันออก',
      'Featured extensively in paranormal television specials, the granite dungeons remain accessible only via passenger ferry across murky tidal waters.',
      'ห้ามขังตัวเองอยู่ในห้องขังมืดใต้ดินของป้อมเดลาแวร์',
      'Do not lock yourself within the windowless subterranean punishment cells.',
      'https://i.ytimg.com/vi/5Uwg5_Zrn3A/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/5Uwg5_Zrn3A/hqdefault.jpg","title":"ป้อมฟอร์ตเดลาแวร์ (วิญญาณนักโทษสงครามแห่งเกาะพีแพตช์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=5Uwg5_Zrn3A","title":"Spooky 360 Video Of Fort Delaware Paranormal Tour | 360 Video | NBC News","thumbnail":"https://i.ytimg.com/vi/5Uwg5_Zrn3A/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-mansfield-reformatory-ohio',
      'ทัณฑสถานแมนส์ฟิลด์ (เรือนจำผีดุแห่งชอว์แชงค์)',
      'The Ohio State Reformatory at Mansfield (The Shawshank Haunting)',
      'ghost',
      'โอไฮโอ',
      'Ohio',
      'แมนส์ฟิลด์ ริชแลนด์',
      'Mansfield, Richland County',
      40.7842,
      -82.5028,
      'creepy_wind',
      'เรือนจำสถาปัตยกรรมกอธิกวิกตอเรียนขนาดมหึมาที่สร้างขึ้นในปี 1886 ในเมืองแมนส์ฟิลด์ รัฐโอไฮโอ เคยเป็นสถานที่ถ่ายทำภาพยนตร์ระดับตำนาน ''The Shawshank Redemption'' ตลอดหนึ่งศตวรรษแห่งการคุมขัง มีนักโทษเสียชีวิตมากกว่า 200 คนจากการฆ่าตัวตาย ความรุนแรง และโรคระบาด วิญญาณที่โด่งดังที่สุดคือวิญญาณของเฮเลน กลาสท์เกอร์ ภรรยาผู้คุมที่ถูกปืนลั่นใส่เสียชีวิต และวิญญาณนักโทษในห้องขังเดี่ยว ''เดอะโฮล'' ที่มักบีบคอนักท่องเที่ยวที่เข้าไปท้าทาย',
      'The Ohio State Reformatory in Mansfield is a menacing Victorian-Gothic prison fortress famous as the primary filming location for ''The Shawshank Redemption''. Over its 94-year operational history, brutal conditions, violent riots, and suicides claimed hundreds of lives. Visitors encounter physical shoves, shadow people in the six-tier east cellblock, and the tragic spectral scent of rose perfume associated with warden''s wife Helen Glattke.',
      'กรงขังเดี่ยวใต้ดิน ''The Hole'' เป็นจุดที่เกิดเหตุการณ์ทำร้ายร่างกายและถูกควบคุมตัวอย่างทารุณมากที่สุด จนกลายเป็นศูนย์รวมพลังงานมืด',
      'The monolithic steel cellblock—the world''s highest freestanding steel cage block—is preserved as a historic museum and magnet for ghost hunts.',
      'ห้ามก้าวเข้าไปในห้องขังขังเดี่ยว ''The Hole'' ตอนปิดไฟ',
      'Never enter solitary confinement cells in total darkness.',
      'https://i.ytimg.com/vi/-w0oe5ravWg/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/-w0oe5ravWg/hqdefault.jpg","title":"ทัณฑสถานแมนส์ฟิลด์ (เรือนจำผีดุแห่งชอว์แชงค์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=-w0oe5ravWg","title":"Mansfield Reformatory (Most Terrifying Places In America)","thumbnail":"https://i.ytimg.com/vi/-w0oe5ravWg/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-brushy-mountain-prison',
      'เรือนจำเทือกเขาบรัชชี (คุกหินผาทรมานแห่งเทนเนสซี)',
      'The Ghosts of Brushy Mountain State Penitentiary (The End of the Line)',
      'ghost',
      'เทนเนสซี',
      'Tennessee',
      'เปตรอส มอร์แกน',
      'Petros, Morgan County',
      36.1492,
      -84.4464,
      'jungle_curse',
      'เรือนจำความมั่นคงสูงสุดที่ตั้งอยู่ท่ามกลางหุบเขาหินป่าทึบในรัฐเทนเนสซี เปิดใช้งานตั้งแต่ปี 1896 เพื่อนำนักโทษไปขุดเหมืองถ่านหิน ที่นี่เคยคุมขัง เจมส์ เอิร์ล เรย์ มือลอบสังหาร มาร์ติน ลูเธอร์ คิง จูเนียร์ เรือนจำแห่งนี้ขึ้นชื่อเรื่องการลงทัณฑ์อันโหดเหี้ยม การสังหารหมู่นักโทษ และการทรมานในห้องมืด วิญญาณนักโทษเหมืองที่เสียชีวิตมักปรากฏตัวเป็นเงามืดไร้หน้า และมีเสียงกระซิบคำสาปแช่งดังก้องในบล็อกเซลล์ร้าง',
      'Nestled against sheer Appalachian cliffs in Petros, Tennessee, Brushy Mountain State Penitentiary opened in 1896 as a brutal coal-mining prison. Infamous for holding MLK assassin James Earl Ray, the penitentiary was dubbed ''The End of the Line''. Murders, disease, and torturous stays in the ''Hole'' left an intense paranormal residue, with investigators experiencing physical claw marks, disembodied snarls, and menacing shadow entities.',
      'เรือนจำปิดตัวลงในปี 2009 และปัจจุบันเปิดเป็นโรงกลั่นสุราและพิพิธภัณฑ์ประวัติศาสตร์ พร้อมทัวร์ล่าท้าผีในยามค่ำคืน',
      'Now operating as a distillery and historic tour site, paranormal teams regularly record violent poltergeist reactions in the maximum-security wing.',
      'ห้ามเข้าไปในทางเดินเหมืองถ่านหินเก่าใต้เรือนจำบรัชชี',
      'Do not explore the abandoned coal mine access portals beneath the cell tiers.',
      'https://i.ytimg.com/vi/CzROwuugfSM/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/CzROwuugfSM/hqdefault.jpg","title":"เรือนจำเทือกเขาบรัชชี (คุกหินผาทรมานแห่งเทนเนสซี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=CzROwuugfSM","title":"Exploring the Haunted Grounds of Brushy | Destination Fear | Travel Channel","thumbnail":"https://i.ytimg.com/vi/CzROwuugfSM/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-moundsville-penitentiary',
      'เรือนจำเมานด์สวิลล์ (แดนประหารเก้าอี้ไฟฟ้าแห่งเวสต์เวอร์จิเนีย)',
      'The West Virginia State Penitentiary at Moundsville (Old Sparky''s Domain)',
      'ghost',
      'เวสต์เวอร์จิเนีย',
      'West Virginia',
      'เมานด์สวิลล์ มาร์แชลล์',
      'Moundsville, Marshall County',
      39.9178,
      -80.7428,
      'jungle_curse',
      'เรือนจำสไตล์กอธิกที่สร้างขึ้นในปี 1866 ข้างเนินดินสุสานอินเดียนแดงโบราณในเมืองเมานด์สวิลล์ รัฐเวสต์เวอร์จิเนีย ที่นี่เป็นแดนประหารชีวิตนักโทษด้วยการแขวนคอและเก้าอี้ไฟฟ้า ''โอลด์ สปาร์กี้'' (Old Sparky) รวมเกือบ 100 ราย รวมถึงมีนักโทษถูกฆาตกรรมภายในคุกอีกหลายร้อยคน ผู้คนพบเห็นเงาร่าง ''ชาโดว์แมน'' ลอยผ่านลูกกรงเหล็ก เสียงฝีเท้าเดินตรวจเวรของผู้คุมที่ตายไปแล้ว และเสียงกรีดร้องจากเก้าอี้ไฟฟ้าที่ว่างเปล่า',
      'Erected directly across from an ancient Adena burial mound in 1866, the West Virginia Penitentiary at Moundsville was among America''s most violent correctional facilities. Host to nearly 100 executions via gallows and the infamous electric chair ''Old Sparky'', riots and mob justice claimed countless inmates. Paranormal phenomena include the legendary ''Shadow Man'' roaming North Hall, sudden temperature drops, and the screams of executed convicts.',
      'การสร้างเรือนจำทับซ้อนกับพื้นที่ศักดิ์สิทธิ์ของชนเผ่าอะดีนา (Adena) ทำให้เชื่อกันว่าเป็นสาเหตุที่ดึงดูดพลังงานแห่งความตายและความรุนแรงตลอดประวัติศาสตร์',
      'Its juxtaposition with the prehistoric Grave Creek Mound is believed by locals to amplify spiritual unrest, making it one of the premier paranormal research hubs in the US.',
      'ห้ามนั่งลงบนเก้าอี้ไฟฟ้าโอลด์สปาร์กี้โดยเด็ดขาด',
      'Never sit in or mock the historical electric chair ''Old Sparky''.',
      'https://i.ytimg.com/vi/I2O20NGHBOg/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/I2O20NGHBOg/hqdefault.jpg","title":"เรือนจำเมานด์สวิลล์ (แดนประหารเก้าอี้ไฟฟ้าแห่งเวสต์เวอร์จิเนีย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=I2O20NGHBOg","title":"A Century of Horror and Hauntings - West Virginia Penitentiary","thumbnail":"https://i.ytimg.com/vi/I2O20NGHBOg/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-charleville-castle-harriet',
      'ปราสาทชาร์เลวิลล์ (วิญญาณหนูน้อยแฮเรียตแห่งไอร์แลนด์)',
      'Charleville Castle (The Ghost of Little Harriet)',
      'ghost',
      'ออฟฟาลี',
      'County Offaly',
      'ทัลลามอร์',
      'Tullamore',
      53.2625,
      -7.5258,
      'whisper',
      'ปราสาทสไตล์กอธิกฟื้นฟูอันงดงามที่สร้างขึ้นในปี 1798 กลางป่าโอ๊กโบราณแห่งทัลลามอร์ ประเทศไอร์แลนด์ วิญญาณที่สิงสถิตอยู่ในปราสาทที่มีชื่อเสียงที่สุดคือ ''แฮเรียต'' บุตรสาววัย 8 ขวบของเอิร์ลแห่งชาร์เลวิลล์รุ่นที่ 3 ซึ่งประสบอุบัติเหตุพลัดตกจากราวบันไดวนลงมาคอหักเสียชีวิตในปี 1861 แขกที่มาเยือนมักได้ยินเสียงเด็กร้องเพลง เสียงหัวเราะไร้เดียงสา เสียงลูกบอลกลิ้งลงบันได และมีผู้พบเห็นเด็กหญิงในชุดกระโปรงสีขาวสว่างวาบข้ามห้องโถง',
      'Charleville Castle is a Gothic revival stronghold surrounded by ancient primeval oak woods in Tullamore, Ireland. The fortress is famously haunted by Harriet, the 8-year-old daughter of the 3rd Earl of Charleville, who tragically fell to her death while sliding down the grand spiral banister in 1861. Visitors and volunteer restorers routinely hear playful giggles, witness phantom nursery balls bouncing down the staircase, and feel invisible small hands clasping theirs.',
      'ในบริเวณป่ารอบปราสาทยังมีต้นโอ๊กโบราณ ''คิงโอ๊ก'' (King Oak) ซึ่งตามตำนานระบุว่าหากกิ่งไม้หักลงมา สมาชิกตระกูลชาร์เลวิลล์จะเสียชีวิตหนึ่งคน',
      'The ancient Druidic King Oak on the castle grounds is tied to a legendary family omen where falling branches prophesied the death of an Earl.',
      'ห้ามวิ่งเล่นหรือลื่นไถลลงตามราวบันไดวนหลักของปราสาทชาร์เลวิลล์',
      'Never slide down the balustrade of the grand central spiral staircase.',
      'https://i.ytimg.com/vi/G7AmWPQvckk/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/G7AmWPQvckk/hqdefault.jpg","title":"ปราสาทชาร์เลวิลล์ (วิญญาณหนูน้อยแฮเรียตแห่งไอร์แลนด์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=G7AmWPQvckk","title":"Most Haunted - S01E16 ''''Charleville Forest Castle''''","thumbnail":"https://i.ytimg.com/vi/G7AmWPQvckk/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-port-arthur-historic-site',
      'พอร์ตอาร์เทอร์ (ทัณฑนิคมทมิฬและวิญญาณนักโทษแห่งแทสเมเนีย)',
      'The Ghosts of Port Arthur (The Separate Prison Torment)',
      'ghost',
      'แทสเมเนีย',
      'Tasmania',
      'คาบสมุทรแทสมัน พอร์ตอาร์เทอร์',
      'Tasman Peninsula, Port Arthur',
      -43.1497,
      147.85,
      'creepy_wind',
      'นิคมคุมขังนักโทษที่โหดเหี้ยมที่สุดของจักรวรรดิอังกฤษ ก่อตั้งขึ้นในปี 1830 บนคาบสมุทรแทสมัน ประเทศออสเตรเลีย ที่นี่ใช้ระบบ ''Separate Prison'' ซึ่งเป็นการขังเดี่ยวนักโทษในความเงียบสนิท ปิดคลุมศีรษะด้วยฮู้ดผ้า และห้ามพูดคุยเด็ดขาดจนนักโทษจำนวนมากกลายเป็นบ้าและฆ่าตัวตาย มีรายงานวิญญาณหลอกหลอนมากกว่า 2,000 ครั้ง ทั้งวิญญาณในหอคอยโบสถ์ วิญญาณเด็กหนุ่มที่เกาะคนตาย (Isle of the Dead) และไฟวิญญาณสีน้ำเงินในห้องเก็บศพ',
      'Established in 1830 on the Tasman Peninsula, Port Arthur was Britain''s harshest penal station for repeat convict offenders. Pioneering psychological isolation techniques in the ''Separate Prison'', convicts were hooded in silence for months, driving many to terminal insanity. Recognized as Australia''s most active haunted site, historic ghost tours regularly encounter heavy rocking chairs moving on their own, phantom bell chimes, and shadowy figures in the asylum ruins.',
      'เกาะเล็กๆ ริมอ่าวที่ชื่อ Isle of the Dead เป็นที่ฝังศพของนักโทษและเจ้าหน้าที่กว่า 1,000 นาย โดยนักโทษจะถูกฝังในหลุมศพนิรนามไร้แผ่นป้าย',
      'Over 1,000 souls lie buried on the adjacent Isle of the Dead, an offshore cemetery island steeped in eerie sightings and spectral maritime fog.',
      'ห้ามพูดคุยหรือส่งเสียงกระซิบในห้องขังเดี่ยวของเรือนจำเงียบ (Separate Prison)',
      'Maintain strict silence within the punishment corridors of the Separate Prison.',
      'https://i.ytimg.com/vi/W-HX660cFnQ/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/W-HX660cFnQ/hqdefault.jpg","title":"พอร์ตอาร์เทอร์ (ทัณฑนิคมทมิฬและวิญญาณนักโทษแห่งแทสเมเนีย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=W-HX660cFnQ","title":"Ghost Hunters International S02E10 Port Arthur Penitentiary","thumbnail":"https://i.ytimg.com/vi/W-HX660cFnQ/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-monte-cristo-homestead-junee',
      'คฤหาสน์มอนเตคริสโต (บ้านผีดุที่สุดในออสเตรเลีย)',
      'Monte Cristo Homestead (Australia''s Most Haunted Mansion)',
      'ghost',
      'นิวเซาท์เวลส์',
      'New South Wales',
      'จูเนอ ริเวอรินา',
      'Junee, Riverina',
      -34.8667,
      147.5833,
      'creepy_wind',
      'คฤหาสน์สไตล์วิกตอเรียนโอ่อ่าบนเนินเขาในเมืองจูเนอ ประเทศออสเตรเลีย สร้างขึ้นในปี 1885 โดยคริสโตเฟอร์ ดอว์ลีย์ ครอว์ลีย์ ประวัติศาสตร์ของบ้านหลังนี้เต็มไปด้วยโศกนาฏกรรม ทั้งเด็กทารกที่ตกบันไดเสียชีวิต เด็กรับใช้ที่ถูกไฟคลอก และคนงานที่ถูกล่ามโซ่ขังไว้ในกระท่อมนานกว่า 30 ปี ปัจจุบันผู้พักอาศัยและนักท่องเที่ยวพบเห็นดวงไฟประหลาดลอยไปมา สัมผัสถึงมือเย็นเยียบแตะไหล่ และใบหน้าของนางครอว์ลีย์ที่จ้องมองลงมาจากหน้าต่างชั้นสอง',
      'Perched above the town of Junee, New South Wales, Monte Cristo Homestead was constructed in 1885 by wealthy pastoralist Christopher Crawley. The manor is plagued by a horrific legacy of accidental and intentional deaths: an infant dropped down the stairs, a stable boy burned alive, and a disabled caretaker chained in the outhouse for decades. Widely acknowledged as Australia''s most haunted home, witnesses report phantom mists, physical pushes, and full-bodied apparitions.',
      'เจ้าของบ้านในยุคปัจจุบันเปิดให้เข้าพักและจัดทัวร์ข้ามคืน โดยมีรายงานอุปกรณ์ไฟฟ้าขัดข้องและกล้องถ่ายภาพติดใบหน้าโปร่งแสงอยู่เสมอ',
      'The Ryan family, who lovingly restored the manor, have documented countless supernatural encounters, confirming cold spots and disembodied sobbing across the estate.',
      'ห้ามจ้องมองหน้าต่างห้องนอนใหญ่ของนางครอว์ลีย์ยามค่ำคืน',
      'Avoid gazing fixedly at Mrs. Crawley''s former second-story bedroom window after dark.',
      'https://i.ytimg.com/vi/zOVRecGnNbM/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/zOVRecGnNbM/hqdefault.jpg","title":"คฤหาสน์มอนเตคริสโต (บ้านผีดุที่สุดในออสเตรเลีย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=zOVRecGnNbM","title":"Monte Cristo - Australia’s Most Haunted House","thumbnail":"https://i.ytimg.com/vi/zOVRecGnNbM/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-karosta-prison-latvia',
      'เรือนจำทหารคาโรสตา (คุกนรกเคจีบีแห่งลัตเวีย)',
      'Karosta Prison (The Soviet Military Incarceration Cells)',
      'ghost',
      'คูร์ลันด์',
      'Courland',
      'ลีปายา คาโรสตา',
      'Liepaja, Karosta',
      56.55,
      21.0167,
      'jungle_curse',
      'เรือนจำทหารของกองทัพเรือซาร์รัสเซียและสหภาพโซเวียต สร้างขึ้นในต้นศตวรรษที่ 20 ในเมืองลีปายา ประเทศลัตเวีย ที่นี่ถูกใช้เป็นคุกคุมขังทหารกบฏและผู้ต้องสงสัยทางการเมือง มีนักโทษหลายพันคนถูกยิงเป้าประหารชีวิตที่ลานหลังคุกโดยเคจีบีและนาซีเยอรมัน ปัจจุบันกลายเป็นสถานที่ทดสอบความกล้าที่เปิดให้นักท่องเที่ยวมาสัมผัสชีวิตนักโทษ มีรายงานหลอดไฟระเบิดเอง ประตูเหล็กไขล็อคเอง และวิญญาณหญิงสาวชุดขาว (White Lady) ที่แขวนคอตายหลังคู่หมั้นถูกยิงเป้า',
      'Built at the turn of the 20th century in Liepaja, Latvia, Karosta Prison served as a grim military detention facility under Tsarist, Nazi, and Soviet regimes. Thousands of mutinous sailors and political dissidents were interrogated, tortured, and executed in the courtyard. Ghost Hunters International identified intense paranormal activity throughout the fortress, including spontaneously unlocking heavy iron cell doors, lightbulbs exploding, and the tragic phantom of a bride who hanged herself.',
      'นักท่องเที่ยวสามารถเลือกโปรแกรม ''สัมผัสประสบการณ์คืนคุกจริง'' โดยจะได้รับการปฏิบัติเยี่ยงนักโทษโซเวียตท่ามกลางความมืดและวิญญาณ',
      'Karosta now operates extreme overnight immersion tours where guests endure Soviet-style guard treatment inside genuinely haunted solitary cells.',
      'ห้ามล้อเลียนหรือขัดคำสั่งเจ้าหน้าที่ในห้องขังเดี่ยวโซเวียต',
      'Never disrespect the memory of executed dissidents in the prison execution courtyard.',
      'https://i.ytimg.com/vi/JhzBx8pO0_g/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/JhzBx8pO0_g/hqdefault.jpg","title":"เรือนจำทหารคาโรสตา (คุกนรกเคจีบีแห่งลัตเวีย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=JhzBx8pO0_g","title":"Ghost Hunters International S1E23 : Karosta Prison","thumbnail":"https://i.ytimg.com/vi/JhzBx8pO0_g/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-burg-eltz-countess-agnes',
      'ปราสาทเบิร์กเอลต์ซ (วิญญาณท่านหญิงแอ็กเนสผู้พิทักษ์ปราสาท)',
      'Burg Eltz (The Ghost of Countess Agnes)',
      'ghost',
      'ไรน์ลันด์-ฟัลทซ์',
      'Rhineland-Palatinate',
      'วีร์เชม ไมเอน-โคเบลนซ์',
      'Wierschem, Mayen-Koblenz',
      50.205,
      7.3364,
      'creepy_wind',
      'หนึ่งในปราสาทยุคกลางที่งดงามและสมบูรณ์ที่สุดในเยอรมนี ซ่อนตัวอยู่ในหุบเขาป่าทึบริมแม่น้ำเอลต์ซบัค ไม่เคยถูกทำลายตลอด 850 ปี ตำนานเล่าถึงท่านหญิงแอ็กเนส บุตรสาวของเจ้าของปราสาทในศตวรรษที่ 15 เธอปฏิเสธการแต่งงานกับอัศวินผู้เหี้ยมโหดแห่งบราวน์สเบิร์ก ทำให้อัศวินนำกำลังเข้าล้อมโจมตีปราสาท ท่านหญิงแอ็กเนสสวมชุดเกราะของพี่ชายออกรบเพื่อปกป้องปราสาทจนถูกลูกธนูยิงทะลุหัวใจเสียชีวิต วิญญาณของเธอยังคงวนเวียนเฝ้าห้องนอนและลานปราสาทเพื่อปกป้องบ้านเกิด',
      'Nestled in a lush forested valley above the Elzbach River, Burg Eltz has remained in the hands of the same noble family for over thirty generations. The castle''s most famous spirit is Countess Agnes, who defended the stronghold in the 15th century against a spurned suitor, Knight of Braunsberg. Donning her brother''s armor to lead the defense, she was struck down by a mortal arrow. Her spectral figure in full plate armor is reported patrolling the courtyard and her preserved bedchamber.',
      'ชุดเกราะที่มีรอยทะลุของลูกธนูและเตียงนอนโบราณของท่านหญิงแอ็กเนสยังคงได้รับการจัดแสดงไว้ในปราสาทจนถึงปัจจุบัน',
      'Agnes''s pierced breastplate and battleaxe remain on display in the castle treasury, accompanied by centuries of guard reports of spectral footsteps.',
      'ห้ามแตะต้องชุดเกราะโบราณในห้องจัดแสดงของท่านหญิงแอ็กเนส',
      'Never attempt to touch the battle-damaged breastplate of Countess Agnes.',
      'https://i.ytimg.com/vi/3ezoCvDZDkU/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/3ezoCvDZDkU/hqdefault.jpg","title":"ปราสาทเบิร์กเอลต์ซ (วิญญาณท่านหญิงแอ็กเนสผู้พิทักษ์ปราสาท)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=3ezoCvDZDkU","title":"Eltz Castle in Germany: Would you like to live here?","thumbnail":"https://i.ytimg.com/vi/3ezoCvDZDkU/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-voergaard-castle-ingeborg-skeel',
      'ปราสาทวอร์การ์ด (วิญญาณอินเกบอร์ก สคีล แห่งเดนมาร์ก)',
      'Voergaard Castle (The Malicious Ghost of Ingeborg Skeel)',
      'ghost',
      'นอร์ทจัตแลนด์',
      'North Jutland',
      'ดรอนนิงลุนด์ บรอนเดอร์สเลฟ',
      'Dronninglund, Bronderslev',
      57.2458,
      10.2925,
      'whisper',
      'ปราสาทเรเนซองส์ที่งดงามที่สุดแห่งหนึ่งในเดนมาร์ก ล้อมรอบด้วยคูน้ำลึก มีชื่อเสียงเรื่องความเฮี้ยนของ ''อินเกบอร์ก สคีล'' หญิงม่ายชนชั้นสูงในศตวรรษที่ 16 ผู้มีชื่อเสียงเรื่องความโหดเหี้ยม เธอถูกกล่าวหาว่าผลักสถาปนิกผู้สร้างปราสาทลงไปในคูน้ำให้จมน้ำตายเพื่อไม่ให้ไปสร้างปราสาทที่สวยกว่านี้ให้คนอื่น และยังตัดหูตัดมือชาวนาที่ขโมยข้าว แม้หลังเธอเสียชีวิตในปี 1604 วิญญาณของเธอก็ยังหลอกหลอนจนบาทหลวงต้องมาทำพิธีสะกดวิญญาณลงในหนองน้ำ แต่เธอก็ยังกลับมาที่ปราสาทได้เสมอ',
      'Voergaard Castle is a moated Renaissance palace in northern Denmark shadowed by the sinister legend of Ingeborg Skeel. Taking ownership in 1580, Skeel was rumored to be a ruthless tyrant who drowned the castle''s master builder in the moat to ensure no rival palace was ever constructed. Exorcised into a nearby marsh upon her death in 1604, her vengeful ghost broke the magical wards, routinely blowing out candles and pacing the tower corridors.',
      'ในห้อง ''Rodedungeon'' มีคราบเลือดบนพื้นไม้ที่ไม่สามารถลบออกได้ แม้จะขัดถูหรือไสหน้าไม้ออก คราบเลือดก็จะกลับมาปรากฏใหม่เสมอ',
      'A permanent, indelible bloodstain on the floor of the northeastern tower room has resisted chemical cleaning and sanding for centuries.',
      'ห้ามนำเทียนไขหรือเปลวไฟเข้าไปในห้องคราบเลือดโบราณของปราสาทวอร์การ์ด',
      'Never carry an open flame into the haunted bloodstain chamber of Voergaard.',
      'https://i.ytimg.com/vi/JmmTId-lKlk/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/JmmTId-lKlk/hqdefault.jpg","title":"ปราสาทวอร์การ์ด (วิญญาณอินเกบอร์ก สคีล แห่งเดนมาร์ก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=JmmTId-lKlk","title":"The Real Haunted Story Of Voergaard Manor | Voergaard Manor","thumbnail":"https://i.ytimg.com/vi/JmmTId-lKlk/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-edinburgh-vaults-south-bridge',
      'ห้องใต้ดินสะพานใต้เอดินบะระ (แดนผีดุใต้สะพานเซาท์บริดจ์)',
      'The Edinburgh South Bridge Vaults (The Damned Underworld)',
      'ghost',
      'เอดินบะระ',
      'City of Edinburgh',
      'สะพานเซาท์บริดจ์ โอลด์ทาวน์',
      'South Bridge, Old Town',
      55.9486,
      -3.1878,
      'jungle_curse',
      'เครือข่ายห้องหินโค้งใต้ดิน 120 ห้องใต้สะพานเซาท์บริดจ์ในกรุงเอดินบะระ สร้างขึ้นในปี 1788 เดิมใช้เป็นร้านค้าและโกดัง แต่ต่อมาเกิดน้ำท่วมและกลายเป็นสลัมใต้ดินอันมืดมิด เป็นที่ซ่อนตัวของโสเภณี อาชญากร และฆาตกรชื่อดัง ''เบิร์กและแฮร์'' ที่สังหารเหยื่อนำศพไปขายให้นักศึกษากายวิภาค ห้องใต้ดินถูกปิดตายและลืมเลือนไปนานนับศตวรรษก่อนจะถูกค้นพบใหม่ มีรายงานวิญญาณ ''มิสเตอร์บู๊ตส์'' ชายร่างยักษ์สวมรองเท้าบูทหนัง และวิญญาณเด็กชาย ''แจ็ค'' ที่ชอบดึงมือนักท่องเที่ยว',
      'The Edinburgh Vaults are a dark labyrinth of subterranean stone chambers enclosed within the 19 arches of South Bridge, completed in 1788. Slum dwellers, illegal distilleries, and body-snatchers like Burke and Hare operated in this sunless abyss before the damp catacombs were abandoned and sealed in the 1870s. Rediscovered in the 1980s, visitors experience chilling physical attacks, shadow entities, and the menacing stomp of ''Mr. Boots''.',
      'นักวิจัยด้านพาราเนอร์มอลจากมหาวิทยาลัยเอดินบะระเคยทำการทดลองทางวิทยาศาสตร์และยืนยันว่าผู้ร่วมการทดลองพบความผิดปกติของอุณหภูมิและคลื่นแม่เหล็กไฟฟ้าสูงผิดปกติ',
      'Prof. Richard Wiseman''s landmark psychological studies at Edinburgh Vaults documented extraordinary clusters of subjective paranormal perceptions and localized magnetic fluctuations.',
      'ห้ามเดินแยกตัวออกจากกลุ่มทัวร์เข้าไปในห้องใต้ดินที่ยังไม่ได้สำรวจ',
      'Never wander alone into unexcavated, pitch-black chambers beneath South Bridge.',
      'https://i.ytimg.com/vi/V7QSfqSAIpc/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/V7QSfqSAIpc/hqdefault.jpg","title":"ห้องใต้ดินสะพานใต้เอดินบะระ (แดนผีดุใต้สะพานเซาท์บริดจ์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=V7QSfqSAIpc","title":"The Ghosts of the Edinburgh Vaults: Exploring the Supernatural under the streets of the capital","thumbnail":"https://i.ytimg.com/vi/V7QSfqSAIpc/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-rolling-hills-asylum-ny',
      'สถานพยาบาลโรลลิงฮิลส์ (บ้านพักคนอนาถาผีดุแห่งนิวยอร์ก)',
      'Rolling Hills Asylum (The Genesee County Poorhouse Haunting)',
      'ghost',
      'นิวยอร์ก',
      'New York',
      'อีสต์เบธานี เจเนซี',
      'East Bethany, Genesee County',
      42.9236,
      -78.1342,
      'creepy_wind',
      'ก่อตั้งขึ้นในปี 1827 ในฐานะบ้านพักคนชรา คนยากไร้ และผู้ป่วยทางจิตในเทศมณฑลเจเนซี รัฐนิวยอร์ก มีผู้เสียชีวิตในสถานที่แห่งนี้มากกว่า 1,700 ราย โดยศพส่วนใหญ่ถูกฝังในหลุมศพนิรนามในทุ่งหญ้าหลังอาคาร วิญญาณที่มีชื่อเสียงที่สุดคือ ''รอย เคราช์'' (Roy Crouse) ชายร่างยักษ์สูงกว่า 7 ฟุตครึ่งที่เป็นโรคยักษ์และใช้ชีวิตอยู่ที่นี่จนเสียชีวิตในปี 1942 เงาร่างยักษ์ของเขามักปรากฏตัวตามทางเดินมืด รวมถึงเสียงเด็กร้องไห้และเก้าอี้โยกที่แกว่งเอง',
      'Established in 1827 as the Genesee County Poorhouse, Rolling Hills Asylum sheltered the destitute, orphaned, mentally afflicted, and criminals for over 150 years. Over 1,700 deaths occurred on-site, filling vast unmarked burial grounds. Renowned for intense poltergeist manifestations, investigators encounter the 7-foot-tall shadow apparition of Roy Crouse, a gentle giant who lived and died here, alongside disembodied voices echoing down the East Wing ward.',
      'สถานที่แห่งนี้เปิดให้นักล่าผีเข้าสำรวจค้างคืน และได้รับการจัดอันดับให้เป็นหนึ่งในสถานพยาบาลที่มีผีดุที่สุดในภาคตะวันออกเฉียงเหนือของสหรัฐฯ',
      'Regularly featured on Travel Channel''s ''Ghost Adventures'', Rolling Hills preserves original morgue coolers, psych ward restraints, and paranormal evidence archives.',
      'ห้ามนำของเล่นเด็กหรือวัตถุโบราณออกจากห้องสถานพยาบาลเด็กกำพร้า',
      'Never remove antique toys or artifacts from the former orphanage ward.',
      'https://i.ytimg.com/vi/zHBSI6iC5dI/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/zHBSI6iC5dI/hqdefault.jpg","title":"สถานพยาบาลโรลลิงฮิลส์ (บ้านพักคนอนาถาผีดุแห่งนิวยอร์ก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=zHBSI6iC5dI","title":"Locked in New York''s Most Haunted Asylum | Rolling Hills","thumbnail":"https://i.ytimg.com/vi/zHBSI6iC5dI/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-fort-mifflin-casemate-screamer',
      'ป้อมฟอร์ตมิฟฟลิน (เสียงกรีดร้องในป้อมปราการแห่งสงครามกู้ชาติ)',
      'Fort Mifflin on the Delaware (The Screaming Lady of the Casemates)',
      'ghost',
      'เพนซิลเวเนีย',
      'Pennsylvania',
      'แม่น้ำเดลาแวร์ ฟิลาเดลเฟีย',
      'Delaware River, Philadelphia',
      39.8711,
      -75.2139,
      'creepy_wind',
      'ป้อมปราการประวัติศาสตร์ที่สร้างขึ้นในปี 1771 ริมแม่น้ำเดลาแวร์ เมืองฟิลาเดลเฟีย เป็นสถานที่ที่กองทัพอเมริกันต่อสู้กับกองเรือรบอังกฤษในการระดมยิงปืนใหญ่ที่รุนแรงที่สุดในสงครามปฏิวัติอเมริกา มีวิญญาณที่สิงสู่อยู่มากมาย โดยเฉพาะ ''สครีมมิงเลดี้'' (The Screaming Lady) วิญญาณของเอลิซาเบธ แพรตต์ หญิงสาวที่เสียชีวิตด้วยความโศกเศร้าหลังลูกสาวตายด้วยไข้ไทฟอยด์ เสียงกรีดร้องของเธอโหยหวนจนตำรวจท้องถิ่นเคยได้รับแจ้งเหตุคนถูกทำร้ายบ่อยครั้ง',
      'Commissioned in 1771, Fort Mifflin endured the heaviest naval bombardment of the American Revolutionary War when British warships pounded the ramparts with over 10,000 cannonballs. Known as the ''Fort That Saved America'', its stone casemates harbor restless spirits, most notably the ''Screaming Lady''—Elizabeth Pratt, whose grief-stricken wails over her daughter''s typhoid death still trigger 911 domestic violence calls to local police.',
      'ในห้องขังใต้ดิน Casemate 11 ยังมีวิญญาณ ''วิลเลียม เอช. ฮาว'' นักโทษหนีทัพฝ่ายเหนือที่ถูกแขวนคอในปี 1864 ปรากฏตัวเป็นเงามืดไร้ใบหน้า',
      'Casemate 11 imprisoned Confederate soldiers and Union deserter William H. Howe, who was hanged on the parade ground; his faceless silhouette haunts cell walls.',
      'ห้ามผิวปากหรือส่งเสียงตะโกนในห้องใต้ดิน Casemate 11',
      'Do not whistle or provoke spirits within the subterranean Casemate 11 dungeon.',
      'https://i.ytimg.com/vi/pAJ7XBNQ9_Y/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/pAJ7XBNQ9_Y/hqdefault.jpg","title":"ป้อมฟอร์ตมิฟฟลิน (เสียงกรีดร้องในป้อมปราการแห่งสงครามกู้ชาติ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=pAJ7XBNQ9_Y","title":"Travel The Dead: Haunted Fort Mifflin | Ghosts of the Revolution | Part 1/3 #haunted #history #ghost","thumbnail":"https://i.ytimg.com/vi/pAJ7XBNQ9_Y/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-st-albans-sanatorium-virginia',
      'สถานพยาบาลเซนต์อัลบันส์ (โรงพยาบาลจิตเวชผีดุแห่งเวอร์จิเนีย)',
      'St. Albans Sanatorium (The Appalachian Psychiatric Haunting)',
      'ghost',
      'เวอร์จิเนีย',
      'Virginia',
      'แรดฟอร์ด พูแลสกี',
      'Radford, Pulaski County',
      37.1436,
      -80.5519,
      'creepy_wind',
      'เดิมทีสถานที่แห่งนี้เคยเป็นโรงเรียนเด็กชายเซนต์อัลบันส์ในปี 1892 ก่อนจะเปลี่ยนเป็นสถานพยาบาลจิตเวชในปี 1916 ที่นี่ขึ้นชื่อเรื่องการใช้วิธีการรักษาที่ทารุณในยุคแรก เช่น การช็อตไฟฟ้า การผ่าตัดสมอง (Lobotomy) และการแช่น้ำแข็งนานหลายชั่วโมง อัตราการฆ่าตัวตายของคนไข้และพยาบาลสูงมากจนบรรยากาศเต็มไปด้วยความหดหู่ ผู้มาเยือนมักถูกข่วน มีรอยฟกช้ำตามตัว และได้ยินเสียงกรีดร้องโหยหวนจากห้องโบว์ลิ่งและห้องน้ำรวม',
      'Perched high above the New River in Radford, Virginia, St. Albans began as a competitive boys'' academy in 1892 before converting into a psychiatric hospital in 1916. Plagued by extreme early experimental treatments—including electroconvulsive therapy, lobotomies, and insulin comas—dozens of patients and staff committed suicide. Today, it ranks among the most physically active paranormal locations on the East Coast, infamous for scratching visitors and phantom cries in the hydrotherapy ward.',
      'พื้นที่ตั้งของสถานพยาบาลเคยเป็นจุดปะทะในสงครามกลางเมืองอเมริกาในการรบที่ภูเขาโคลธส์ (Battle of Cloyd''s Mountain) ทำให้มีวิญญาณทหารทับซ้อนอยู่ด้วย',
      'The ground was soaked in blood long before the hospital opened during the 1864 Civil War Battle of Cloyd''s Mountain, compounding the site''s dark spiritual energy.',
      'ห้ามท้าทายวิญญาณในห้องวารีบำบัด (Hydrotherapy Room) ของเซนต์อัลบันส์',
      'Never provoke hostile entities inside the abandoned hydrotherapy bathtub room.',
      'https://i.ytimg.com/vi/kt8YWA0dVMM/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/kt8YWA0dVMM/hqdefault.jpg","title":"สถานพยาบาลเซนต์อัลบันส์ (โรงพยาบาลจิตเวชผีดุแห่งเวอร์จิเนีย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=kt8YWA0dVMM","title":"The Most TERRIFYING Haunted Asylum in America: Chilling Proof of the Paranormal Captured (SCARY)","thumbnail":"https://i.ytimg.com/vi/kt8YWA0dVMM/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-pythian-castle-springfield-missouri',
      'ปราสาทไพเธียน (วิญญาณคุกทหารผ่านศึกแห่งสปริงฟิลด์)',
      'Pythian Castle (The Military Hospital Hauntings of Springfield)',
      'ghost',
      'มิสซูรี',
      'Missouri',
      'สปริงฟิลด์ กรีน',
      'Springfield, Greene County',
      37.2289,
      -93.2683,
      'jungle_curse',
      'ปราสาทหินปูนสไตล์ปราสาทเยอรมัน สร้างขึ้นในปี 1913 โดยกลุ่มภราดรภาพ ''Knights of Pythias'' เพื่อเป็นบ้านพักคนชราและเด็กกำพร้า ต่อมาในช่วงสงครามโลกครั้งที่สอง กองทัพสหรัฐฯ ยึดปราสาทไปใช้เป็นโรงพยาบาลทหารและคุมขังเชลยศึกชาวเยอรมันและอิตาลี มีรายงานวิญญาณเด็กวิ่งเล่นในห้องใต้หลังคา เสียงดนตรีเต้นรำโบราณแว่วมาจากห้องบอลรูม และเงาร่างทหารเยอรมันที่ถูกขังเดี่ยวในห้องใต้ดินอันมืดมิด',
      'Constructed in 1913 by the fraternal order Knights of Pythias as an orphanage and retirement home, Pythian Castle in Springfield, Missouri, was requisitioned by the US military during World War II as an injured soldiers'' hospital and Axis prisoner interrogation center. Paranormal phenomena include phantom children giggling on the top floor, 1940s big band music echoing in the grand ballroom, and aggressive poltergeist activity in the subterranean detention cells.',
      'ปราสาทแห่งนี้ได้รับการขึ้นทะเบียนเป็นโบราณสถานแห่งชาติ และเปิดให้นักท่องเที่ยวเข้าร่วมทัวร์ประวัติศาสตร์และทัวร์ล่าผี',
      'Privately purchased and restored, the castle is certified as an official historic landmark and remains one of the Midwest''s most investigated paranormal locations.',
      'ห้ามเคาะผนังห้องขังเชลยศึกใต้ดินเพื่อสื่อสารกับวิญญาณโดยลำพัง',
      'Do not tap on the subterranean POW detention cell walls to summon spirits.',
      'https://i.ytimg.com/vi/4XlZHweHEtc/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/4XlZHweHEtc/hqdefault.jpg","title":"ปราสาทไพเธียน (วิญญาณคุกทหารผ่านศึกแห่งสปริงฟิลด์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=4XlZHweHEtc","title":"The Spirits of Pythian Castle","thumbnail":"https://i.ytimg.com/vi/4XlZHweHEtc/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-sorrel-weed-house-savannah',
      'บ้านซอร์เรล-วีด (โศกนาฏกรรมฆ่าตัวตายแห่งเมืองซาวันนาห์)',
      'The Sorrel Weed House (The Tragic Suicides of Madison Square)',
      'ghost',
      'จอร์เจีย',
      'Georgia',
      'แมดิสันสแควร์ ซาวันนาห์',
      'Madison Square, Savannah',
      32.0725,
      -81.0944,
      'creepy_wind',
      'คฤหาสน์สไตล์กรีกฟื้นฟูอันหรูหรา สร้างขึ้นในปี 1840 โดยฟรานซิส ซอร์เรล พ่อค้าผู้มั่งคั่ง ในเมืองซาวันนาห์ รัฐจอร์เจีย ประวัติศาสตร์ของบ้านเต็มไปด้วยความตาย เมื่อภรรยาของเขา มาทิลด้า กระโดดระเบียงชั้นสองลงมาเสียชีวิตหลังจับได้ว่าสามีนอกใจกับทาสสาวชื่อมอลลี่ ไม่นานหลังจากนั้น มอลลี่ก็ถูกพบผูกคอตายในโรงม้าด้านหลัง แขกที่มาเยือนมักรู้สึกแน่นหน้าอก หายใจไม่ออก และได้ยินเสียงสะอื้นไห้ของผู้หญิงดังก้องในห้องนอนใหญ่',
      'Standing elegantly on Madison Square, Savannah''s Sorrel Weed House is an 1840 Greek Revival mansion burdened with notorious double-suicide lore. Francis Sorrel''s wife Matilda reportedly leaped to her death from the second-story balcony after discovering her husband''s affair with an enslaved servant named Molly; shortly thereafter, Molly was found hanged in the carriage house. Visitors regularly experience severe nausea, phantom suffocating sensations, and the rustle of Matilda''s heavy hoop skirt.',
      'พื้นที่ใต้คฤหาสน์ยังทับซ้อนกับสนามรบ ''Siege of Savannah'' ในปี 1779 ทำให้มีวิญญาณทหารสงครามปฏิวัติวนเวียนอยู่เช่นกัน',
      'The property sits directly atop earth contested during the bloody 1779 Siege of Savannah, adding revolutionary war soldier apparitions to the antebellum domestic tragedy.',
      'ห้ามยืนพิงราวระเบียงชั้นสองจุดที่มาทิลด้ากระโดดลงมา',
      'Do not lean over the second-floor balcony where Matilda plummeted to her death.',
      'https://i.ytimg.com/vi/JAOYywV_gvc/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/JAOYywV_gvc/hqdefault.jpg","title":"บ้านซอร์เรล-วีด (โศกนาฏกรรมฆ่าตัวตายแห่งเมืองซาวันนาห์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=JAOYywV_gvc","title":"The Horrifying Sorrel-Weed Haunted Mansion","thumbnail":"https://i.ytimg.com/vi/JAOYywV_gvc/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-kehoe-house-savannah',
      'บ้านตระกูลคีโฮ (วิญญาณเด็กในปล่องไฟแห่งโคลัมเบียสแควร์)',
      'The Kehoe House (The Lost Children of Columbia Square)',
      'ghost',
      'จอร์เจีย',
      'Georgia',
      'โคลัมเบียสแควร์ ซาวันนาห์',
      'Columbia Square, Savannah',
      32.0781,
      -81.0883,
      'whisper',
      'คฤหาสน์อิฐแดงสไตล์เรเนซองส์ฟื้นฟูอันงดงาม สร้างขึ้นในปี 1892 โดยวิลเลียม คีโฮ เจ้าของโรงหล่อเหล็กผู้มีอิทธิพล เขาและภรรยามีบุตรถึง 10 คน ตำนานเล่าว่ามีลูกสองคนของเขาเสียชีวิตจากอุบัติเหตุติดอยู่ในปล่องไฟขณะเล่นซ่อนแอบ ต่อมาบ้านถูกเปลี่ยนเป็นสถานประกอบพิธีศพนานหลายสิบปี ปัจจุบันเปิดเป็นโรงแรมหรู แขกมักตื่นขึ้นมากลางดึกเพราะรู้สึกเหมือนมีเด็กมานั่งทับบนเตียง ได้ยินเสียงหัวเราะวิ่งเล่นตามทางเดิน และเห็นเงาเด็กจ้องมองมาจากหน้าต่าง',
      'Built in 1892 on Columbia Square by iron foundry magnate William Kehoe, this magnificent red-brick mansion was home to a large family of ten children. Tragic urban folklore maintains that two young Kehoe twins died after becoming trapped inside the home''s chimneys while playing. Later serving as Goette''s Funeral Home, guests at the current luxury boutique inn routinely report ghost children sitting on their beds, knocking on doors, and giggling in empty hallways.',
      'แม้จะไม่มีบันทึกมรณบัตรทางการเรื่องเด็กติดในปล่องไฟ แต่การเป็นสถานจัดงานศพนานหลายสิบปีทำให้คฤหาสน์สะสมพลังงานความเศร้าโศกอย่างมหาศาล',
      'Whether fueled by the chimney urban legend or its decades as a busy mortuary, rooms 201 and 203 are internationally famous for spectral touchings and child manifestations.',
      'ห้ามมองเข้าไปในช่องระบายควันปล่องไฟเก่าในยามค่ำคืน',
      'Never peer up into the unsealed fireplaces late at night.',
      'https://i.ytimg.com/vi/h4jtizPqy2E/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/h4jtizPqy2E/hqdefault.jpg","title":"บ้านตระกูลคีโฮ (วิญญาณเด็กในปล่องไฟแห่งโคลัมเบียสแควร์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=h4jtizPqy2E","title":"History & Hauntings of Savannah''s Premier Victorian Inns: The Kehoe House & the Hamilton-Turner Inn","thumbnail":"https://i.ytimg.com/vi/h4jtizPqy2E/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-fremantle-prison-western-australia',
      'เรือนจำฟรีแมนเทิล (แดนประหารแดนสยองแห่งออสเตรเลียตะวันตก)',
      'Fremantle Prison (The Convict Gallows and Ghostly Murmurs)',
      'ghost',
      'เวสเทิร์นออสเตรเลีย',
      'Western Australia',
      'ฟรีแมนเทิล เพิร์ท',
      'Fremantle, Perth',
      -32.0558,
      115.7539,
      'jungle_curse',
      'เรือนจำหินปูนขนาดมหึมาที่สร้างขึ้นโดยแรงงานนักโทษอังกฤษในช่วงทศวรรษ 1850 ในเมืองฟรีแมนเทิล ประเทศออสเตรเลีย ที่นี่เป็นสถานที่ประหารชีวิตด้วยการแขวนคอถึง 44 ราย รวมถึงมาร์ธา เรนเดลล์ หญิงคนเดียวที่ถูกแขวนคอในรัฐนี้ในข้อหาวางยาพิษเด็ก เรือนจำขึ้นชื่อเรื่องความแออัด การลงแส้ และห้องขังมืด ผู้คุมและนักท่องเที่ยวรายงานการพบเห็นหมอกสีเขียวลอยผ่านแดนประหาร เสียงร้องไห้ของนักโทษ และเงาดำที่เดินทะลุกำแพงหินปูน',
      'Constructed by British convicts from 1852 to 1859, Fremantle Prison is a World Heritage-listed fortress that witnessed 44 hangings on its permanent gallows. The most notorious spirit is child poisoner Martha Rendell, the only woman ever hanged in Western Australia, alongside executed bush-ranger Moondyne Joe. Night torchlight tours frequently encounter sudden icy drafts, disembodied weeping in solitary cells, and green ectoplasmic mists in the execution chamber.',
      'เรือนจำแห่งนี้ปิดทำการในปี 1991 หลังเกิดเหตุจลาจลครั้งใหญ่ที่นักโทษจุดไฟเผาเรือนจำเพื่อประท้วงสภาพความเป็นอยู่อันเลวร้าย',
      'Decommissioned in 1991 following a violent riot over archaic sanitation conditions, its subterranean tunnels and cellblocks remain a focal point of Australian ghost lore.',
      'ห้ามยืนเหยียบตรงจุดเปิดของประตูกลแดนประหารแขวนคอ',
      'Never stand directly atop the gallows trapdoor mechanism.',
      'https://i.ytimg.com/vi/prgfVSFMniE/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/prgfVSFMniE/hqdefault.jpg","title":"เรือนจำฟรีแมนเทิล (แดนประหารแดนสยองแห่งออสเตรเลียตะวันตก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=prgfVSFMniE","title":"MOST Haunted JAIL + DEATH ROW | Terrifying Paranormal Evidence | Fremantle Prison Part 1","thumbnail":"https://i.ytimg.com/vi/prgfVSFMniE/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-quarantine-station-manly-sydney',
      'สถานีกักกันโรคแมนลี่ (ด่านกักโรคหมื่นวิญญาณแห่งซิดนีย์)',
      'The Manly Quarantine Station (Q Station Ghosts of Sydney Harbour)',
      'ghost',
      'นิวเซาท์เวลส์',
      'New South Wales',
      'นอร์ธเฮด แมนลี่ ซิดนีย์',
      'North Head, Manly, Sydney',
      -33.8167,
      151.2833,
      'jungle_curse',
      'สถานีกักกันโรคแห่งแรกของออสเตรเลีย ก่อตั้งขึ้นในปี 1832 บนแหลมนอร์ธเฮด บริเวณปากอ่าวซิดนีย์ เพื่อกักกันเรือสินค้าและผู้อพยพที่ติดเชื้อกาฬโรค ไข้ทรพิษ ไข้หวัดใหญ่สเปน และอหิวาตกโรค มีผู้เสียชีวิตที่นี่มากกว่า 500 ราย ผู้ป่วยจะถูกแยกตามชนชั้นวรรณะ และต้องอาศัยอยู่อย่างสิ้นหวัง ปัจจุบันเป็นหนึ่งในสถานที่ผีดุที่สุดในออสเตรเลีย มีรายงานวิญญาณพยาบาลสาว วิญญาณคนขุดสุสาน และเงาร่างที่คอยเฝ้ามองผู้คนจากหน้าต่างห้องอาบน้ำกรดคาร์โบลิก',
      'Operating from 1832 to 1984 on Sydney Harbour''s North Head, the Quarantine Station (Q Station) isolated inbound passenger ships afflicted with smallpox, bubonic plague, Spanish flu, and cholera. Over 500 passengers died in misery on this wind-swept cliff. Widely investigated by medium teams, sightings include nurse apparitions in 1918 uniforms, phantom children in the third-class dorms, and cold lingering dread inside the carbolic acid decontamination showers.',
      'มีรอยสลักชื่อ วันที่ และชื่อเรือของผู้ถูกกักกันหลายพันคนบนหน้าผาหินทรายริมทะเล เป็นอนุสรณ์แห่งความทุกข์ทรมานที่ยังคงปรากฏให้เห็น',
      'Over 1,000 historic rock inscriptions carved by quarantined passengers survive along the sandstone cliffs, commemorating dead family members and lost voyages.',
      'ห้ามลบหลู่รอยสลักชื่อผู้เสียชีวิตบนหน้าผาหินทรายสถานีกักกันแมนลี่',
      'Never deface or mock the historical passenger inscriptions carved along the North Head cliffs.',
      'https://i.ytimg.com/vi/_sHFLUsZQ5A/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/_sHFLUsZQ5A/hqdefault.jpg","title":"สถานีกักกันโรคแมนลี่ (ด่านกักโรคหมื่นวิญญาณแห่งซิดนีย์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=_sHFLUsZQ5A","title":"Still Standing: Sydney Quarantine Station","thumbnail":"https://i.ytimg.com/vi/_sHFLUsZQ5A/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-st-elmo-ghost-town-colorado',
      'เมืองผีสิงเซนต์เอลโม (วิญญาณแอนนาเบลล์ผู้พิทักษ์แห่งโคโลราโด)',
      'St. Elmo Ghost Town (The Spectral Vigil of Annabelle Stark)',
      'ghost',
      'โคโลราโด',
      'Colorado',
      'เซนต์เอลโม แชฟฟี',
      'St. Elmo, Chaffee County',
      38.7047,
      -106.3456,
      'creepy_wind',
      'เมืองเหมืองทองคำร้างในยุคตื่นทอง ก่อตั้งขึ้นในปี 1880 บนเทือกเขาซอวัตช์ รัฐโคโลราโด เป็นหนึ่งในเมืองผีสิงที่ได้รับการอนุรักษ์ไว้อย่างสมบูรณ์ที่สุดในอเมริกา บุคคลที่เป็นตำนานที่สุดคือ แอนนาเบลล์ สตาร์ก ''วิญญาณสกปรกแห่งเซนต์เอลโม'' หญิงสาวผู้ปฏิเสธที่จะทิ้งเมืองไปแม้เหมืองจะปิดและทางรถไฟจะหยุดวิ่ง เธอใช้ชีวิตอย่างโดดเดี่ยวจนสติฟั่นเฟือนและเสียชีวิตในปี 1960 ปัจจุบันมีพยานพบเห็นหญิงสาวผมยาวในชุดเดรสสีขาวยืนถือปืนลูกซองเฝ้าหน้าต่างโรงแรมโฮมคอมฟอร์ตเพื่อไล่ผู้บุกรุก',
      'St. Elmo is one of Colorado''s best-preserved mining ghost towns, founded in 1880 high in the Sawatch Range. When the gold veins ran dry and rail service ceased, eccentric resident Annabelle Stark refused to leave, living without electricity or running water until her death in 1960. Today, tourists and caretakers frequently glimpse Annabelle''s ghost standing at the second-story window of the Home Comfort Hotel, clutching a shotgun to ward off vandals.',
      'อาคารไม้โบราณกว่า 40 หลังยังคงตั้งตระหง่านอยู่ท่ามกลางหิมะ และชาวบ้านในละแวกเชื่อว่าวิญญาณของแอนนาเบลล์เป็นผู้ปกป้องไม่ให้เมืองถูกไฟไหม้',
      'Local lore credits Annabelle''s protective spirit with safeguarding the fragile wooden settlement from the devastating mountain forest fires that destroyed neighboring camps.',
      'ห้ามขโมยเศษไม้หรือสิ่งของโบราณออกจากอาคารร้างในเมืองเซนต์เอลโม',
      'Never take relics, wood, or antique nails from St. Elmo''s historic structures.',
      'https://i.ytimg.com/vi/QhWfuOg47Ik/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/QhWfuOg47Ik/hqdefault.jpg","title":"เมืองผีสิงเซนต์เอลโม (วิญญาณแอนนาเบลล์ผู้พิทักษ์แห่งโคโลราโด)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=QhWfuOg47Ik","title":"I Visited Colorado’s Haunted Ghost Town – St. Elmo | The Story of Annabelle Stark","thumbnail":"https://i.ytimg.com/vi/QhWfuOg47Ik/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-bannack-ghost-town-montana',
      'เมืองผีสิงแบนแน็ค (คำสาปนายอำเภอโจรและวิญญาณโดโรธีแห่งมอนแทนา)',
      'Bannack Ghost Town (The Gallows of Sheriff Plummer and Dorothy Dunn)',
      'ghost',
      'มอนแทนา',
      'Montana',
      'แบนแน็ค บีเวอร์เฮด',
      'Bannack, Beaverhead County',
      45.1611,
      -112.9972,
      'creepy_wind',
      'เมืองหลวงแห่งแรกของมอนแทนา ก่อตั้งขึ้นในปี 1862 หลังการค้นพบทองคำริมลำห้วยกราสส์ฮอปเปอร์ เมืองนี้เต็มไปด้วยกฎหมายบ้านป่าเมืองเถื่อน โดยนายอำเภอเฮนรี พลัมเมอร์ กลับเป็นหัวหน้าแก๊งโจรปล้นฆ่าคนเดินทาง จนกลุ่มศาลเตี้ย ''Vigilantes'' ลุกขึ้นมาจับเขาและพวกแขวนคอที่ตะแลงแกงหน้าเมือง นอกจากนี้ยังมีวิญญาณของ ''โดโรธี ดันน์'' เด็กหญิงวัยรุ่นที่จมน้ำตายในสระน้ำปี 1916 มักปรากฏตัวในชุดกระโปรงสีน้ำเงินที่โรงแรมมีดเปโปลส์โฮเต็ล',
      'Bannack was Montana''s first territorial capital, founded during the 1862 gold strike along Grasshopper Creek. Lawlessness peaked when Sheriff Henry Plummer was discovered to be the secret leader of the murderous ''Innocents'' outlaw gang, resulting in the Montana Vigilantes hanging him from his own gallows in 1864. Spirits abound in the preserved state park, including Plummer''s phantom and 16-year-old Dorothy Dunn, who drowned in 1916 and manifests in a blue dress inside Meade Hotel.',
      'โรงแรมมีด (Meade Hotel) ซึ่งเดิมเคยเป็นศาลากลาง มีประวัติการพบเห็นลูกไฟวิญญาณและกลิ่นแป้งเด็กโบราณลอยฟุ้งอย่างไม่มีสาเหตุ',
      'The Meade Hotel remains the epicenter of paranormal activity, where infant crying and full-figure apparitions in Victorian garments are frequently photographed.',
      'ห้ามยืนใต้คานตะแลงแกงประหารเก่าของนายอำเภอพลัมเมอร์ยามพลบค่ำ',
      'Never stand beneath the historic gallows beam at Plummer''s hanging site at dusk.',
      'https://i.ytimg.com/vi/SrgN3PDtxyI/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/SrgN3PDtxyI/hqdefault.jpg","title":"เมืองผีสิงแบนแน็ค (คำสาปนายอำเภอโจรและวิญญาณโดโรธีแห่งมอนแทนา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=SrgN3PDtxyI","title":"Dark History | Ghost Towns and More | Episode 7 | Bannack, Montana","thumbnail":"https://i.ytimg.com/vi/SrgN3PDtxyI/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-calico-ghost-town-california',
      'เมืองผีสิงคาลิโค (วิญญาณเหมืองเงินแห่งทะเลทรายโมฮาวี)',
      'Calico Ghost Town (The Silver Miners of the Mojave Desert)',
      'ghost',
      'แคลิฟอร์เนีย',
      'California',
      'เยอร์โม ซานเบอร์นาร์ดิโน',
      'Yermo, San Bernardino County',
      34.9492,
      -116.8644,
      'creepy_wind',
      'เมืองเหมืองแร่เงินที่เคยรุ่งเรืองสุดขีดในปี 1881 ท่ามกลางหุบเขาดินแดงแห่งทะเลทรายโมฮาวี มีประชากรกว่า 1,200 คนและมีบาร์เหล้าถึง 22 แห่ง แต่เมื่อราคาแร่เงินตกต่ำ เมืองก็ถูกทิ้งร้างกลายเป็นเมืองผีสิงในปี 1907 วิญญาณที่โด่งดังที่สุดคือ ''ลูซี่ เลน'' หญิงชราผู้เปิดร้านค้าทั่วไปและใช้ชีวิตอยู่ที่นี่จนวาระสุดท้าย วิญญาณของเธอมักปรากฏในชุดสีดำเดินตรวจตราบ้านของเธอ และมีวิญญาณ ''ทอร์เกอร์สัน'' ครูใหญ่ที่ยังคงสอนหนังสืออยู่ในโรงเรียนเก่า',
      'Calico was a booming Mojave Desert silver-mining settlement founded in 1881 that yielded over $20 million in silver ore before collapsing when silver prices plummeted. Restored by Walter Knott (creator of Knott''s Berry Farm), the ghost town is inhabited by several well-documented spirits: Lucy Lane, the town''s beloved general store proprietor who manifests in a black lace dress, and the phantom schoolteacher Dorsey roaming the red-rock schoolhouse.',
      'ในสุสานคาลิโคบูทฮิลล์ (Calico Boot Hill) มีหลุมศพของคนงานเหมืองที่เสียชีวิตจากอุบัติเหตุระเบิดดินปืนและโรคระบาดกว่า 130 หลุม',
      'The Boot Hill cemetery on the canyon edge holds over a hundred rough wooden grave markers, surrounded by intense reports of phantom mining lantern lights.',
      'ห้ามเดินเข้าไปในอุโมงค์เหมืองเงินแม็กกี้ไมน์เก่าโดยไม่มีไกด์นำทาง',
      'Do not venture into unlit adits and shafts of the historic Maggie Mine.',
      'https://i.ytimg.com/vi/ILv_uPHtpyM/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/ILv_uPHtpyM/hqdefault.jpg","title":"เมืองผีสิงคาลิโค (วิญญาณเหมืองเงินแห่งทะเลทรายโมฮาวี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=ILv_uPHtpyM","title":"Calico Ghost Town California History","thumbnail":"https://i.ytimg.com/vi/ILv_uPHtpyM/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-castle-stuart-inverness-scotland',
      'ปราสาทสจวร์ต (ห้องมรณะสี่ทิศและสตรีชุดเขียวแห่งอินเวอร์เนสส์)',
      'Castle Stuart (The Murder Room and the Green Lady)',
      'ghost',
      'ไฮแลนด์',
      'Highlands',
      'เพ็ตตี อินเวอร์เนสส์',
      'Petty, Inverness-shire',
      57.5342,
      -4.0833,
      'creepy_wind',
      'ปราสาทหอคอยสไตล์สก็อตช์บารอนเนียล สร้างขึ้นในปี 1625 ริมอ่าวมอเรย์เฟิร์ธ ใกล้เมืองอินเวอร์เนสส์ ประเทศสกอตแลนด์ ปราสาทแห่งนี้มีชื่อเสียงจาก ''ห้องนอนชั้นบนสุด'' ซึ่งขึ้นชื่อเรื่องความเฮี้ยนจนเอิร์ลแห่งมอร์เรย์เคยท้าทายเงินรางวัลก้อนโตให้ใครก็ตามที่กล้านอนพักค้างคืน คนแรกที่รับคำท้าตื่นมาพบร่างฉีกขาดกระโดดลงมาตายที่ลานหิน คนที่สองถูกพบกลายเป็นศพหน้าตาบิดเบี้ยวด้วยความสยดสยอง นอกจากนี้ยังมีวิญญาณ ''กรีนเลดี้'' สตรีชุดเขียวที่เดินลอยผ่านห้องโถง',
      'Castle Stuart is a 1625 tower fortress overlooking the Moray Firth in the Scottish Highlands. The castle''s top-floor chamber achieved terrifying fame when the Earl of Moray offered a cash reward to anyone brave enough to spend a night alone in it. A local poacher who accepted was found dead in the courtyard having plummeted from the window with a face frozen in absolute terror. The castle is also frequented by the tragic ''Green Lady'' ghost floating down the spiral stairs.',
      'ปัจจุบันปราสาทได้รับการบูรณะเป็นโรงแรมหรูและสนามกอล์ฟระดับโลก แต่ตำนานห้องนอนต้องห้ามยังคงเป็นที่เล่าขานในหมู่ชาวสก็อต',
      'Now integrated into Castle Stuart Golf Links, the historic tower''s haunted upper chamber remains one of Scotland''s most chilling paranormal legends.',
      'ห้ามพักค้างคืนตามลำพังในห้องนอนชั้นบนสุดของปราสาทสจวร์ต',
      'Never accept a dare to sleep alone in the top turret chamber of Castle Stuart.',
      'https://i.ytimg.com/vi/t2HozAGZeKE/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/t2HozAGZeKE/hqdefault.jpg","title":"ปราสาทสจวร์ต (ห้องมรณะสี่ทิศและสตรีชุดเขียวแห่งอินเวอร์เนสส์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=t2HozAGZeKE","title":"Ghost caught on camera in daylight on a Scottish river.","thumbnail":"https://i.ytimg.com/vi/t2HozAGZeKE/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-dalhousie-castle-grey-lady-scotland',
      'ปราสาทดัลฮูซี (วิญญาณเลดี้แคเธอริน สตรีชุดเทาแห่งมิดโลเธียน)',
      'Dalhousie Castle (The Grey Lady of Lady Catherine)',
      'ghost',
      'มิดโลเธียน',
      'Midlothian',
      'บอนนีริกก์ เอดินบะระ',
      'Bonnyrigg, Edinburgh',
      55.8597,
      -3.0789,
      'whisper',
      'ปราสาทหินทรายสีแดงอายุ 800 ปี ริมแม่น้ำเซาท์เอสก์ ใกล้เมืองเอดินบะระ ประเทศสกอตแลนด์ เคยต้อนรับกษัตริย์ทั้งเอ็ดเวิร์ดที่ 1 และเซอร์วิลเลียม วอลเลซ วิญญาณที่โด่งดังที่สุดคือ ''เลดี้แคเธอริน'' หรือเกรย์เลดี้ หญิงสาววัย 16 ปีในศตวรรษที่ 16 ที่ตกหลุมรักคนรับใช้ในปราสาท เมื่อพ่อแม่ของเธอจับได้จึงสั่งขังเธอไว้ในห้องใต้หลังคาบนหอคอยจนเธออดอาหารตาย วิญญาณของเธอมักปรากฏตัวในชุดผ้าไหมสีเทา เดินทะลุกำแพง โบกมือทักทายแขก และดึงผ้าห่มของผู้มาเยือน',
      'Dating back to the 13th century, Dalhousie Castle has hosted figures like William Wallace, Mary Queen of Scots, and Oliver Cromwell. The castle is eternally haunted by ''The Grey Lady'', the ghost of Lady Catherine, a 16-year-old maiden who was locked in the castle turret and starved to death in the 16th century by her furious parents after falling in love with a stable hand. Her elegant grey silhouette is routinely seen gliding through walls and standing beside guests'' beds.',
      'ปราสาทแห่งนี้เปิดเป็นโรงแรมหรู และแขกในพิธีแต่งงานมักถ่ายภาพติดเงาร่างโปร่งแสงสีเทายืนร่วมแสดงความยินดีในห้องจัดเลี้ยง',
      'Operating as Dalhousie Castle Hotel, wedding guests frequently snap photographs displaying misty grey apparitions lingering in the historic banquet hall.',
      'ห้ามทุบหรือเคาะผนังหอคอยห้องคุมขังโบราณของเลดี้แคเธอริน',
      'Do not strike or desecrate the turret walls of Lady Catherine''s confinement tower.',
      'https://i.ytimg.com/vi/njD_eZiTkB8/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/njD_eZiTkB8/hqdefault.jpg","title":"ปราสาทดัลฮูซี (วิญญาณเลดี้แคเธอริน สตรีชุดเทาแห่งมิดโลเธียน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=njD_eZiTkB8","title":"Dalhousie Castle","thumbnail":"https://i.ytimg.com/vi/njD_eZiTkB8/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-wat-phra-kaew-emerald-buddha',
      'วัดพระศรีรัตนศาสดาราม (พระพุทธมหามณีรัตนปฏิมากร พระแก้วมรกต)',
      'Wat Phra Kaew (The Temple of the Emerald Buddha)',
      'sacred',
      'กรุงเทพมหานคร',
      'Bangkok',
      'พระบรมมหาราชวัง พระนคร',
      'Phra Borom Maha Ratchawang, Phra Nakhon',
      13.7516,
      100.4927,
      'temple_bell',
      'พระอารามหลวงคู่บ้านคู่เมืองที่ประดิษฐาน ''พระพุทธมหามณีรัตนปฏิมากร'' หรือพระแก้วมรกต พระพุทธรูปศักดิ์สิทธิ์คู่แผ่นดินสยามที่แกะสลักจากหยกเขียวบริสุทธิ์ ตำนานเล่าว่าพระอินทร์และพระวิษณุกรรมร่วมกันสร้างขึ้นในชมพูทวีป พระแก้วมรกตเดินทางผ่านอาณาจักรโบราณ ทั้งปาฏลีบุตร ศรีลังกา กัมพูชา เชียงราย ลำปาง เชียงใหม่ และเวียงจันทน์ ก่อนจะอัญเชิญมาประดิษฐาน ณ พระนครแห่งนี้ เชื่อกันว่าเป็นมิ่งขวัญศูนย์รวมจิตใจและความร่มเย็นเป็นสุขของสยามประเทศ',
      'Wat Phra Kaew, located within the Grand Palace complex in Bangkok, is Thailand''s most revered Buddhist temple. It enshrines the Emerald Buddha (Phra Kaew Morakot), an ancient, potent palladium carved from a single block of translucent green jadeite. Traditional chronicles attribute its divine creation to Indra and Nagasena in ancient India, journeying through ancient empires before King Rama I enshrined it in 1784 to guard the perpetual peace and prosperity of the kingdom.',
      'พระมหากษัตริย์จะเสด็จพระราชดำเนินประกอบพระราชพิธีเปลี่ยนเครื่องทรงพระแก้วมรกตเป็นประจำทุกปีตามฤดูกาล (ฤดูร้อน ฤดูฝน ฤดูหนาว)',
      'Three times a year, in a sacred ritual performed exclusively by the King of Thailand, the Emerald Buddha''s seasonal vestments (Summer, Rainy, and Winter) are ritually changed.',
      'ห้ามแต่งกายไม่สุภาพหรือถ่ายภาพภายในพระอุโบสถวัดพระแก้ว',
      'Strict dress codes apply; photography is strictly prohibited inside the main ordination hall.',
      'https://i.ytimg.com/vi/FVD90o-bybE/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/FVD90o-bybE/hqdefault.jpg","title":"วัดพระศรีรัตนศาสดาราม (พระพุทธมหามณีรัตนปฏิมากร พระแก้วมรกต)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=FVD90o-bybE","title":"Wat Phra Kaew — The Sacred Temple of the Emerald Buddha That Protects All of Thailand","thumbnail":"https://i.ytimg.com/vi/FVD90o-bybE/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-wat-phra-that-lampang-luang',
      'วัดพระธาตุลำปางหลวง (ปาฏิหาริย์เงาพระธาตุกลับหัวแห่งล้านนา)',
      'Wat Phra That Lampang Luang (The Miraculous Inverted Pagoda Shadow)',
      'sacred',
      'ลำปาง',
      'Lampang',
      'เกาะคา',
      'Ko Kha',
      18.2172,
      99.3886,
      'temple_bell',
      'วัดไม้สักโบราณอายุกว่าพันปีที่ยังคงความสมบูรณ์แห่งศิลปะล้านนา ประดิษฐานพระบรมสารีริกธาตุส่วนพระนลาฏ (หน้าผาก) และพระศอ (ลำคอ) ความมหัศจรรย์อันลือเลื่องคือ ''เงาพระธาตุกลับหัว'' ภายในวิหารพระพุทธและซุ้มพระบาท ที่แสงจากภายนอกส่องผ่านรูเข็มเล็กๆ บนผนังไม้ เกิดเป็นภาพเงาขององค์พระธาตุหัวกลับสะท้อนลงบนผืนผ้าใบหรือพื้นไม้ได้อย่างน่าอัศจรรย์ตามหลักธรรมชาติและพลังศรัทธา',
      'Wat Phra That Lampang Luang is a breathtaking, fortified teak temple founded in the 8th century, representing the zenith of classical Lanna architecture. Enshrining sacred hair and bone relics of Gautama Buddha, the temple is celebrated for its natural optical miracle: an inverted, full-color camera obscura projection of the golden chedi appearing on white cloth inside the darkened Viharn Phra Phut and sacred foot pavilion.',
      'ม่อนหินแก้วและกำแพงแลงโบราณเคยเป็นสมรภูมิที่หนานทิพย์ช้าง วีรบุรุษแห่งลำปาง ยิงปืนลอบสังหารท้าวลิ้นก่านแม่ทัพพม่าเพื่อกอบกู้เมืองลำปางในปี 1732',
      'The historic bullet hole from Nan Thip Chang''s 1732 assassination of the occupying Burmese commander remains preserved in the bronze balustrade.',
      'ห้ามสุภาพสตรีขึ้นไปบนมณฑปพระพุทธบาทตามธรรมเนียมโบราณล้านนา',
      'Women are respectfully prohibited from ascending the inner sanctum of the Phra Bat pavilion per ancient Lanna tradition.',
      'https://i.ytimg.com/vi/qbtJLVEKnB4/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/qbtJLVEKnB4/hqdefault.jpg","title":"วัดพระธาตุลำปางหลวง (ปาฏิหาริย์เงาพระธาตุกลับหัวแห่งล้านนา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=qbtJLVEKnB4","title":"[Eng]: This 500 Year Old Thai Temple Hides a Real Camera","thumbnail":"https://i.ytimg.com/vi/qbtJLVEKnB4/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-mahabodhi-temple-bodh-gaya',
      'มหาโพธิเจดีย์พุทธคยา (ต้นพระศรีมหาโพธิ์และพระแท่นวัชรอาสน์แห่งการตรัสรู้)',
      'Mahabodhi Temple Complex (The Bodhi Tree of Enlightenment at Bodh Gaya)',
      'sacred',
      'พิหาร',
      'Bihar',
      'คยา พุทธคยา',
      'Gaya, Bodh Gaya',
      24.6961,
      84.9914,
      'temple_bell',
      'สถานที่ศักดิ์สิทธิ์สูงสุดของชาวพุทธทั่วโลก จุดที่พระโคตมพุทธเจ้าทรงตรัสรู้อนุตตรสัมมาสัมโพธิญาณใต้ต้นพระศรีมหาโพธิ์ เมื่อ 588 ปีก่อนคริสตกาล ณ ริมฝั่งแม่น้ำเนรัญชรา มหาโพธิเจดีย์ทรงพีระมิดหินทรายสูง 55 เมตร สร้างขึ้นในยุคคุปตะ ข้างพระเจดีย์คือ ''พระแท่นวัชรอาสน์'' (Vajrasana) บัลลังก์เพชรที่พระพุทธองค์ประทับนั่งสมาธิ พระมหากษัตริย์อโศกมหาราชได้เสด็จมาทรงสร้างสถูปและเสาหินศิลาจารึกไว้ที่นี่',
      'The Mahabodhi Temple in Bodh Gaya, Bihar, is Buddhism''s most sacred pilgrimage site, marking the exact spot where Prince Siddhartha Gautama attained supreme enlightenment under the Bodhi Tree in 588 BCE. The soaring 55-meter pyramidal sandstone spire, originally patronized by Emperor Ashoka in the 3rd century BCE, stands beside the Vajrasana (''Diamond Throne''), revered as the navel of the earth and the spiritual center of Buddhist devotion.',
      'ต้นพระศรีมหาโพธิ์ต้นปัจจุบันเป็นหน่อเนื้อเชื้อไขสายตรงจากต้นเดิมในสมัยพุทธกาล โดยสืบสายพันธุ์ผ่านหน่อต้นพระศรีมหาโพธิ์ที่พระนางสังฆมิตตามหาเถรีนำไปปลูกที่อนุราธปุระในศรีลังกา',
      'The current Bodhi tree is a direct descendant grafted from the sacred Sri Maha Bodhi in Anuradhapura, Sri Lanka, which itself was brought as a sapling by Ashoka''s daughter Sanghamitta.',
      'ห้ามเด็ดหรือหักกิ่งใบของต้นพระศรีมหาโพธิ์โดยเด็ดขาด',
      'Never break branches or pluck leaves directly from the sacred Bodhi Tree.',
      'https://i.ytimg.com/vi/jJx2epaYaho/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/jJx2epaYaho/hqdefault.jpg","title":"มหาโพธิเจดีย์พุทธคยา (ต้นพระศรีมหาโพธิ์และพระแท่นวัชรอาสน์แห่งการตรัสรู้)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=jJx2epaYaho","title":"【Bodh Gaya - The Sacred Land of Buddhahood】 Documentary  |  History of Bodh Gaya &  Mahabodhi Temple","thumbnail":"https://i.ytimg.com/vi/jJx2epaYaho/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-pura-besakih-mother-temple-bali',
      'ปุระเบซากิห์ (มหาเทวาลัยแม่แห่งเกาะบาหลีเชิงภูเขาไฟอากุง)',
      'Pura Besakih (The Mother Temple of Bali on Mount Agung)',
      'sacred',
      'บาหลี',
      'Bali',
      'เบซากิห์ คารังกาเซ็ม',
      'Besakih, Karangasem',
      -8.3739,
      115.4508,
      'temple_bell',
      'หมู่วิหารฮินดูที่ใหญ่และศักดิ์สิทธิ์ที่สุดบนเกาะบาหลี ตั้งอยู่บนเนินเขาลาดชันสูง 1,000 เมตรเชิงภูเขาไฟอากุง (Gunung Agung) ซึ่งชาวบาหลีเชื่อว่าเป็นศูนย์กลางจักรวาลและที่สถิตของทวยเทพ วิหารประกอบด้วยศาลเจ้าเมรู (Meru) ทรงยอดแหลมลดหลั่นกันถึง 86 วิหาร ในปี 1963 เมื่อภูเขาไฟอากุงเกิดการปะทุครั้งใหญ่ ลาวาและหินภูเขาไฟไหลเฉียดผ่านวิหารไปเพียงไม่กี่เมตรโดยไม่ทำลายโครงสร้างหลัก ชาวบาหลีเชื่อว่าเป็นปาฏิหาริย์แห่งความคุ้มครองของทวยเทพ',
      'Perched 1,000 meters high on the southwest slopes of the holy volcano Mount Agung, Pura Besakih is the ''Mother Temple'' of Balinese Hinduism. Comprising 86 individual temples dedicated to the Hindu trinity (Brahma, Shiva, Vishnu), its towering thatch-roofed Meru towers align directly with the celestial heavens. In 1963, during a catastrophic volcanic eruption of Mount Agung, deadly pyroclastic flows missed the sanctuary complex by mere yards, hailed by the islanders as a divine miracle of protection.',
      'ก่อตั้งขึ้นในศตวรรษที่ 8 โดยฤาษีมาร์กันเดยา (Rsi Markandeya) ผู้ฝังหินปัญจธาตุและเครื่องหอมศักดิ์สิทธิ์ไว้ใต้ฐานรากเพื่อขับไล่โรคระบาดและสิ่งชั่วร้าย',
      'Founded in the 8th century by the sage Rsi Markandeya, who buried the sacred Pancadatu (five metal alloys) into the volcano soil to sanctify the island.',
      'ห้ามสวมกางเกงขาสั้นเข้าเขตวิหารโดยไม่นุ่งโสร่งซารุงและผูกผ้าคาดเอวสลามปัง',
      'Never enter the temple grounds without traditional sarong and sash attire.',
      'https://i.ytimg.com/vi/GeLSQOwvydI/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/GeLSQOwvydI/hqdefault.jpg","title":"ปุระเบซากิห์ (มหาเทวาลัยแม่แห่งเกาะบาหลีเชิงภูเขาไฟอากุง)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=GeLSQOwvydI","title":"PURA RAKSASA | BESAKIH TEMPLE | BALI","thumbnail":"https://i.ytimg.com/vi/GeLSQOwvydI/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-church-of-the-nativity-bethlehem',
      'โบสถ์แห่งการประสูติ (ถ้ำศักดิ์สิทธิ์และดาวเงินแห่งเบธเลเฮม)',
      'The Church of the Nativity (The Holy Grotto and Silver Star of Bethlehem)',
      'sacred',
      'เวสต์แบงก์',
      'West Bank',
      'เมืองเบธเลเฮม',
      'Bethlehem',
      31.7042,
      35.2075,
      'temple_bell',
      'หนึ่งในโบสถ์คริสต์ที่เก่าแก่ที่สุดในโลกที่ยังคงเปิดใช้งานอย่างต่อเนื่อง สร้างขึ้นในปี ค.ศ. 327 โดยจักรพรรดิคอนสแตนตินมหาราชและจักรพรรดินีเฮเลนา เหนือถ้ำธรรมชาติที่เชื่อว่าเป็นสถานที่ประสูติของพระเยซูคริสต์ ภายในถ้ำใต้แท่นบูชาหลักมี ''ดาวเงินสิบสี่แฉก'' (Fourteen-Pointed Silver Star) ฝังอยู่บนพื้นหินอ่อน พร้อมข้อความภาษาละตินว่า ''Hic de Virgine Maria Jesus Christus natus est'' (ณ ที่นี้ พระเยซูคริสต์ได้ประสูติจากพระแม่มารี)',
      'Commissioned by Emperor Constantine and his mother Saint Helena in 327 CE, the Church of the Nativity in Bethlehem is among the oldest continuously operating Christian sanctuaries on Earth. Built directly over the Grotto of the Nativity, the subterranean cave where Jesus of Nazareth was born, the holy site is marked by an iconic 14-pointed silver star set into marble beneath an altar hung with eternal oil lamps.',
      'ประตูทางเข้าหลักถูกลดขนาดลงในยุคออตโตมันจนเหลือเพียงช่องเตี้ยๆ เรียกว่า ''ประตูแห่งความถ่อมตน'' (Door of Humility) เพื่อป้องกันไม่ให้ผู้รุกรานขี่ม้าเข้าไปในวิหาร',
      'The fortress-like exterior features the ''Door of Humility'', a miniature limestone portal constructed so visitors must bow their heads and horse-mounted raiders could not breach the nave.',
      'ห้ามยืนบังหรือส่งเสียงดังรอบดาวเงินศักดิ์สิทธิ์ในถ้ำใต้ดิน',
      'Do not block pilgrims or speak loudly while approaching the sacred Silver Star of the Grotto.',
      'https://i.ytimg.com/vi/29U7yn9fi6Y/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/29U7yn9fi6Y/hqdefault.jpg","title":"โบสถ์แห่งการประสูติ (ถ้ำศักดิ์สิทธิ์และดาวเงินแห่งเบธเลเฮม)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=29U7yn9fi6Y","title":"Bethlehem: Place Jesus Was Born! Church of the Nativity, Manger, Wise Men, Where Christmas Began!","thumbnail":"https://i.ytimg.com/vi/29U7yn9fi6Y/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-western-wall-kotel-jerusalem',
      'กำแพงร้องไห้แห่งเยรูซาเล็ม (ซากกำแพงตะวันตกพระวิหารศักดิ์สิทธิ์)',
      'The Western Wall (The Kotel of Jerusalem and the Divine Presence)',
      'sacred',
      'เยรูซาเล็ม',
      'Jerusalem District',
      'โอลด์ซิตี เยรูซาเล็ม',
      'Old City, East Jerusalem',
      31.7767,
      35.2342,
      'temple_bell',
      'สถานที่ศักดิ์สิทธิ์ที่สุดของศาสนายิวที่ผู้คนสามารถเข้าถึงและสวดภาวนาได้ คือกำแพงหินปูนโบราณขนาดมหึมาที่หลงเหลือจากการค้ำจุนลานพระวิหารหลังที่สอง (Second Temple) ของกษัตริย์เฮโรดมหาราช ซึ่งถูกกองทัพโรมันทำลายในปี ค.ศ. 70 ชาวยิวเชื่อว่า ''เชคินาห์'' (Shechinah) หรือพระบารมีของพระเจ้าไม่เคยละทิ้งกำแพงนี้ ผู้ศรัทธาจากทั่วโลกจะเดินทางมาเขียนคำอธิษฐานลงบนเศษกระดาษและสอดไว้ตามร่องหินกำแพง พร้อมทั้งร่ำไห้รำลึกถึงการสูญสิ้นของพระวิหาร',
      'The Western Wall, or Kotel, in the Old City of Jerusalem is Judaism''s holiest prayer site, being the sole surviving retaining wall of the Second Temple esplanade expanded by King Herod the Great before its catastrophic Roman destruction in 70 CE. Rabbinic tradition teaches that the Divine Presence (Shechinah) never departs from the Western Wall. Millions of pilgrims tuck personal written prayer petitions (kvitlach) into the crevices between its massive limestone ashlars.',
      'ก้อนหินที่ใหญ่ที่สุดในอุโมงค์ใต้กำแพง ''Western Stone'' มีน้ำหนักมากกว่า 500 ตัน เป็นหนึ่งในหินก่อสร้างที่หนักที่สุดในโลกโบราณที่ยกขึ้นด้วยเทคโนโลยีปริศนา',
      'Subterranean tunnels expose the monolithic ''Western Stone'', an ancient foundation block weighing an astounding 570 tons placed with razor-sharp precision without mortar.',
      'ห้ามหันหลังให้กำแพงทันทีเมื่อเดินถอยออกจากลานสวดมนต์ตามธรรมเนียมยิวโบราณ',
      'Never turn your back abruptly to the wall when leaving the prayer courtyard; walk backward respectfully.',
      'https://i.ytimg.com/vi/ZLqHiPdy86g/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/ZLqHiPdy86g/hqdefault.jpg","title":"กำแพงร้องไห้แห่งเยรูซาเล็ม (ซากกำแพงตะวันตกพระวิหารศักดิ์สิทธิ์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=ZLqHiPdy86g","title":"The Western Wall: From Ancient times to the Present","thumbnail":"https://i.ytimg.com/vi/ZLqHiPdy86g/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-santiago-de-compostela-cathedral',
      'มหาวิหารซันเตียโกเดกอมโปสเตลา (สุสานอัครสาวกนักบุญยากอบและเส้นทางกามิโน)',
      'Cathedral of Santiago de Compostela (The Shrine of Saint James)',
      'sacred',
      'กาลิเซีย',
      'Galicia',
      'ซันเตียโกเดกอมโปสเตลา อาโกรุญญา',
      'Santiago de Compostela, A Coruna',
      42.8806,
      -8.5447,
      'temple_bell',
      'จุดหมายปลายทางอันศักดิ์สิทธิ์ของเส้นทางแสวงบุญ ''กามิโนเดซันเตียโก'' (Camino de Santiago) ที่มีประวัติศาสตร์ยาวนานกว่าพันปี มหาวิหารสไตล์โรมาเนสก์และบาโรกแห่งนี้สร้างขึ้นเหนือหลุมฝังศพของ ''นักบุญยากอบ'' (Saint James the Greater) หนึ่งในสิบสองอัครสาวกของพระเยซู ซึ่งเชื่อว่าถูกค้นพบโดยฤาษีเปลาโยในศตวรรษที่ 9 ตามการชี้ทางของดวงดาวประกายแสงบนท้องฟ้า ไฮไลต์ศักดิ์สิทธิ์คือ ''โบตาฟูไมโร'' (Botafumeiro) กระถางกำยานขนาดยักษ์หนัก 80 กิโลกรัมที่แกว่งด้วยเชือกข้ามห้องโถงวิหารด้วยความเร็วสูง',
      'The Cathedral of Santiago de Compostela in northwestern Spain is the culminating destination of the legendary Camino de Santiago pilgrimage route. Constructed between 1075 and 1211, it enshrines the tomb and holy relics of Saint James the Greater, miraculously rediscovered in the 9th century by a hermit guided by celestial star clusters. Celebrated rituals include embracing the gilded statue of the Apostle and the dramatic swinging of the colossal Botafumeiro incense censer across the transept.',
      'สัญลักษณ์หอยเชลล์ (Scallop Shell) กลายเป็นตราสัญลักษณ์ของนักแสวงบุญทั่วโลกที่เดินเท้าข้ามเทือกเขาพิเรนีสมายังวิหารแห่งนี้',
      'Pilgrims display the iconic scallop shell badge, historically dipped into Galician waters as proof of completing the arduous trans-European trek.',
      'ห้ามยืนขวางหรือสัมผัสเชือกขณะแกว่งกระถางกำยานโบตาฟูไมโร',
      'Do not obstruct the path of the swinging Botafumeiro during solemn high mass.',
      'https://i.ytimg.com/vi/blK3IF51B0M/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/blK3IF51B0M/hqdefault.jpg","title":"มหาวิหารซันเตียโกเดกอมโปสเตลา (สุสานอัครสาวกนักบุญยากอบและเส้นทางกามิโน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=blK3IF51B0M","title":"Camino de Santiago Full Doumentary (The Way of St. James )","thumbnail":"https://i.ytimg.com/vi/blK3IF51B0M/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-sanctuary-of-our-lady-fatima',
      'สักการสถานแม่พระประจักษ์แห่งฟาตีมา (ปาฏิหาริย์ดวงอาทิตย์เต้นระบำ)',
      'Sanctuary of Our Lady of Fatima (The Miracle of the Dancing Sun)',
      'sacred',
      'ซังตาไรช์',
      'Santarem',
      'ฟาตีมา โอเรม',
      'Fatima, Ourem',
      39.6317,
      -8.6733,
      'temple_bell',
      'สถานที่แสวงบุญระดับโลกในประเทศโปรตุเกส จุดกำเนิดจากเหตุการณ์แม่พระประจักษ์ต่อเด็กเลี้ยงแกะสามคน ได้แก่ ลูเซีย, ฟรันซิสโก และยาซินทา ในปี 1917 เหตุการณ์ครั้งประวัติศาสตร์เกิดขึ้นในวันที่ 13 ตุลาคม 1917 เมื่อมีผู้คนมากกว่า 70,000 คนรวมตัวกันท่ามกลางสายฝน และได้เป็นพยานใน ''ปาฏิหาริย์แห่งดวงอาทิตย์'' (Miracle of the Sun) ดวงอาทิตย์หมุนวน เปลี่ยนสี และพุ่งตรงลงมายังพื้นโลก เสื้อผ้าที่เปียกชุ่มแห้งสนิทในพริบตา พร้อมการเปิดเผยความลับสามประการแห่งฟาตีมา',
      'The Sanctuary of Our Lady of Fatima in central Portugal commemorates the 1917 Marian apparitions witnessed by three young shepherd children: Lucia dos Santos and Francisco and Jacinta Marto. On October 13, 1917, over 70,000 witnesses, including secular journalists, beheld the awe-inspiring ''Miracle of the Sun'', where the sun reportedly zig-zagged toward Earth, casting vivid rainbow colors and instantaneously drying drenched fields. The site draws millions seeking physical healing and spiritual solace.',
      'กระสุนปืนที่ลอบยิงสมเด็จพระสันตะปาปาจอห์น ปอลที่ 2 ในปี 1981 ถูกนำมาประดับไว้ในมงกุฎของรูปปั้นแม่พระฟาตีมา หลังจากพระองค์เชื่อว่าแม่พระทรงช่วยเบี่ยงวิถีกระสุนให้รอดชีวิต',
      'Pope John Paul II credited Our Lady of Fatima with saving his life during the 1981 assassination attempt, donating the extracted bullet to be mounted into the Virgin''s royal crown.',
      'ห้ามยืนขวางทางเดินคุกเข่าแสวงบุญบนลานหินอ่อนกลางแจ้ง',
      'Do not step across or interrupt pilgrims crawling the marble penitential walkway on their knees.',
      'https://i.ytimg.com/vi/m9h3ekyKwkE/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/m9h3ekyKwkE/hqdefault.jpg","title":"สักการสถานแม่พระประจักษ์แห่งฟาตีมา (ปาฏิหาริย์ดวงอาทิตย์เต้นระบำ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=m9h3ekyKwkE","title":"The Miracle of Fatima: Why 6 Million Pilgrims Still Visit the Shrine | Full Documentary","thumbnail":"https://i.ytimg.com/vi/m9h3ekyKwkE/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-mount-emei-golden-summit',
      'ยอดเขาทองคำเอ๋อเหมยซาน (แดนตรัสรู้พระสมันตภัทรโพธิสัตว์แห่งเสฉวน)',
      'Mount Emei Golden Summit (The Radiant Realm of Bodhisattva Samantabhadra)',
      'sacred',
      'เสฉวน',
      'Sichuan',
      'เอ๋อเหมยซาน เล่อซาน',
      'Emeishan, Leshan',
      29.5258,
      103.3367,
      'temple_bell',
      'หนึ่งในสี่ขุนเขาศักดิ์สิทธิ์แห่งพุทธศาสนาในประเทศจีน สูงตระหง่านกว่า 3,099 เมตรในมณฑลเสฉวน เป็นสถานที่ตรัสรู้และสถิตของ ''พระสมันตภัทรโพธิสัตว์'' (ผู้นำแห่งการบำเพ็ญทานและจริยวัตร) บนยอดเขาทองคำ (จินติ่ง) ประดิษฐานรูปปั้นพระโพธิสัตว์สิบพักตร์สัมฤทธิ์ทองคำขนาดมหึมาประทับบนช้างเผือกหกงาสี่เชือกสูง 48 เมตร ปรากฏการณ์อัศจรรย์ประจำยอดเขาคือ ''แสงพุทธรังสี'' (Buddha''s Light) รัศมีวงกลมสีรุ้งที่ลอยอยู่เหนือม่านหมอกสีขาวเบื้องล่าง',
      'Towering 3,099 meters in Sichuan Province, Mount Emei is one of China''s Four Sacred Buddhist Mountains, revered as the bodhimanda of Bodhisattva Samantabhadra (Puxian). Crowning the Golden Summit (Jinding) is a majestic 48-meter multi-faced gilded bronze statue of Samantabhadra seated upon four sacred six-tusked white elephants. Pilgrims gather on the sheer precipice to witness ''Buddha''s Halo'', an extraordinary atmospheric glory phenomenon projecting colorful concentric rings across the cloud sea.',
      'วัดพุทธแห่งแรกในประเทศจีนสร้างขึ้นบนเขานี้ในศตวรรษที่ 1 และเป็นต้นกำเนิดของวิชาหมัดมวยกำลังภายในสายเอ๋อเหมย (ง้อไบ๊) ควบคู่กับเส้าหลินและบู๊ตึ๊ง',
      'Hosting the first Buddhist sanctuary built in China during the Han Dynasty, Emei also developed its own legendary internal martial arts tradition rivaling Shaolin and Wudang.',
      'ห้ามก้มโน้มตัวข้ามรั้วกั้นหน้าผาเพื่อมองดูเงาพุทธรังสี',
      'Never lean over the sheer precipice railing of Sheshen Rock to chase the optical halo.',
      'https://i.ytimg.com/vi/iu-gwRUYX3g/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/iu-gwRUYX3g/hqdefault.jpg","title":"ยอดเขาทองคำเอ๋อเหมยซาน (แดนตรัสรู้พระสมันตภัทรโพธิสัตว์แห่งเสฉวน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=iu-gwRUYX3g","title":"Mount Emei Sacred Journey: 2.5 Hour 4K Golden Buddha & Cloud Sea Views","thumbnail":"https://i.ytimg.com/vi/iu-gwRUYX3g/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-mount-jiuhua-ksitigarbha',
      'เขาจิ่วหัวซาน (แดนมหาปณิธานพระกษิติครรภโพธิสัตว์แห่งอันฮุย)',
      'Mount Jiuhua (The Sacred Mountain of Bodhisattva Ksitigarbha)',
      'sacred',
      'อันฮุย',
      'Anhui',
      'ชิงหยาง ฉือโจว',
      'Qingyang, Chizhou',
      30.4833,
      117.8,
      'temple_bell',
      'หนึ่งในสี่ขุนเขาศักดิ์สิทธิ์ทางพุทธศาสนาของจีน มีแนวเขายอดแหลมเก้ายอดประดุจดอกบัว เป็นแดนสถิตของ ''พระกษิติครรภโพธิสัตว์'' (ตี้จั้งหวังผูซ่า) ผู้มีมหาปณิธาน ''ตราบใดที่นรกยังไม่ว่างเว้นจากคนบาป ข้าพเจ้าจะไม่ขอสำเร็จเป็นพระพุทธเจ้า'' ในศตวรรษที่ 8 เจ้าชายคิม กโยกัก แห่งอาณาจักรชิลลา (เกาหลี) ได้สละราชสมบัติมาบวชจำพรรษาที่นี่จนละสังขาร ร่างของท่านไม่เน่าเปื่อยกลายเป็นมัมมี่ทองคำศักดิ์สิทธิ์ ทำให้เขาจิ่วหัวซานมีชื่อเสียงเรื่องสรีระสังขารอมตะของพระเกจิอาจารย์หลายรูป',
      'Mount Jiuhua (''Nine Lotus Peaks'') in Anhui Province is the sacred sanctuary of Bodhisattva Ksitigarbha (Dizang), the savior of souls in the underworld who vowed not to attain Buddhahood until all hells are empty. In the 8th century, Silla prince Kim Gyo-gak arrived here to practice austere meditation until his passing at age 99. His uncorrupted body mummified naturally, initiating a centuries-long monastic tradition that has produced an astonishing number of incorruptible golden flesh-body saints.',
      'บนยอดเขาประดิษฐานรูปปั้นพระกษิติครรภโพธิสัตว์ทองสัมฤทธิ์สูง 99 เมตร ซึ่งสร้างขึ้นตามอายุ 99 พรรษาของท่านคิม กโยกัก',
      'The colossal 99-meter bronze statue of Ksitigarbha holding his wishing jewel and monk''s staff dominates the valley, commemorating Kim Gyo-gak''s age at enlightenment.',
      'ห้ามลบหลู่หรือชี้นิ้วใส่สรีระสังขารทองคำในวิหารพระเน่าเปื่อย',
      'Never point disrespectfully at the gilded flesh-body relic shrines of the incorruptible masters.',
      'https://i.ytimg.com/vi/dI0uNtp7MDE/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/dI0uNtp7MDE/hqdefault.jpg","title":"เขาจิ่วหัวซาน (แดนมหาปณิธานพระกษิติครรภโพธิสัตว์แห่งอันฮุย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=dI0uNtp7MDE","title":"Mount Jiuhua","thumbnail":"https://i.ytimg.com/vi/dI0uNtp7MDE/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-mount-putuo-guanyin',
      'เกาะผู่ถัวซาน (เกาะสวรรค์พระโพธิสัตว์กวนอิมแห่งทะเลตะวันออก)',
      'Mount Putuo (The Island Sanctuary of Bodhisattva Guanyin)',
      'sacred',
      'เจ้อเจียง',
      'Zhejiang',
      'หมู่เกาะโจวซาน',
      'Putuo District, Zhoushan',
      29.9833,
      122.3833,
      'water_spirit',
      'เกาะศักดิ์สิทธิ์กลางทะเลตะวันออกในมณฑลเจ้อเจียง แดนสถิตของ ''พระอวโลกิเตศวร'' หรือพระโพธิสัตว์กวนอิม เทพีแห่งความเมตตา ตำนานเล่าว่าในปี ค.ศ. 863 พระภิกษุชาวญี่ปุ่นชื่อเอโกกุ ได้อัญเชิญรูปปั้นเจ้าแม่กวนอิมจากเขาอู่ไถเพื่อนำกลับญี่ปุ่น แต่เรือกลับติดพายุและเกิดดอกบัวเหล็กผุดขึ้นขวางลำเรือไว้ พระองค์จึงทรงอธิษฐานว่าหากพระแม่ประสงค์จะประทับอยู่ที่ใดก็ขอให้เรือลอยไปที่นั่น เรือจึงลอยเข้าสู่เกาะผู่ถัวซาน นำไปสู่การสร้างวัด ''กวนอิมไม่ยอมไป'' (Bukenqu Guanyin) ปัจจุบันมีรูปปั้นกวนอิมสัมฤทธิ์ทองคำริมทะเลสูง 33 เมตร',
      'Mount Putuo is a tranquil island sanctuary located in the Zhoushan archipelago, revered as the earthly bodhimanda of Avalokiteshvara, the Goddess of Mercy (Guanyin). In 863 CE, Japanese monk Egaku attempted to transport a sacred Guanyin statue home, but fierce squalls and iron lotus formations immobilized his vessel in the waves until he vowed to enshrine the goddess on the island, founding the ''Unwilling to Leave Guanyin Temple''. Today, a magnificent 33-meter golden statue blesses passing ships.',
      'ถ้ำเฉาหยิน (Chaoyin Cave) ริมโขดหินชายหาดเป็นจุดที่ผู้แสวงบุญในอดีตมักเห็นนิมิตองค์เจ้าแม่กวนอิมปรากฏกายท่ามกลางคลื่นทะเลซัดสาด',
      'The historic Chaoyin tidal cave is famous for centuries of miraculous apparitions where pilgrims reported seeing Guanyin manifest in shimmering sea spray.',
      'ห้ามกระทำการฆ่าสัตว์หรือตกปลาในน่านน้ำรอบเกาะศักดิ์สิทธิ์ผู่ถัวซาน',
      'Fishing and taking of life are strictly forbidden within the protected coastal temple waters.',
      'https://i.ytimg.com/vi/HgF02kzgg_U/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/HgF02kzgg_U/hqdefault.jpg","title":"เกาะผู่ถัวซาน (เกาะสวรรค์พระโพธิสัตว์กวนอิมแห่งทะเลตะวันออก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=HgF02kzgg_U","title":"Mount Putuo （普陀山）: Where Compassion Meets the Sea","thumbnail":"https://i.ytimg.com/vi/HgF02kzgg_U/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-mount-wutai-manjushri',
      'เขาอู่ไถซาน (ห้าเฉลียงสวรรค์พระมัญชุศรีโพธิสัตว์แห่งปัญญา)',
      'Mount Wutai (The Five Terraces of Bodhisattva Manjushri)',
      'sacred',
      'ชานซี',
      'Shanxi',
      'ซินโจว อู่ไถ',
      'Xinzhou, Wutai County',
      39.0067,
      113.5967,
      'temple_bell',
      'ขุนเขาที่สำคัญที่สุดในบรรดาสี่พุทธคีรีของจีน ประกอบด้วยยอดเขาตัดเรียบห้ายอดประดุจเฉลียงห้าแห่ง สูงที่สุดในภาคเหนือของจีน เป็นดินแดนตรัสรู้ของ ''พระมัญชุศรีโพธิสัตว์'' (เหวินซูผูซ่า) พระโพธิสัตว์แห่งปัญญาและความรู้ บนยอดเขามีวัดโบราณตั้งอยู่ถึง 53 แห่ง ผสมผสานทั้งพุทธศาสนานิกายมหายานของชาวฮั่นและทิเบต มีสถูปขาวเจดีย์ทิเบตขนาดมหึมา (Tayuan Pagoda) บรรจุพระบรมสารีริกธาตุ พระมหากษัตริย์จีนทุกราชวงศ์ต่างเสด็จมาจาริกแสวงบุญเพื่อขอพรแห่งสติปัญญา',
      'Mount Wutai in Shanxi Province is the foremost of China''s Four Sacred Buddhist Mountains, comprising five flat-topped alpine peaks symbolizing the five crowns of Bodhisattva Manjushri (Wenshu), the embodiment of supreme transcendent wisdom. Revered since the 1st century, it is unique for uniting both Han Chinese Mahayana and Tibetan Buddhist lineages across 53 historic monasteries, crowned by the towering white Great White Pagoda of Tayuan Temple containing sacred Ashokan relics.',
      'วัดหนานฉาน (Nanchan Temple) และวัดฝอเจียง (Foguang Temple) บนเขานี้เป็นอาคารไม้โบราณสมัยราชวงศ์ถังที่เก่าแก่ที่สุดที่ยังหลงเหลืออยู่ในประเทศจีน',
      'Preserving China''s oldest standing Tang Dynasty timber structures at Nanchan and Foguang temples, Wutai survived multiple dynastic Buddhist persecutions intact.',
      'ห้ามส่งเสียงดังรบกวนการทำสมาธิของพระภิกษุลามะทิเบตบนยอดเขา',
      'Maintain absolute quiet while passing through the active meditation courtyards of Tayuan Temple.',
      'https://i.ytimg.com/vi/KiCF90kIFvI/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/KiCF90kIFvI/hqdefault.jpg","title":"เขาอู่ไถซาน (ห้าเฉลียงสวรรค์พระมัญชุศรีโพธิสัตว์แห่งปัญญา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=KiCF90kIFvI","title":"Mount Wutai (UNESCO/NHK)","thumbnail":"https://i.ytimg.com/vi/KiCF90kIFvI/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-sensoji-asakusa-kannon-tokyo',
      'วัดเซ็นโซจิ (ปาฏิหาริย์เจ้าแม่กวนอิมทองคำแห่งแม่น้ำสุมิดะ)',
      'Senso-ji Temple (The Miraculous Golden Kannon of Asakusa)',
      'sacred',
      'โตเกียว',
      'Tokyo',
      'อาซากุสะ ไทโตะ',
      'Asakusa, Taito',
      35.7147,
      139.7967,
      'temple_bell',
      'วัดพุทธที่เก่าแก่ที่สุดในกรุงโตเกียว ก่อตั้งขึ้นในปี ค.ศ. 628 เมื่อชาวประมงสองพี่น้อง ฮิโนคุมะ ฮามานาริ และทาเคนาริ กำลังทอดแหจับปลาในแม่น้ำสุมิดะ แต่กลับพบรูปปั้นเจ้าแม่กวนอิมทองคำขนาดเล็กติดขึ้นมาในแห ไม่ว่าจะพยายามปล่อยกลับคืนสู่แม่น้ำกี่ครั้ง รูปปั้นก็ยังคงติดแหกลับขึ้นมาเสมอ หัวหน้าหมู่บ้านจึงเปลี่ยนบ้านของตนเป็นวัดเพื่อประดิษฐานรูปปั้นศักดิ์สิทธิ์ หน้าวัดมีโคมแดงยักษ์ ''คามินาริมง'' (Kaminarimon) และกระถางธูปศักดิ์สิทธิ์ที่ผู้คนเชื่อว่าการกวักควันธูปเข้าหาตัวจะช่วยปัดเป่าโรคภัยไข้เจ็บ',
      'Founded in 628 CE, Senso-ji is Tokyo''s oldest and most significant Buddhist temple. Legend recounts that two fisherman brothers, Hinokuma Hamanari and Takenari, netted a tiny golden statue of Kannon (Goddess of Mercy) in the Sumida River. Even after casting it back into the currents, the statue miraculously returned to their nets. Enshrined in the inner sanctuary (as a hidden ''hibutsu'' never seen by the public), visitors pass beneath the iconic Kaminarimon thunder gate to bathe in the healing incense smoke of the giant Jokoro censer.',
      'รูปปั้นเจ้าแม่กวนอิมทองคำองค์จริงถูกเก็บรักษาไว้เป็น ''ฮิบุตสึ'' (พระพุทธรูปลับ) ที่ไม่อนุญาตให้ใครเปิดดูมานานกว่าหนึ่งพันปีเพื่อรักษาความศักดิ์สิทธิ์สูงสุด',
      'The original golden Kannon statue is designated as a secret ''hibutsu'', permanently concealed behind gold-lacquered altar doors and never displayed even to the chief abbot.',
      'ห้ามดับธูปในกระถางธูปยักษ์โจโคโระด้วยน้ำหรือเหยียบย่ำเถ้าธูป',
      'Do not extinguish or tamper with the sacred burning incense within the Jokoro cauldron.',
      'https://i.ytimg.com/vi/zfFTbdpTJUc/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/zfFTbdpTJUc/hqdefault.jpg","title":"วัดเซ็นโซจิ (ปาฏิหาริย์เจ้าแม่กวนอิมทองคำแห่งแม่น้ำสุมิดะ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=zfFTbdpTJUc","title":"Sensoji in Asakusa - The Most Iconic Temple in Tokyo","thumbnail":"https://i.ytimg.com/vi/zfFTbdpTJUc/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-izumo-taisha-shinto-shrine',
      'ศาลเจ้าอิซุโมะไทฉะ (มหาวิหารแห่งการชุมนุมแปดล้านเทพเจ้าชินโต)',
      'Izumo Taisha (The Grand Shrine of the Eight Million Kami Gathering)',
      'sacred',
      'ชิมาเนะ',
      'Shimane',
      'ไทฉะ อิซุโมะ',
      'Taisha-cho, Izumo',
      35.4011,
      132.6856,
      'temple_bell',
      'หนึ่งในศาลเจ้าชินโตที่เก่าแก่และศักดิ์สิทธิ์ที่สุดในญี่ปุ่น อุทิศแด่เทพ ''โอคุนินุชิ โนะ มิโคโตะ'' เทพแห่งความสัมพันธ์ การเกษตร และการรักษาโรค ในเดือน 10 ตามปฏิทินจันทรคติ ขณะที่ทั่วทั้งญี่ปุ่นจะเรียกว่าเดือน ''คันนาซึกิ'' (เดือนที่ไร้เทพเจ้า) แต่ที่อิซุโมะจะเรียกว่า ''คามิอาริซึกิ'' (เดือนที่มีเทพเจ้ามาชุมนุม) เพราะเทพเจ้าชินโตทั้ง 8 ล้านองค์จากทั่วแดนอาทิตย์อุทัยจะเสด็จมารวมตัวกันที่ศาลเจ้าแห่งนี้เพื่อกำหนดชะตากรรมและการจับคู่ชีวิตของมนุษย์ ไฮไลต์คือเชือกศักดิ์สิทธิ์ชิเมะนาวะ (Shimenawa) ขนาดยักษ์หนักกว่า 5.2 ตันที่แขวนอยู่หน้าอาคารคาราฮาฟุ',
      'Izumo Taisha in Shimane Prefecture is one of Japan''s most ancient and revered Shinto sanctuaries, dedicated to Okuninushi no Mikoto, god of marriage, agriculture, and unseen spiritual realms. In the tenth lunar month, while the rest of Japan enters ''Kannazuki'' (the month without gods), Izumo celebrates ''Kamiarizuki''—the arrival of all eight million Shinto kami descending upon Inasa Beach to convene annual divine councils deciding human destinies. The shrine features the world''s largest straw sacred rope (Shimenawa), weighing over 5.2 tons.',
      'การไหว้พระที่อิซุโมะแตกต่างจากศาลเจ้าทั่วไป โดยจะโค้งคำนับ 2 ครั้ง ปรบมือ 4 ครั้ง (แทนที่จะเป็น 2 ครั้ง) และโค้งคำนับอีก 1 ครั้งเพื่อถวายความเคารพต่อเทพเจ้าผู้สร้างโลก',
      'Worshippers at Izumo practice a unique four-clap ritual (two for oneself, two for one''s destined partner) rather than the standard two-clap Shinto protocol.',
      'ห้ามโยนเหรียญใส่เชือกชิเมะนาวะยักษ์เพื่อเสี่ยงทายตามความเชื่องมงายรุ่นใหม่',
      'Do not throw coins into the woven rice straw fibers of the giant Shimenawa rope.',
      'https://i.ytimg.com/vi/3dPtt75VxVs/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/3dPtt75VxVs/hqdefault.jpg","title":"ศาลเจ้าอิซุโมะไทฉะ (มหาวิหารแห่งการชุมนุมแปดล้านเทพเจ้าชินโต)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=3dPtt75VxVs","title":"Izumo Taisha Grand Shrine","thumbnail":"https://i.ytimg.com/vi/3dPtt75VxVs/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-batu-caves-murugan-temple',
      'ถ้ำบาตู (มหาเทวาลัยพระขันธกุมารและบันไดสายรุ้ง 272 ขั้น)',
      'Batu Caves (The Murugan Limestone Sanctuary and Rainbow Stairs)',
      'sacred',
      'สลังงอร์',
      'Selangor',
      'กมบัก กัวลาลัมเปอร์',
      'Gombak, Kuala Lumpur',
      3.2372,
      101.6839,
      'temple_bell',
      'ถ้ำหินปูนศักดิ์สิทธิ์อายุกว่า 400 ล้านปี ตั้งตระหง่านอยู่ทางตอนเหนือของกรุงกัวลาลัมเปอร์ ประเทศมาเลเซีย เป็นศูนย์กลางการแสวงบุญของชาวฮินดูที่ใหญ่ที่สุดนอกประเทศอินเดีย ทางเข้าถ้ำมีรูปปั้นพระขันธกุมาร (Lord Murugan) สีทองอร่ามสูง 42.7 เมตร สูงที่สุดในโลก ผู้แสวงบุญต้องเดินขึ้นบันไดหลากสีสัน 272 ขั้นเพื่อเข้าสู่ ''ถ้ำวิหาร'' (Cathedral Cave) ขนาดมหึมาที่มีเพดานโค้งสูงกว่า 100 เมตร และมีแสงสวรรค์ส่องลงมาจากช่องหินธรรมชาติ ในช่วงเทศกาลไทปูซัม (Thaipusam) ผู้ศรัทธาจะแบก ''กาวาดิ'' และใช้เหล็กแหลมแทงตามร่างกายเพื่อถวายความจงรักภักดี',
      'Rising dramatically above Selangor, Malaysia, Batu Caves is a 400-million-year-old limestone hill holding a sprawling network of sacred Hindu caverns. Guarding the 272 vibrant rainbow steps is the world''s tallest statue of Lord Murugan, standing 42.7 meters high and clad in gold paint imported from Thailand. Inside the cavernous Cathedral Cave, natural light beams pierce the high limestone vault. During the annual Thaipusam festival, over a million devotees participate in trance-induced kavadi body-piercing penances.',
      'ถ้ำแห่งนี้ได้รับการโปรโมตเป็นสถานที่ศักดิ์สิทธิ์ของฮินดูในปี 1890 โดยเค. ทัมบูซามี ปิลไล พ่อค้าชาวทมิฬผู้สังเกตเห็นว่าปากถ้ำมีรูปร่างคล้าย ''เวล'' (Vel) หอกศักดิ์สิทธิ์ของพระมุรุกัน',
      'Discovered as a sacred site in 1890 by Tamil merchant K. Thamboosamy Pillay, who recognized the cave''s natural limestone entrance resembled the divine spear ''Vel'' of Lord Murugan.',
      'ห้ามพกพาอาหารหรือขวดน้ำเปิดโล่งเพราะฝูงลิงศักดิ์สิทธิ์อาจแย่งชิง',
      'Keep food and drinks concealed to prevent aggressive approaches from the resident macaque monkeys.',
      'https://i.ytimg.com/vi/Z8XBFW5tbdE/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/Z8XBFW5tbdE/hqdefault.jpg","title":"ถ้ำบาตู (มหาเทวาลัยพระขันธกุมารและบันไดสายรุ้ง 272 ขั้น)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=Z8XBFW5tbdE","title":"Batu Caves Documentary  (Faith and Nature: A Journey Through Time)","thumbnail":"https://i.ytimg.com/vi/Z8XBFW5tbdE/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-somnath-temple-jyotirlinga-gujarat',
      'วิหารโสมนาถ (ชโยติรลึงค์ปฐมบทแห่งพระศิวะผู้เป็นอมตะ)',
      'Somnath Temple (The Eternal First Jyotirlinga of Lord Shiva)',
      'sacred',
      'คุชราต',
      'Gujarat',
      'ประภาสปาตัน คีร์โสมนาถ',
      'Prabhas Patan, Gir Somnath',
      20.888,
      70.4012,
      'temple_bell',
      'วิหารศักดิ์สิทธิ์แห่งแรกในบรรดา 12 ชโยติรลึงค์ (เสาไฟสว่างไสวแห่งพระศิวะ) ริมชายฝั่งทะเลอาหรับในรัฐคุชราต ประเทศอินเดีย ตำนานในคัมภีร์สกันทปุราณะระบุว่า พระจันทร์ (โสมเทพ) ถูกคำสาปของประชาบดีทักษะให้สูญเสียแสงสว่าง จึงมาสร้างวิหารทองคำบูชาพระศิวะที่นี่จนหายจากคำสาป วิหารแห่งนี้เป็นสัญลักษณ์แห่งความไม่ยอมแพ้ โดยถูกกองทัพผู้รุกรานทำลายและปล้นสะดมทองคำถึง 17 ครั้งตลอดประวัติศาสตร์ แต่ก็ได้รับการสร้างขึ้นใหม่ทุกครั้งจนได้รับการขนานนามว่า ''วิหารแห่งการฟื้นคืนชีพนิรันดร์''',
      'Located on the Arabian Sea coast of Gujarat, Somnath Temple enshrines the first of the twelve sacred Jyotirlingas of Lord Shiva. According to ancient Puranas, the Moon God Chandra built the original temple of pure gold to break a curse of waning consumption cast upon him by King Daksha. Renowned as the ''Shrine Eternal'', Somnath was brutally invaded, ransacked, and demolished seventeen times by foreign armies, yet was reconstructed anew each time, standing today as a monument to indomitable Hindu faith.',
      'ที่ลานวิหารมีเสา ''พาณสตัมภ์'' (Baan Stambh) เสาลูกศรโบราณที่ชี้ตรงลงสู่ทิศใต้ ซึ่งเป็นแนวเส้นตรงทางทะเลที่ไม่มีแผ่นดินใดๆ ขวางกั้นจนถึงทวีปแอนตาร์กติกา',
      'The seaside complex features the Baan Stambh (Arrow Pillar), an ancient astronomical marker indicating an uninterrupted direct maritime line from Somnath south to Antarctica.',
      'ห้ามนำโทรศัพท์มือถือ กล้อง หรือกระเป๋าหนังเข้าไปในเขตพระวิหารโสมนาถ',
      'Mobile phones, recording devices, and leather articles are strictly prohibited inside the inner sanctum.',
      'https://i.ytimg.com/vi/pBfbUTvdUQw/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/pBfbUTvdUQw/hqdefault.jpg","title":"วิหารโสมนาถ (ชโยติรลึงค์ปฐมบทแห่งพระศิวะผู้เป็นอมตะ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=pBfbUTvdUQw","title":"1000 Years of The Somnath Mandir (The History You Will Love!) | Pratik Nayak","thumbnail":"https://i.ytimg.com/vi/pBfbUTvdUQw/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-kashi-vishwanath-varanasi-shiva',
      'วิหารกาสีวิศวนาถ (ยอดทองคำแห่งวาราณสีและสะพานสู่โมกษะ)',
      'Kashi Vishwanath Temple (The Golden Spire of Shiva and Liberation at Varanasi)',
      'sacred',
      'อุตตรประเทศ',
      'Uttar Pradesh',
      'วาราณสี กาสี',
      'Varanasi, Kashi',
      25.3108,
      83.0107,
      'temple_bell',
      'ศูนย์กลางจิตวิญญาณของศาสนาฮินดูริมแม่น้ำคงคา เมืองพาราณสี (กาสี) เมืองที่มีผู้คนอยู่อาศัยต่อเนื่องยาวนานที่สุดในโลก วิหารแห่งนี้ประดิษฐาน ''วิศเวศวร'' (ผู้เป็นเจ้าแห่งสากลจักรวาล) หนึ่งใน 12 ชโยติรลึงค์ ยอดโดมของวิหารหุ้มด้วยทองคำบริสุทธิ์หนักกว่าหนึ่งตันที่ถวายโดยมหาราชา รันจิต ซิงห์ ชาวฮินดูเชื่อว่าผู้ใดที่ได้มาสักการะและอาบน้ำชำระล้างบาปในแม่น้ำคงคา ณ เมืองกาสี หรือเสียชีวิตในเมืองศักดิ์สิทธิ์นี้ จะได้รับการปลดปล่อยจากวัฏสงสาร (โมกษะ) ทันทีโดยไม่ต้องเวียนว่ายตายเกิดอีก',
      'Standing beside the holy Ganges River in Varanasi, Kashi Vishwanath Temple is Hinduism''s spiritual beating heart. Dedicated to Lord Shiva as Vishwanatha (''Ruler of the Universe''), it enshrines one of the primary Jyotirlingas. Its iconic spires are plated in over a ton of pure gold donated by Maharaja Ranjit Singh in 1835. Millions believe that taking holy darshan here and cremating departed loved ones along the Manikarnika ghats grants immediate Moksha—liberation from the eternal cycle of rebirth.',
      'บ่อน้ำชญาณวาปี (Gyanvapi Well) ภายในเขตวิหาร เชื่อว่าเป็นจุดที่หัวหน้านักบวชกระโดดลงไปซ่อนชโยติรลึงค์ดั้งเดิมไว้เพื่อปกป้องจากการทำลายล้างของจักรพรรดิออรังเซบ',
      'The historic Gyanvapi ''Well of Wisdom'' inside the corridor holds the legendary history where priests hid the sacred lingam during Mughal Emperor Aurangzeb''s siege.',
      'ห้ามสวมรองเท้าและห้ามนำอุปกรณ์อิเล็กทรอนิกส์เข้าสู่เขตทางเดินกาสีวิศวนาถคอริดอร์',
      'Footwear and electronics are strictly barred beyond the high-security security checkpoint.',
      'https://i.ytimg.com/vi/9RSHrwc3v9w/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/9RSHrwc3v9w/hqdefault.jpg","title":"วิหารกาสีวิศวนาถ (ยอดทองคำแห่งวาราณสีและสะพานสู่โมกษะ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=9RSHrwc3v9w","title":"Kashi Vishwanath | A documentary film by SHIV SHAKTI","thumbnail":"https://i.ytimg.com/vi/9RSHrwc3v9w/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-kedarnath-temple-himalayan-shrine',
      'วิหารเกดาร์นาถ (มหาวิหารหินกลางพายุหิมะเทือกเขาหิมาลัย)',
      'Kedarnath Temple (The High Himalayan Shrine of the Pandavas)',
      'sacred',
      'อุตตราขัณฑ์',
      'Uttarakhand',
      'เกดาร์นาถ รุทรปรยัค',
      'Kedarnath, Rudraprayag',
      30.7352,
      79.0669,
      'creepy_wind',
      'หนึ่งในวิหารศักดิ์สิทธิ์สูงสุดของอินเดีย ตั้งอยู่บนความสูง 3,583 เมตรท่ามกลางหุบเขาธารน้ำแข็งหิมาลัย ใกล้ต้นกำเนิดแม่น้ำมันดากินี ตำนานมหาภารตะเล่าว่าพี่น้องปาณฑพทั้งห้าได้เดินทางขึ้นหิมาลัยเพื่อขอขมาต่อพระศิวะจากการสังหารญาติมิตรในสงครามทุ่งกุรุเกษตร พระศิวะได้แปลงร่างเป็นวัวกระทิงกระทืบดินมุดหนี แต่ภีมะคว้าหลังของวัวไว้ได้ หลังค่อมของวัวจึงกลายสภาพเป็นก้อนหินรูปทรงสามเหลี่ยมศักดิ์สิทธิ์ภายในวิหารแห่งนี้ ในมหาอุทกภัยปี 2013 โคลนถล่มกวาดล้างเมืองจนราบคาบ แต่มีหินก้อนมหึมา ''ภีมศิลา'' กลิ้งมาหยุดขวางน้ำไว้ ทำให้ตัววิหารโบราณรอดพ้นมาได้อย่างปาฏิหาริย์',
      'Situated at an altitude of 3,583 meters against the majestic snow-capped peaks of the Garhwal Himalayas, Kedarnath is the highest of the twelve Jyotirlingas. Rooted in the Mahabharata epic, the Pandava brothers journeyed to these frozen heights seeking Lord Shiva''s absolution after the Kurukshetra war; Shiva took the form of a bull, leaving his triangular hump enshrined as the sanctum''s holy rock. In the catastrophic 2013 Himalayan flash floods, a massive boulder dubbed ''Bheem Shila'' miraculously diverted debris flows around the stone temple, leaving it unharmed.',
      'วิหารหินแกรนิตสีเทานี้สร้างขึ้นโดยอาทิศังการาจารย์ในศตวรรษที่ 8 และต้องปิดตัวลงนาน 6 เดือนในฤดูหนาวเนื่องจากหิมะท่วมมิดหลังคา',
      'Restored by Adi Shankara, who achieved mahasamadhi behind the shrine, Kedarnath remains snowbound and closed to pilgrims for six months each winter.',
      'ห้ามปีนขึ้นไปเหยียบก้อนหินศักดิ์สิทธิ์ภีมศิลาหลังวิหาร',
      'Do not climb atop the miraculous protective boulder ''Bheem Shila'' behind the sanctuary.',
      'https://i.ytimg.com/vi/oGlzn2xCPmw/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/oGlzn2xCPmw/hqdefault.jpg","title":"วิหารเกดาร์นาถ (มหาวิหารหินกลางพายุหิมะเทือกเขาหิมาลัย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=oGlzn2xCPmw","title":"Kedarnath Jyotirlinga Full Documentary | History,  Miracle & Panch Kedar Explained","thumbnail":"https://i.ytimg.com/vi/oGlzn2xCPmw/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-ranakpur-jain-temple-pillars',
      'วิหารรานัคปูร์ (อัศจรรย์ 1,444 เสาหินอ่อนสลักไร้คู่เหมือนแห่งเชน)',
      'Ranakpur Jain Temple (The 1,444 Unique Marble Pillars of Adinatha)',
      'sacred',
      'ราชสถาน',
      'Rajasthan',
      'รานัคปูร์ ปาลี',
      'Ranakpur, Pali District',
      25.1158,
      73.4736,
      'temple_bell',
      'หนึ่งในวิหารเชนที่วิจิตรงดงามที่สุดในโลก สร้างขึ้นในศตวรรษที่ 15 ท่ามกลางหุบเขาอาราวาลี รัฐราชสถาน เพื่ออุทิศแด่พระอาทินาถ ตีรถังกรองค์แรก วิหารสร้างขึ้นจากหินอ่อนสีขาวนวลทั้งหลัง จุดเด่นอันน่าอัศจรรย์คือเสาหินอ่อนค้ำยันวิหารจำนวน 1,444 ต้น ซึ่งได้รับการแกะสลักลวดลายอย่างประณีตวิจิตรบรรจง และไม่มีเสาต้นใดเลยที่มีลวดลายซ้ำกันแม้แต่ต้นเดียว นอกจากนี้เสาทุกต้นถูกจัดวางในมุมมองที่ไม่บดบังทัศนียภาพขององค์พระประธานไม่ว่าจะยืนมองจากจุดใดในห้องโถง',
      'Nestled in a remote valley of Rajasthan''s Aravalli Range, the 15th-century Ranakpur Jain Temple is an architectural masterpiece of light marble dedicated to Tirthankara Adinatha. Supported by an astounding 1,444 intricately carved marble pillars, astonishingly no two columns share the same carved design. Furthermore, the visionary architects engineered the forest of columns so that none obstruct a direct sightline to the central four-faced idol of the deity from any hall.',
      'สร้างขึ้นโดยพ่อค้าผู้เคร่งครัด ธรณา ชาห์ (Dharna Shah) หลังจากที่เขาเห็นนิมิตสวรรค์ของยานพาหนะลอยฟ้าในภวังค์จิต',
      'Conceived by wealthy Jain merchant Dharna Shah following a celestial vision, King Rana Kumbha provided royal land and sanctuary for its 50-year construction.',
      'ห้ามนำสิ่งของที่ทำจากหนังสัตว์หรือเนื้อสัตว์ทุกชนิดเข้าสู่วิหารตามหลักอหิงสา',
      'Strictly ban all leather items, belts, and non-vegetarian food to honor Jain vows of Ahimsa.',
      'https://i.ytimg.com/vi/o8Gx2B-O06Y/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/o8Gx2B-O06Y/hqdefault.jpg","title":"วิหารรานัคปูร์ (อัศจรรย์ 1,444 เสาหินอ่อนสลักไร้คู่เหมือนแห่งเชน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=o8Gx2B-O06Y","title":"Rajasthan''s best kept secret: Chaturmukh Temple","thumbnail":"https://i.ytimg.com/vi/o8Gx2B-O06Y/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-montserrat-black-madonna-catalonia',
      'อารามมอนต์เซอร์รัต (พระแม่มารีผิวดำแห่งยอดเขารอยหยักคาตาโลเนีย)',
      'Santa Maria de Montserrat (The Holy Black Virgin of Catalonia)',
      'sacred',
      'คาตาโลเนีย',
      'Catalonia',
      'เทือกเขามอนต์เซอร์รัต บาร์เซโลนา',
      'Montserrat, Barcelona',
      41.5933,
      1.8378,
      'temple_bell',
      'อารามเบเนดิกตินโบราณที่เกาะตัวอยู่บนหน้าผาหินรูปร่างประหลาดคล้ายฟันเลื่อยสูง 720 เมตรในแคว้นคาตาโลเนีย ประเทศสเปน ภายในประดิษฐาน ''ลา โมเรเนตา'' (La Moreneta) หรือพระแม่มารีผิวดำ แกะสลักจากไม้เนื้อแข็งสีเข้มในศตวรรษที่ 12 พระหัตถ์ถือลูกโลกสากล ตำนานเล่าว่าเด็กเลี้ยงแกะเห็นแสงสว่างเจิดจ้าและได้ยินเสียงเพลงสวรรค์ดังมาจากถ้ำซานตากอวา เมื่อบิชอปพยายามเคลื่อนย้ายรูปปั้นลงจากเขา รูปปั้นกลับมีน้ำหนักมหาศาลจนไม่มีใครยกขึ้น จึงต้องสร้างอารามขึ้น ณ ยอดเขาแห่งนี้',
      'Perched dramatically among the jagged, serrated conglomerate pillars of Catalonia, Santa Maria de Montserrat Abbey has been a holy sanctuary since the 9th century. Enshrined in the basilica is ''La Moreneta'' (''The Little Dark One''), a Romanesque 12th-century dark wood carving of the Virgin Mary holding the orb of creation. According to lore, shepherd children discovered the statue in a cave guided by celestial singing; when priests attempted to carry it down to the valley, the idol grew impossibly heavy, commanding its shrine remain on the mountain.',
      'คณะนักร้องประสานเสียงเด็กชาย ''เอสโคลาเนีย'' (Escolania de Montserrat) เป็นหนึ่งในคณะนักร้องประสานเสียงทางศาสนาที่เก่าแก่ที่สุดในยุโรปตั้งแต่ศตวรรษที่ 14',
      'The abbey hosts the Escolania de Montserrat, one of Europe''s oldest boys'' choirs recorded performing sacred polyphonic choral hymns since 1307.',
      'ห้ามสัมผัสส่วนอื่นของรูปปั้นพระแม่มารีนอกเหนือจากลูกแก้วกลมในพระหัตถ์ขวา',
      'Pilgrims touch only the exposed wooden orb held in the Black Madonna''s right hand.',
      'https://i.ytimg.com/vi/G4MkIMLehhQ/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/G4MkIMLehhQ/hqdefault.jpg","title":"อารามมอนต์เซอร์รัต (พระแม่มารีผิวดำแห่งยอดเขารอยหยักคาตาโลเนีย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=G4MkIMLehhQ","title":"THE STORY OF THE MIRACULOUS BLACK MADONNA OF MONSERRAT, CATALONIA, SPAIN / DISABILITY TRAVEL VLOG","thumbnail":"https://i.ytimg.com/vi/G4MkIMLehhQ/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-badrinath-temple-char-dham',
      'วิหารพัทรีนาถ (วิหารทองคำพระนารายณ์แห่งยอดเขานีลคัณฐ์)',
      'Badrinath Temple (The Sacred Abode of Lord Vishnu in the Himalayas)',
      'sacred',
      'อุตตราขัณฑ์',
      'Uttarakhand',
      'พัทรีนาถ ชาโมลี',
      'Badrinath, Chamoli',
      30.7447,
      79.4911,
      'temple_bell',
      'หนึ่งในสี่มหาปูชนียสถาน ''ชาร์ธาม'' (Char Dham) ที่สำคัญที่สุดของศาสนาฮินดู ตั้งอยู่สูง 3,133 เมตรริมฝั่งแม่น้ำอลักนันทา เบื้องหลังคือยอดเขานีลคัณฐ์ที่ปกคลุมด้วยหิมะขาวโพลน ภายในประดิษฐานเทวรูปพระวิษณุ (พัทรีนารายณ์) หินศิลาดำศาลิครามขนาด 1 เมตร ในท่านั่งสมาธิ ตำนานเล่าว่าพระนารายณ์ทรงบำเพ็ญตบะท่ามกลางความหนาวเหน็บ พระแม่ลักษมีจึงแปลงกายเป็นต้นเบอร์รี่ป่า (พัทรี) แผ่กิ่งก้านกำบังหิมะและลมหนาวให้พระสวามี หน้าวิหารมีบ่อน้ำพุร้อนกำมะถันธรรมชาติ ''ตัปตากุนด์'' ที่ผู้แสวงบุญจะลงอาบน้ำชำระกายก่อนเข้ากราบไหว้',
      'Badrinath Temple, set beside the roaring Alaknanda River at 3,133 meters in the Garhwal Himalayas, is the preeminent pilgrimage shrine of the sacred Char Dham circuit. Enshrining a 1-meter black Shaligram stone idol of Lord Vishnu (Badrinarayan) meditating in padmasana, mythology recounts that Vishnu performed severe penance here while goddess Lakshmi sheltered him from freezing blizzards by taking the form of a Badri (jujube berry) tree. Pilgrims purify themselves in the steaming natural sulfur hot springs of Tapt Kund before worship.',
      'องค์พระพุทธปฏิมาถูกค้นพบในแม่น้ำอลักนันทาโดยอาทิศังการาจารย์ในศตวรรษที่ 9 และทำพิธีประดิษฐานไว้ในถ้ำก่อนสร้างวิหาร',
      'Adi Shankara retrieved the discarded Shaligram deity from the icy Narad Kund pool, establishing South Indian Nambudiri Brahmins as the temple''s perpetual head priests (Rawal).',
      'ห้ามลงอาบน้ำในบ่อน้ำพุร้อนตัปตากุนด์โดยไม่ล้างเท้าก่อน',
      'Never enter the holy sulfur bathing tank of Tapt Kund with footwear nearby.',
      'https://i.ytimg.com/vi/0QD4uMmsVgo/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/0QD4uMmsVgo/hqdefault.jpg","title":"วิหารพัทรีนาถ (วิหารทองคำพระนารายณ์แห่งยอดเขานีลคัณฐ์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0QD4uMmsVgo","title":"Char Dham Yatra I Documentary I  2025 I Yamunotri,  Gangotri, Kedarnath, Badrinath,I 4K","thumbnail":"https://i.ytimg.com/vi/0QD4uMmsVgo/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-st-peter-basilica-vatican',
      'มหาวิหารนักบุญเปโตร (ศูนย์กลางแห่งคริสตจักรคาทอลิกและสุสานอัครทูต)',
      'St. Peter''s Basilica (The Papal Enclave and Tomb of the Apostle)',
      'sacred',
      'นครรัฐวาติกัน',
      'Vatican City',
      'จัตุรัสนักบุญเปโตร',
      'Piazza San Pietro',
      41.9022,
      12.4539,
      'temple_bell',
      'โบสถ์คริสต์ที่ใหญ่ที่สุดในโลกและศูนย์กลางแห่งพระศาสนจักรโรมันคาทอลิก สร้างขึ้นเหนือสุสานของนักบุญเปโตร หนึ่งในอัครสาวกสิบสององค์และบิชอปองค์แรกแห่งโรม ผู้ถูกตรึงกางเขนกลับหัวในยุคจักรพรรดิเนโร โดมยักษ์อันสง่างามได้รับการออกแบบโดยมีเกลันเจโล ภายในประดิษฐานซุ้มพลับพลาสัมฤทธิ์ ''บัลดาคคิโน'' ของแบร์นินี เหนือแท่นบูชาเอก และรูปสลักหินอ่อน ''ปีเอตา'' (Pieta) วิหารแห่งนี้เป็นศูนย์รวมศรัทธาของชาวคาทอลิกกว่า 1.3 พันล้านคนทั่วโลก',
      'St. Peter''s Basilica in Vatican City is the preeminent shrine of Roman Catholicism and the greatest architectural monument of the Renaissance. Consecrated in 1626 atop the 4th-century basilica founded by Emperor Constantine over the tomb of Saint Peter (crucified upside-down in the Circus of Nero), the basilica features Michelangelo''s soaring dome, Bernini''s bronze Baldacchino towering over the papal altar, and the timeless marble Pieta. It stands as the spiritual center for over a billion believers.',
      'การขุดค้นทางโบราณคดีใต้แท่นบูชาในทศวรรษ 1940 ได้ค้นพบ ''สุสานเปโตร'' (Scavi) พร้อมกระดูกมนุษย์ศตวรรษที่ 1 ที่มีรอยจารึกว่า ''เปโตรอยู่ที่นี่''',
      'The Vatican Necropolis (Scavi) excavations beneath the high altar confirmed the existence of Peter''s 1st-century graffiti-inscribed ''Red Wall'' burial monument.',
      'ห้ามแต่งกายเปิดไหล่หรือกระโปรงสั้นเหนือเข่าเข้าสู่มหาวิหารนักบุญเปโตร',
      'Strict modesty rules require shoulders and knees to be covered to gain entry to the basilica.',
      'https://i.ytimg.com/vi/CixwkOSwo0g/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/CixwkOSwo0g/hqdefault.jpg","title":"มหาวิหารนักบุญเปโตร (ศูนย์กลางแห่งคริสตจักรคาทอลิกและสุสานอัครทูต)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=CixwkOSwo0g","title":"The First Pope: The Story Of Saint Peter And His Holy Relics","thumbnail":"https://i.ytimg.com/vi/CixwkOSwo0g/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-san-damiano-church-assisi',
      'โบสถ์ซานดามิอาโน (กางเขนพูดได้และถิ่นกำเนิดนักบุญฟรังซิสแห่งอัสซีซี)',
      'San Damiano Church (The Speaking Crucifix of Saint Francis of Assisi)',
      'sacred',
      'อุมเบรีย',
      'Umbria',
      'อัสซีซี เปรูจา',
      'Assisi, Perugia',
      43.0617,
      12.6178,
      'temple_bell',
      'โบสถ์หินชนบทโบราณท่ามกลางดงมะกอกนอกเมืองอัสซีซี ประเทศอิตาลี จุดเริ่มต้นของการปฏิรูปทางจิตวิญญาณของนักบุญฟรังซิสแห่งอัสซีซี ในปี 1205 ขณะที่ท่านกำลังคุกเข่าสวดมนต์หน้ากางเขนโบราณในโบสถ์ที่ทรุดโทรม ท่านได้ยินเสียงพระเยซูตรัสออกมาจากไม้กางเขนว่า ''ฟรังซิส จงไปซ่อมแซมบ้านของข้า ซึ่งเจ้าเห็นว่ากำลังจะพังทลายลง'' ท่านจึงสละทรัพย์สมบัติของตระกูล นุ่งห่มผ้าหยาบ และก่อตั้งคณะภราดาน้อย (ฟรานซิสกัน) ขึ้นที่นี่ นอกจากนี้ยังเป็นที่พำนักของนักบุญคลาแรจนวาระสุดท้าย',
      'San Damiano is a humble, stone sanctuary nestled among ancient olive groves outside Assisi, Italy. In 1205, while praying before a Byzantine crucifix in the crumbling church, young Francis heard the painted Christ speak to him aloud: ''Francis, go and repair my house, which as you see is falling into ruin.'' Renouncing his inheritance to live in absolute poverty, Francis rebuilt the walls with his own hands, sparking a global mendicant movement. It also served as the cloister for Saint Clare and the Poor Clares.',
      'นักบุญฟรังซิสได้ประพันธ์ ''บทเพลงสรรเสริญสรรพสิ่ง'' (Canticle of the Sun) วรรณกรรมภาษาอิตาลีโบราณชิ้นแรกๆ ในสวนของโบสถ์แห่งนี้',
      'In the quiet cloister garden of San Damiano, Saint Francis composed his celebrated ''Canticle of the Sun'', praising Brother Sun and Sister Moon.',
      'ห้ามส่งเสียงดังในเขตระเบียงคดและห้องพำนักเดิมของนักบุญคลาแร',
      'Maintain silent prayer while walking through Saint Clare''s historic dormitory and courtyard.',
      'https://i.ytimg.com/vi/pVodFcL0x6g/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/pVodFcL0x6g/hqdefault.jpg","title":"โบสถ์ซานดามิอาโน (กางเขนพูดได้และถิ่นกำเนิดนักบุญฟรังซิสแห่งอัสซีซี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=pVodFcL0x6g","title":"The San Damiano Cross: story and meaning","thumbnail":"https://i.ytimg.com/vi/pVodFcL0x6g/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-blue-mosque-mazar-i-sharif',
      'มัสยิดสีน้ำเงินแห่งมะซารีชะรีฟ (สุสานแห่งแสงและกระเบื้องโมเสกสีคราม)',
      'The Blue Mosque of Mazar-i-Sharif (The Turquoise Shrine of Hazrat Ali)',
      'sacred',
      'บัลข์',
      'Balkh',
      'มะซารีชะรีฟ',
      'Mazar-i-Sharif',
      36.7081,
      67.1108,
      'temple_bell',
      'มัสยิดที่งดงามที่สุดในเอเชียกลาง ประดับด้วยกระเบื้องโมเสกเคลือบสีฟ้าครามและเทอร์ควอยซ์นับล้านแผ่นในเมืองมะซารีชะรีฟ ประเทศอัฟกานิสถาน ชาวมุสลิมในเอเชียกลางเชื่อว่าที่นี่เป็นสถานที่ฝังพระศพที่แท้จริงของ ''ฮัซรัต อาลี'' (บุตรเขยและลูกพี่ลูกน้องของศาสดามุฮัมมัด) ร่างของท่านถูกนำมาโดยอูฐสีขาวและฝังไว้ ณ ที่แห่งนี้ ตำนานเล่าว่านกพิราบสีเทาทุกตัวที่บินเข้ามาอาศัยในลานมัสยิดสีน้ำเงินแห่งนี้จะกลายสภาพเป็นนกพิราบสีขาวบริสุทธิ์ภายใน 40 วัน ด้วยความบริสุทธิ์แห่งความศักดิ์สิทธิ์',
      'The Shrine of Hazrat Ali, famously known as the Blue Mosque, is an architectural jewel in Mazar-i-Sharif, Afghanistan. Enveloped in intricate Persian turquoise, lapis, and cobalt ceramic tiles, regional tradition maintains that the remains of Ali ibn Abi Talib, fourth caliph and son-in-law of Prophet Muhammad, were secretly transported by a white camel and interred here. Local folklore holds that any grey pigeon nesting within the mosque''s sacred courtyards turns snow-white within forty days due to the holiness of the ground.',
      'มัสยิดเดิมถูกทำลายโดยเจงกิสข่านในปี 1220 ก่อนจะถูกสร้างขึ้นใหม่ในศตวรรษที่ 15 โดยสุลต่านฮุสเซน ไบการา แห่งราชวงศ์ตีมูร์',
      'Buried to protect it from Genghis Khan in 1220 and rediscovered via a celestial dream, Sultan Husayn Bayqarah erected the current Timurid masterpiece in the 15th century.',
      'ห้ามทำร้ายหรือไล่นกพิราบสีขาวที่อาศัยอยู่ในลานมัสยิดสีน้ำเงิน',
      'Never harm or chase the sacred white pigeons residing in the mosque''s tiled plazas.',
      'https://i.ytimg.com/vi/8YWfvyWFTDU/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/8YWfvyWFTDU/hqdefault.jpg","title":"มัสยิดสีน้ำเงินแห่งมะซารีชะรีฟ (สุสานแห่งแสงและกระเบื้องโมเสกสีคราม)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=8YWfvyWFTDU","title":"🇦🇫 I Explored Afghanistan’s Blue Mosque | Mazar-e-Sharif City & Local Life","thumbnail":"https://i.ytimg.com/vi/8YWfvyWFTDU/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-jagannath-temple-puri-odisha',
      'วิหารจากันนาถแห่งปุรี (เทวาลัยแห่งเจ้านายสากลโลกและเทศกาลราชยาตรา)',
      'Jagannath Temple of Puri (The Lord of the Universe and the Chariot Ratha Yatra)',
      'sacred',
      'โอริสสา',
      'Odisha',
      'เมืองปุรี ริมอ่าวเบงกอล',
      'Puri, Bay of Bengal',
      19.8047,
      85.8178,
      'temple_bell',
      'หนึ่งในสี่มหาปูชนียสถาน ชาร์ธาม ริมอ่าวเบงกอลในรัฐโอริสสา ประเทศอินเดีย สร้างขึ้นในศตวรรษที่ 12 อุทิศแด่พระจากันนาถ (อวตารของพระกฤษณะ) พร้อมพระเชษฐาพลราม และพระขนิษฐาสุภัทรา เทวรูปแกะสลักจากท่อนไม้ศักดิ์สิทธิ์นีม มีดวงตากลมโตเป็นเอกลักษณ์ ความอัศจรรย์ของวิหารนี้คือ ธงบนยอดวิหารจะโบกสะบัดทวนทิศทางลมเสมอ ไม่มีนกหรือเครื่องบินบินผ่านเหนือยอดวิหาร และเสียงคลื่นทะเลจะเงียบสนิทลงทันทีเมื่อก้าวเท้าผ่านประตูด้านใน นอกจากนี้ยังเป็นต้นกำเนิดของเทศกาล ''ราชยาตรา'' (Ratha Yatra) ลากราชรถยักษ์ที่ยิ่งใหญ่ที่สุดในโลก',
      'The Jagannath Temple in Puri, Odisha, is a colossal 12th-century Kalinga-style fortress shrine dedicated to Lord Jagannath (''Lord of the Universe''), Balabhadra, and Subhadra. Enshrining distinct neem-wood idols with large circular eyes, the temple is surrounded by inexplicable mysteries: the summit flag always flutters against the wind direction, birds never fly over the high spire, and the roar of the ocean waves vanishes the instant one crosses Simhadwara gate. It is world-renowned for the monumental Ratha Yatra chariot festival.',
      'โรงครัวของวิหารจากันนาถ (Rosha Ghara) เป็นโรงครัวดั้งเดิมที่ใหญ่ที่สุดในโลก ปรุงอาหารบริสุทธิ์ (มหาปรสาท) เลี้ยงดูผู้คนนับแสนคนทุกวันโดยใช้หมอดินเผาซ้อนกัน 7 ชั้นบนกองไฟเดียว',
      'Operating the world''s largest traditional kitchen, 500 cooks prepare Mahaprasad offerings using earthen pots stacked vertically seven-high over wood fires, where the uppermost pot cooks first.',
      'ห้ามบุคคลที่ไม่ใช่ศาสนิกชนฮินดูเข้าไปภายในเขตพระวิหารชั้นในตามกฎโบราณนับพันปี',
      'Strict centuries-old temple laws restrict entry to the inner sanctum to practicing Hindus only.',
      'https://i.ytimg.com/vi/OvwHUiBM81w/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/OvwHUiBM81w/hqdefault.jpg","title":"วิหารจากันนาถแห่งปุรี (เทวาลัยแห่งเจ้านายสากลโลกและเทศกาลราชยาตรา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=OvwHUiBM81w","title":"Ratha-Yatra aka Chariot Festival: Jagannath (1961) | British Pathé","thumbnail":"https://i.ytimg.com/vi/OvwHUiBM81w/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-gobekli-tepe-ancient-temple',
      'เกอเบกลี เทเป (วิหารหินสลักหมื่นสองพันปีแห่งซานลึอูร์ฟา)',
      'Gobekli Tepe (The 12,000-Year-Old Megalithic Sanctuary of Sanliurfa)',
      'legend',
      'ซานลึอูร์ฟา',
      'Sanliurfa',
      'ฮาลีลีเย',
      'Haliliye',
      37.2231,
      38.9225,
      'jungle_curse',
      'มหาศาสนสถานยุคก่อนประวัติศาสตร์ที่เก่าแก่ที่สุดในโลก สร้างขึ้นเมื่อราว 9,600 ปีก่อนคริสตกาล (กว่า 11,600 ปีก่อน) ก่อนกำเนิดเกษตรกรรม การทำเครื่องปั้นดินเผา และการเขียนหลายพันปี ประกอบด้วยเสาหินปูนรูปตัว T ขนาดยักษ์สูงถึง 5.5 เมตร หนักหลายสิบตัน เรียงตัวเป็นวงกลม เสาหินสลักลวดลายสัตว์ดุร้ายนูนต่ำ ทั้งสิงโต เสือดาว หมาป่า นกแร้ง และแมงป่อง สิ่งก่อสร้างนี้พลิกความเข้าใจประวัติศาสตร์มนุษยชาติ โดยพิสูจน์ว่าศาสนาและความเชื่อทางจิตวิญญาณเป็นตัวผลักดันให้มนุษย์รวมตัวกันสร้างอารยธรรม ก่อนที่จะรู้จักทำการเกษตรเสียอีก',
      'Gobekli Tepe in southeastern Turkey is the world''s oldest known megalithic temple complex, dating back to circa 9600 BCE—predating Stonehenge by over 6,000 years and constructed before the dawn of agriculture or metallurgy. Hunter-gatherers quarried and erected colossal T-shaped limestone pillars weighing up to 20 tons, carved with intricate high-relief depictions of predatory beasts, vultures, and anthropomorphic arms. Its discovery revolutionized archaeology, proving religious gathering preceded settled urban civilization.',
      'ค้นพบโดยนักโบราณคดีชาวเยอรมัน คลาอุส ชมิดท์ (Klaus Schmidt) ในปี 1994 โดยพบว่าวิหารหินทั้งหมดถูกฝังกลบดินอย่างจงใจด้วยมือมนุษย์โบราณในยุคสิ้นสุดการใช้งาน',
      'Excavated under Klaus Schmidt, evidence demonstrates the monumental enclosures were deliberately backfilled and buried beneath mounds of soil by ancient builders for unknown ritualistic purposes.',
      'ห้ามปีนป่ายหรือสัมผัสภาพแกะสลักสัตว์โบราณบนเสาหินรูปตัว T',
      'Never climb or touch the 11,000-year-old animal relief carvings on the T-pillars.',
      'https://i.ytimg.com/vi/n-phVB-EmR8/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/n-phVB-EmR8/hqdefault.jpg","title":"เกอเบกลี เทเป (วิหารหินสลักหมื่นสองพันปีแห่งซานลึอูร์ฟา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=n-phVB-EmR8","title":"The OLDEST temple in the world 🤯 - BBC","thumbnail":"https://i.ytimg.com/vi/n-phVB-EmR8/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-serpent-mound-adams-county-ohio',
      'เกรตเซอร์เพนต์เมานด์ (เนินดินงูยักษ์ดึกดำบรรพ์แห่งโอไฮโอ)',
      'The Great Serpent Mound (The Prehistoric Effigy of Adams County)',
      'legend',
      'โอไฮโอ',
      'Ohio',
      'พีเบิลส์ แอดัมส์',
      'Peebles, Adams County',
      39.0253,
      -83.4303,
      'creepy_wind',
      'เนินดินรูปสัตว์ (Effigy Mound) ยุคก่อนประวัติศาสตร์ที่ยาวที่สุดในโลก มีความยาวมากกว่า 411 เมตร (1,348 ฟุต) สูงประมาณ 1 เมตร สร้างเป็นรูปงูยักษ์ที่ขดลำตัวเลื้อยไปตามแนวสันเขาหินปูนริมลำห้วยบรัชครีก ส่วนหัวของงูอ้าปากกลืนหรือคายไข่วงรีขนาดใหญ่ ตำนานทางดาราศาสตร์ระบุว่าหัวของงูและไข่วงรีวางแนวตรงกับพระอาทิตย์ตกดินในวันครีษมายัน (Summer Solstice) อย่างแม่นยำ นอกจากนี้เนินดินนี้ยังสร้างขึ้นบนปากหลุมอุกกาบาตโบราณที่ชนพื้นเมืองเชื่อว่าเป็นจุดรวมพลังจักรวาล',
      'The Great Serpent Mound in Adams County, Ohio, is the largest surviving prehistoric serpentine earthwork on Earth, stretching 1,348 feet across a high limestone ridge. Depicting an undulating snake with an coiled tail and an open mouth holding an oval egg-shaped effigy, the mound aligns precisely with the summer solstice sunset and lunar maximum cycles. The earthwork rests atop an ancient meteorite cryptoexplosion crater, regarded by indigenous cultures as a potent vortex of telluric earth energies.',
      'สร้างขึ้นโดยชนเผ่าฟอร์ตเอนเชียนต์ (Fort Ancient) หรือวัฒนธรรมอะดีนา (Adena) โดยสามารถมองเห็นรูปร่างงูยักษ์สมบูรณ์แบบได้เฉพาะจากมุมมองบนท้องฟ้าเท่านั้น',
      'Attributed to the Fort Ancient or Adena cultures, the complex serpent geometry can only be fully appreciated from aerial vantage points, sparking astronomical alignment theories.',
      'ห้ามเดินเหยียบย่ำบนสันเนินดินงูยักษ์เพื่อป้องกันการกัดเซาะและเคารพบรรพชน',
      'Stay strictly on the designated viewing paths; walking across the earthen serpent ridge is strictly forbidden.',
      'https://i.ytimg.com/vi/IzHwvZE1QmY/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/IzHwvZE1QmY/hqdefault.jpg","title":"เกรตเซอร์เพนต์เมานด์ (เนินดินงูยักษ์ดึกดำบรรพ์แห่งโอไฮโอ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=IzHwvZE1QmY","title":"Something About Ohio''s Serpent Mound Still Doesn''t Add Up","thumbnail":"https://i.ytimg.com/vi/IzHwvZE1QmY/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-coral-castle-ed-leedskalnin',
      'ปราสาทปะการัง (ความลับพลังแม่เหล็กและการยกหินยักษ์ของเอ็ด ลีดสคัลนิน)',
      'Coral Castle (The Magnetic Levitation Feat of Edward Leedskalnin)',
      'legend',
      'ฟลอริดา',
      'Florida',
      'โฮมสเตด ไมอามี-เดด',
      'Homestead, Miami-Dade County',
      25.5006,
      -80.4442,
      'jungle_curse',
      'ปราสาทหินปะการังขนาดมหึมาที่สร้างขึ้นโดย เอ็ดเวิร์ด ลีดสคัลนิน ผู้อพยพชาวลัตเวียร่างเล็กสูงเพียง 5 ฟุต หนัก 100 ปอนด์ ระหว่างปี 1923 ถึง 1951 เขาตัด เคลื่อนย้าย และแกะสลักหินปะการังโอโอไลต์น้ำหนักรวมกว่า 1,100 ตันด้วยตัวคนเดียวในเวลากลางคืนโดยไม่มีใครเคยเห็นเขาทำงาน ประตูกลหินหมุนหนัก 9 ตันสามารถเปิดออกได้ด้วยแรงผลักเพียงปลายนิ้วเดียวของเด็ก เมื่อถูกถามว่าเขาสร้างได้อย่างไร เขาตอบเพียงว่า ''ผมได้ค้นพบความลับของการสร้างปิรามิดอียิปต์ และรู้วิธีการควบคุมพลังงานแม่เหล็กของโลก''',
      'Coral Castle in Homestead, Florida, is a jaw-dropping megalithic monument hand-carved single-handedly from over 1,100 tons of dense oolitic limestone by Edward Leedskalnin, a frail 100-pound Latvian immigrant. Built secretly under the cover of night between 1923 and 1951 as a tribute to his lost love, Ed claimed to understand the gravitational and magnetic secret of the Egyptian pyramids. Highlights include a nine-ton revolving gate balanced so perfectly that a child can open it with a single finger touch.',
      'นักฟิสิกส์และวิศวกรยุคใหม่ยังคงทึ่งกับความสมดุลอันแม่นยำของประตูกลหิน ซึ่งหมุนบนตลับลูกปืนรถบรรทุกเก่าแกนกลางหินปะการัง',
      'When the nine-ton gate finally seized in 1986, it required a crane and dozens of engineers to replace the custom spindle bearings that Ed had installed alone.',
      'ห้ามใช้แรงกระแทกหรือพยายามงัดแงะแกนหมุนของประตูปราสาทปะการัง',
      'Do not slam or force the precision nine-ton rotating stone gate.',
      'https://i.ytimg.com/vi/qvvIqEexj_Y/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/qvvIqEexj_Y/hqdefault.jpg","title":"ปราสาทปะการัง (ความลับพลังแม่เหล็กและการยกหินยักษ์ของเอ็ด ลีดสคัลนิน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=qvvIqEexj_Y","title":"Levitating 1000 Tons of Stone? - The Coral Castle (Full Documentary)","thumbnail":"https://i.ytimg.com/vi/qvvIqEexj_Y/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-longyou-caves-zhejiang-china',
      'ถ้ำหลงโหยว (มหาถ้ำใต้พิภพสลักมือปริศนายี่สิบสี่ห้องแห่งเจ้อเจียง)',
      'The Longyou Caves (The 24 Hand-Carved Subterranean Grottoes)',
      'legend',
      'เจ้อเจียง',
      'Zhejiang',
      'หลงโหยว ฉวีโจว',
      'Longyou County, Quzhou',
      29.0667,
      119.2,
      'water_spirit',
      'เครือข่ายถ้ำใต้ดินหินทรายเทียมขนาดมหึมา 24 ห้องที่ถูกขุดค้นพบโดยบังเอิญในปี 1992 โดยชาวบ้านที่สูบน้ำออกจากบ่อน้ำลึก ถ้ำเหล่านี้มีอายุกว่า 2,000 ปี แต่ละห้องมีเสาหินค้ำยัน เพดานลาดเอียง และมีร่องรอยการสกัดหินด้วยสิ่วเป็นเส้นขนานเฉียง 60 องศาอย่างสม่ำเสมอตลอดทุกตารางนิ้ว ปริศนาคือการขุดหินปริมาตรรวมกว่า 1 ล้านลูกบาศก์เมตรเกิดขึ้นได้อย่างไรในยุคโบราณ โดยไม่มีบันทึกประวัติศาสตร์ใดในจีนเคยกล่าวถึง และไม่มีเศษหินที่ขุดออกตกค้างอยู่ในบริเวณรอบข้างแม้แต่น้อย',
      'Discovered accidentally in 1992 when local farmers pumped water from five village ponds, the Longyou Caves in Zhejiang Province comprise 24 monumental subterranean caverns carved entirely by hand out of solid siltstone over 2,000 years ago. Covering an area of 30,000 square meters, every wall, ceiling, and stone pillar is uniformly chiseled with parallel 60-degree diagonal grooves. Mystifyingly, historical annals contain zero records of their colossal construction, nor has any excavated spoil rock ever been found nearby.',
      'ผนังถ้ำบางส่วนมีภาพสลักนูนต่ำรูปม้า ปลา และนก ซึ่งเป็นสัญลักษณ์สามัญในศิลปะยุคก่อนราชวงศ์ฉิน',
      'Acoustical studies reveal extraordinary resonance properties throughout the chambers, sparking theories ranging from imperial military bunkers to sacred subterranean ceremonial halls.',
      'ห้ามขีดเขียนหรือทำลายร่องรอยสิ่วโบราณบนผนังหินทรายของถ้ำหลงโหยว',
      'Never scrape or deface the uniform parallel chisel strokes adorning the sandstone cavern walls.',
      'https://i.ytimg.com/vi/Y3x44S5CYOA/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/Y3x44S5CYOA/hqdefault.jpg","title":"ถ้ำหลงโหยว (มหาถ้ำใต้พิภพสลักมือปริศนายี่สิบสี่ห้องแห่งเจ้อเจียง)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=Y3x44S5CYOA","title":"The Longyou Caves | The Secrets of China’s Underground Labyrinth","thumbnail":"https://i.ytimg.com/vi/Y3x44S5CYOA/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-dendera-light-hathor-temple',
      'หลอดไฟเดนเดรา (ภาพสลักเทคโนโลยีไฟฟ้าโบราณแห่งวิหารฮาธอร์)',
      'The Dendera Light (The Ancient Electrical Mystery of Hathor Temple)',
      'legend',
      'กินา',
      'Qena Governorate',
      'เดนเดรา',
      'Dendera',
      26.1417,
      32.6703,
      'jungle_curse',
      'ภาพสลักหินนูนต่ำอันโด่งดังในห้องใต้ดินแคบของวิหารเทพีฮาธอร์ เมืองเดนเดรา ประเทศอียิปต์ ภาพสลักแสดงรูปวัตถุโปร่งแสงรูปทรงยาวคล้ายหลอดรังสีครุกส์ (Crookes Tube) หรือหลอดไฟฟ้ายุคใหม่ ด้านในมีงูเลื้อยคล้ายไส้หลอด ปลายหลอดต่อเข้ากับดอกบัวและสายเคเบิลที่มีเสาค้ำทรง ''เจด'' (Djed pillar) รองรับ นักทฤษฎีโบราณคดีนอกกระแสเชื่อว่าเป็นหลักฐานว่าชาวอียิปต์โบราณค้นพบและใช้พลังงานไฟฟ้าส่องสว่างภายในสุสานที่ไม่มีรอยเขม่าควันไฟ ขณะที่นักไอยคุปต์วิทยาระบุว่าเป็นสัญลักษณ์เทพฮอร์ซมาทูวีที่ถือกำเนิดจากดอกบัว',
      'In the crypts beneath the Greco-Roman Temple of Hathor at Dendera, Egypt, enigmatic stone reliefs depict figures operating oblong, bulbous objects resembling modern Crookes electrical discharge tubes. Complete with an undulating serpent filament inside, a lotus-flower socket, a braided cable wire, and a high-voltage Djed pillar insulator, alternative theorists propose the carvings prove ancient Egyptian mastery of electric illumination. Mainstream Egyptology interprets the iconography as mythological representations of the god Harsomtous emerging from a primeval lotus.',
      'ห้องใต้ดินของวิหารเดนเดราสร้างขึ้นอย่างลึกลับและเข้าถึงได้ผ่านช่องทางเดินแคบๆ ในกำแพงหนา แสดงว่าภาพสลักนี้เป็นความลับขั้นสูงสุดของเหล่านักบวช',
      'Engineers have successfully constructed functional vacuum tube replicas matching the exact relief proportions, generating radiant purple glow discharges in laboratory tests.',
      'ห้ามสัมผัสหรือส่องไฟฉายความร้อนสูงจ่อที่ภาพสลักหินในห้องใต้ดินเดนเดรา',
      'Do not touch or shine intense heat lamps directly against the delicate crypt reliefs.',
      'https://i.ytimg.com/vi/RA_PYsfeXac/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/RA_PYsfeXac/hqdefault.jpg","title":"หลอดไฟเดนเดรา (ภาพสลักเทคโนโลยีไฟฟ้าโบราณแห่งวิหารฮาธอร์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=RA_PYsfeXac","title":"Grok AI Reanalyzed the Dendera Light Bulb in Egypt — What It Found Technology Terrified Researchers","thumbnail":"https://i.ytimg.com/vi/RA_PYsfeXac/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-saqqara-bird-ancient-glider',
      'นกซัคคารา (เครื่องร่อนโบราณสองพันปีแห่งอียิปต์)',
      'The Saqqara Bird (The 2,200-Year-Old Egyptian Glider)',
      'legend',
      'กิซา',
      'Giza Governorate',
      'สุสานซัคคารา บัดราชิน',
      'Saqqara Necropolis, Badrashin',
      29.8711,
      31.2164,
      'creepy_wind',
      'วัตถุโบราณทำจากไม้มะเดื่อกาฟาก (Sycamore) ถูกค้นพบในปี 1898 ในสุสานของปา-ดิ-อิเมน ณ สุสานโบราณซัคคารา ประเทศอียิปต์ มีอายุประมาณ 200 ปีก่อนคริสตกาล วัตถุนี้มีรูปร่างคล้ายนกแต่ปีกทั้งสองข้างเหยียดตรงอย่างสมบูรณ์แบบ มีปีกหักงอลงด้านล่าง (Anhedral Angle) และที่สำคัญคือส่วนหางตั้งตรงในแนวตั้งประดุจหางเสือเครื่องบิน (Rudder) แทนที่จะเป็นหางนกแนวราบตามธรรมชาติ วิศวกรการบิน ดร.คาลิล เมสซีฮา ทดลองพบว่ามันมีคุณสมบัติทางอากาศพลศาสตร์ที่สามารถร่อนได้ในอากาศอย่างมั่นคง นำไปสู่ข้อถกเถียงว่าชาวอียิปต์โบราณอาจเคยสร้างเครื่องร่อนขนาดจริง',
      'Discovered in 1898 inside the tomb of Pa-di-Imen at the Saqqara necropolis, the Saqqara Bird is a 2,200-year-old carved sycamore artifact with a 7-inch wingspan. While cataloged as a bird figurine, aeronautical engineers quickly noted striking disparities: perfectly flat aerodynamic wings with anhedral drop-tips and a vertical rudder tail fin entirely absent in natural birds. Aerodynamic modeling and wind tunnel tests indicate the carving possesses sophisticated lift-to-drag gliding ratios, fueling theories of ancient Egyptian miniature aircraft prototypes.',
      'วัตถุโบราณชิ้นจริงได้รับการจัดแสดงอยู่ในพิพิธภัณฑ์อียิปต์ ณ กรุงไคโร ในหมวดเครื่องร่อนจำลองโบราณ',
      'Tested in wind tunnels by flight simulator engineers, the airframe demonstrates high lateral stability, requiring only a horizontal tailplane to achieve sustained manned-scale gliding.',
      'ห้ามทดลองขว้างปาหรือจับต้องวัตถุโบราณโดยไม่มีถุงมืออนุรักษ์',
      'Handle the delicate 2,000-year-old wooden artifact only with archival conservation gloves.',
      'https://i.ytimg.com/vi/SxALrzX2v9g/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/SxALrzX2v9g/hqdefault.jpg","title":"นกซัคคารา (เครื่องร่อนโบราณสองพันปีแห่งอียิปต์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=SxALrzX2v9g","title":"The Saqqara Bird – A Glider from the Past?","thumbnail":"https://i.ytimg.com/vi/SxALrzX2v9g/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-dropa-stones-baian-kara-discs',
      'แผ่นหินโดรปา (จานหินร่องเกลียวอารยธรรมต่างดาวแห่งเทือกเขาบาเยนฮาร์)',
      'The Dropa Stones (The Spiral Discs of the Bayan Har Mountains)',
      'legend',
      'ชิงไห่',
      'Qinghai',
      'เทือกเขาบายันฮาร์ ยู่ซู่',
      'Bayan Har Mountains, Yushu',
      34.2,
      97.5,
      'jungle_curse',
      'ในปี 1938 ศาสตราจารย์ฉีผู่ไถ นำคณะสำรวจเข้าไปในถ้ำสูงชันของเทือกเขาบายันฮาร์ บริเวณพรมแดนทิเบต-ชิงไห่ และได้ค้นพบหลุมฝังศพของมนุษย์ร่างเล็กสูงเพียง 4 ฟุตที่มีกะโหลกศีรษะใหญ่ผิดปกติ ข้างโครงกระดูกพบแผ่นหินแกรนิตทรงกลมแบนคล้ายแผ่นเสียงไวนิล 716 แผ่น หนา 2 เซนติเมตร มีรูตรงกลางและมีร่องเกลียวสลักอักษรภาพขนาดจิ๋ว ในปี 1962 นักวิจัย ซุม อุม นุย อ้างว่าสามารถแปลความหมายได้ว่า ชนเผ่าโดรปาเดินทางมาจากอวกาศด้วยยานที่ประสบอุบัติเหตุตกบนภูเขาแห่งนี้ และไม่สามารถซ่อมแซมยานกลับบ้านได้',
      'In 1938, Chinese archaeologist Chi Pu Tei led an expedition into the isolated caves of the Bayan Har Mountains along the Tibetan border, discovering strange graves holding diminutive skeletal beings with oversized craniums. Entombed beside them were 716 circular granite discs (''Dropa Stones''), each etched with microscopic spiral hieroglyphs running from a central hole to the rim. In 1962, professor Tsum Um Nui controversially claimed to decipher the grooves as a message detailing an extraterrestrial scout ship crash 12,000 years ago whose marooned survivors became known as the Dropa.',
      'นักวิจัยชาวรัสเซีย ดร.เวียเชสลาฟ ไซต์เซฟ เคยนำแผ่นหินไปทดสอบและพบว่ามันสะท้อนคลื่นแม่เหล็กไฟฟ้าและสั่นสะเทือนด้วยความถี่สูงเมื่อวางบนเครื่องบันทึกเสียง',
      'Soviet researchers who examined sample discs reported they contained abnormally high cobalt concentrations and exhibited resonant electrical oscillations.',
      'ห้ามขุดค้นหรือรบกวนถ้ำโครงกระดูกโบราณบนเทือกเขาบายันฮาร์',
      'Never desecrate or exhume unmarked cave graves across the remote Bayan Har ridge.',
      'https://i.ytimg.com/vi/sQ-HA11nWsw/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/sQ-HA11nWsw/hqdefault.jpg","title":"แผ่นหินโดรปา (จานหินร่องเกลียวอารยธรรมต่างดาวแห่งเทือกเขาบาเยนฮาร์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=sQ-HA11nWsw","title":"Did GODS Build This Epic Stone Structure?! | Ancient Aliens | #shorts | History","thumbnail":"https://i.ytimg.com/vi/sQ-HA11nWsw/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-piri-reis-map-antarctica',
      'แผนที่พีรี เรอิส (แผนที่ขั้วโลกใต้ไร้น้ำแข็งแห่งศตวรรษที่ 16)',
      'The Piri Reis Map (The 1513 Ice-Free Antarctic Enigma)',
      'legend',
      'อิสตันบูล',
      'Istanbul',
      'พระราชวังโทพคาปึ ฟาติห์',
      'Topkapi Palace, Fatih',
      41.0115,
      28.9833,
      'jungle_curse',
      'แผนที่โลกโบราณที่วาดขึ้นบนหนังละมั่งในปี ค.ศ. 1513 โดยนายพลเรือและนักทำแผนที่ชาวออตโตมัน พีรี เรอิส ถูกค้นพบโดยบังเอิญในห้องสมุดพระราชวังโทพคาปึเมื่อปี 1929 ความน่าอัศจรรย์ที่สร้างความตกตะลึงให้นักวิชาการคือ แผนที่นี้แสดงแนวชายฝั่งทวีปอเมริกาใต้และทวีปแอนตาร์กติกา (ควีนมอดแลนด์) อย่างละเอียดแม่นยำ ทั้งที่แอนตาร์กติกาเพิ่งถูกค้นพบอย่างเป็นทางการในปี 1820 และที่ลึกลับยิ่งกว่าคือ มันแสดงแนวชายฝั่งแบบ ''ไร้น้ำแข็ง'' (Ice-Free) ซึ่งตรงกับชั้นหินใต้ผืนน้ำแข็งที่ตรวจวัดด้วยคลื่นโซนาร์สมัยใหม่ แสดงว่าต้นฉบับแผนที่เดิมอาจถูกวาดขึ้นก่อนที่น้ำแข็งจะปกคลุมขั้วโลกเมื่อหลายพันปีก่อน',
      'Drawn on gazelle skin parchment in 1513 by Ottoman admiral and cartographer Piri Reis, this surviving map fragment was rediscovered in Istanbul''s Topkapi Palace in 1929. The map displays the coastlines of West Africa, South America, and an enigmatic southern landmass identified by researchers like Charles Hapgood as Queen Maud Land, Antarctica. Bizarrely, Antarctica was not officially discovered until 1820, and the map depicts the subglacial topography devoid of ice, a geographical state that geological surveys confirm has not existed for thousands of years.',
      'พีรี เรอิส บันทึกไว้ที่ขอบแผนที่ว่าเขาคัดลอกและรวบรวมข้อมูลมาจากแผนที่โบราณกว่า 20 แผ่น รวมถึงแผนที่สมัยพระเจ้าอเล็กซานเดอร์มหาราช',
      'Piri Reis noted on the parchment margin that he compiled the charts from twenty older source maps, including ancient Greek maps from the Library of Alexandria.',
      'ห้ามใช้แสงแฟลชถ่ายภาพแผนที่ต้นฉบับบนหนังละมั่งในพิพิธภัณฑ์โทพคาปึ',
      'Do not expose the fragile 1513 gazelle parchment to camera flashes or ultraviolet light.',
      'https://i.ytimg.com/vi/ubkM4U8BWfQ/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/ubkM4U8BWfQ/hqdefault.jpg","title":"แผนที่พีรี เรอิส (แผนที่ขั้วโลกใต้ไร้น้ำแข็งแห่งศตวรรษที่ 16)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=ubkM4U8BWfQ","title":"The Piri Reis Map Explained: History, Mystery, and Ancient Civilizations","thumbnail":"https://i.ytimg.com/vi/ubkM4U8BWfQ/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-london-hammer-texas-creek',
      'ค้อนลอนดอน (ค้อนเหล็กในก้อนหินล้านปีแห่งเท็กซัส)',
      'The London Hammer (The Out-of-Place Artifact of Red Creek)',
      'legend',
      'เท็กซัส',
      'Texas',
      'ลอนดอน คิมเบิล',
      'London, Kimble County',
      30.6761,
      -99.5767,
      'creepy_wind',
      'วัตถุโบราณผิดยุค (OOPArt) ที่สร้างความฮือฮาไปทั่วโลก ค้นพบในปี 1936 ริมลำห้วยเรดครีก ใกล้เมืองลอนดอน รัฐเท็กซัส เมื่อครอบครัวฮาห์นพบก้อนหินปูนคอนครีชันที่มีด้ามไม้โผล่ออกมา เมื่อกะเทาะหินออกพบหัวค้อนเหล็กความยาว 15 เซนติเมตร ฝังแน่นอยู่ภายในเนื้อหินปูนยุคออร์โดวิเชียนหรือครีเทเชียส ซึ่งมีอายุทางธรณีวิทยากว่า 100 ถึง 400 ล้านปี ผลการทดสอบโลหะวิทยาพบว่าหัวค้อนทำจากเหล็กบริสุทธิ์ถึง 96.6% ไร้สนิมและไม่มีฟองอากาศภายในโลหะ สร้างคำถามว่ามนุษย์หรือเทคโนโลยีใดทำค้อนนี้ขึ้นก่อนยุคไดโนเสาร์',
      'Discovered in 1936 by Max Hahn while walking along Red Creek near London, Texas, the London Hammer is an infamous Out-of-Place Artifact (OOPArt). Encased inside a solid concretion of limestone dating geologically to the Cretaceous or Ordovician period (over 100 to 400 million years old), the hammer''s iron head and fossilized wooden handle are fused into the stone. Metallurgical scans revealed the head consists of 96.6% pure iron without carbon impurities or rust, fueling debates between creationists, alternative historians, and geologists.',
      'นักธรณีวิทยาสายกระแสหลักอธิบายว่าหินปูนอาจเกิดจากการสะสมตัวของแร่ธาตุรอบค้อนของคนงานเหมืองในศตวรรษที่ 19 แต่ผู้ศรัทธาเชื่อว่าเป็นหลักฐานของอารยธรรมโบราณขั้นสูง',
      'While mainstream scientists argue the hammer fell into a mineral-rich solution forming a rapid modern concretion, the artifact remains permanently displayed in Glen Rose''s Creation Evidence Museum.',
      'ห้ามใช้กรดหรือของมีคมขูดเนื้อเหล็กของค้อนลอนดอน',
      'Never scrape or apply acid etching to the pristine iron surface of the London Hammer.',
      'https://i.ytimg.com/vi/4OzpkXKPUvU/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/4OzpkXKPUvU/hqdefault.jpg","title":"ค้อนลอนดอน (ค้อนเหล็กในก้อนหินล้านปีแห่งเท็กซัส)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=4OzpkXKPUvU","title":"EXPLAINED: Mysterious Ancient Artifact Locked In Stone - The London Hammer","thumbnail":"https://i.ytimg.com/vi/4OzpkXKPUvU/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-shugborough-inscription-shepherds-code',
      'จารึกชักโบโรห์ (รหัสลับจอกศักดิ์สิทธิ์แห่งอนุสาวรีย์คนเลี้ยงแกะ)',
      'The Shugborough Inscription (The Unsolved Holy Grail Cipher)',
      'legend',
      'สแตฟฟอร์ดเชอร์',
      'Staffordshire',
      'คฤหาสน์ชักโบโรห์ เกรตเฮย์วูด',
      'Shugborough Hall, Great Haywood',
      52.7997,
      -2.0125,
      'whisper',
      'อนุสาวรีย์คนเลี้ยงแกะ (Shepherd''s Monument) ในคฤหาสน์ชักโบโรห์ ประเทศอังกฤษ สร้างขึ้นในศตวรรษที่ 18 มีภาพสลักหินนูนต่ำจำลองภาพวาด ''คนเลี้ยงแกะแห่งอาร์คาเดีย'' ของนีกอลา ปูแซ็ง แต่กลับมีภาพสะท้อนกลับด้าน ใต้ภาพสลักมีตัวอักษรปริศนาสลักอยู่ 10 ตัว: ''O U O S V A V V'' ขนาบข้างด้วย ''D M'' รหัสลับนี้ไม่เคยมีใครถอดรหัสได้ตลอด 250 ปี แม้แต่นักคิดระดับโลกอย่าง ชาลส์ ดาร์วิน, ชาลส์ ดิกเคนส์ และนักถอดรหัสแห่งเบลตช์ลีย์พาร์ก ตำนานเชื่อว่ารหัสนี้คือพิกัดซ่อน ''จอกศักดิ์สิทธิ์'' (Holy Grail) ของอัศวินเทมพลาร์',
      'Erected between 1748 and 1763 on the grounds of Shugborough Hall in Staffordshire, the Shepherd''s Monument features a carved relief mirror-image of Nicolas Poussin''s painting ''The Arcadian Shepherds''. Beneath the pastoral tomb scene is a mysterious 10-letter sequence: ''D O U O S V A V V M''. Uncracked for over 250 years despite intensive efforts by Charles Darwin, Charles Dickens, and Bletchley Park WWII codebreakers, conspiracy lore links the cipher to the hidden coordinates of the Holy Grail guarded by the Priory of Sion.',
      'ตระกูลแอนสันผู้สร้างคฤหาสน์มีความเชื่อมโยงกับสมาคมลับและกลุ่มอัศวินเทมพลาร์ ทำให้ผู้คนเชื่อว่ารหัสลับนี้เป็นมรดกตกทอดทางประวัติศาสตร์',
      'Constructed by George Anson, First Lord of the Admiralty, speculative historians suggest the cipher protects secret navigational charts to immense Templar treasures.',
      'ห้ามขูดขีดหรือสัมผัสตัวอักษรจารึกหินสิบตัวบนอนุสาวรีย์ชักโบโรห์',
      'Do not touch or trace sharp implements over the ten carved letters of the Shugborough cipher.',
      'https://i.ytimg.com/vi/jxAJrUXITHM/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/jxAJrUXITHM/hqdefault.jpg","title":"จารึกชักโบโรห์ (รหัสลับจอกศักดิ์สิทธิ์แห่งอนุสาวรีย์คนเลี้ยงแกะ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=jxAJrUXITHM","title":"The Hidden Grail Cipher: The Shugborough Mystery","thumbnail":"https://i.ytimg.com/vi/jxAJrUXITHM/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-georgia-guidestones-elberton',
      'จอร์เจียไกด์สโตนส์ (อนุสาวรีย์บัญญัติสิบประการแห่งวันสิ้นโลก)',
      'The Georgia Guidestones (The American Stonehenge of Elberton)',
      'legend',
      'จอร์เจีย',
      'Georgia',
      'เอลเบิร์ตตัน เอลเบิร์ต',
      'Elberton, Elbert County',
      34.2319,
      -82.8944,
      'jungle_curse',
      'อนุสาวรีย์หินแกรนิตขนาดยักษ์สูงเกือบ 6 เมตร หนักกว่า 110 ตัน สร้างขึ้นในปี 1980 บนเนินเขาเปลี่ยวในเมืองเอลเบิร์ตตัน รัฐจอร์เจีย โดยชายลึกลับที่ใช้นามแฝงว่า ''อาร์. ซี. คริสเตียน'' แผ่นหินสลักข้อความชี้นำมนุษยชาติ 10 ประการใน 8 ภาษาโบราณและสมัยใหม่ โดยมีข้อความแรกสุดอันเป็นที่ถกเถียงว่า ''ควบคุมจำนวนประชากรมนุษย์ให้อยู่ต่ำกว่า 500 ล้านคนเพื่อสมดุลกับธรรมชาติ'' หินได้รับการจัดวางตามตำแหน่งดาราศาสตร์ มีช่องมองดาวเหนือและช่องรับแสงอาทิตย์เที่ยงวัน ก่อนจะถูกลอบวางระเบิดทำลายปริศนาในปี 2022',
      'Erected in 1980 in rural Elbert County, Georgia, the Georgia Guidestones was a massive astronomical granite monument dubbed ''America''s Stonehenge''. Commissioned anonymously under the pseudonym R.C. Christian, four monolithic slabs bore ten guides for humanity inscribed in eight modern languages, topped by a capstone bearing four ancient scripts. The most controversial commandment urged keeping human population below 500 million. Serving as a solar calendar, the monument was mysteriously bombed in July 2022 and subsequently dismantled.',
      'ตัวตนที่แท้จริงของ อาร์. ซี. คริสเตียน และวัตถุประสงค์ของการสร้างยังคงเป็นปริศนา โดยมีทฤษฎีโยงไปถึงลัทธิโรซิครูเชียนหรือกลุ่มผู้อยู่เบื้องหลังการจัดระเบียบโลกใหม่',
      'Conspiracy lore linked the monument to Rosicrucian secret societies preparing instructions for rebuilding civilization following a thermonuclear apocalypse.',
      'ห้ามขุดค้นบริเวณหลุมแคปซูลกาลเวลาใต้ฐานหินไกด์สโตนส์เดิม',
      'Do not trespass or dig into the contested time capsule vault site at the Guidestones foundation.',
      'https://i.ytimg.com/vi/S4P1kEDRGgI/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/S4P1kEDRGgI/hqdefault.jpg","title":"จอร์เจียไกด์สโตนส์ (อนุสาวรีย์บัญญัติสิบประการแห่งวันสิ้นโลก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=S4P1kEDRGgI","title":"Georgia Guidestones Mystery - Forgotten History","thumbnail":"https://i.ytimg.com/vi/S4P1kEDRGgI/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-tartaria-tablets-vinca-symbols',
      'แผ่นจารึกทาร์ทาเรีย (อักษรโบราณเก่าแก่ที่สุดในยุโรปแห่งทรานซิลเวเนีย)',
      'The Tartaria Tablets (The 7,300-Year-Old Vinca Script of Transylvania)',
      'legend',
      'อัลบา',
      'Alba County',
      'หมู่บ้านทาร์ทาเรีย ซาลีชเต',
      'Tartaria, Salistea',
      45.9833,
      23.4167,
      'jungle_curse',
      'แผ่นดินเผาจารึกขนาดเล็ก 3 แผ่น ถูกค้นพบในปี 1961 โดยนักโบราณคดี นิโคเล วลาสซา ในหลุมศพโบราณที่หมู่บ้านทาร์ทาเรีย แคว้นทรานซิลเวเนีย ประเทศโรมาเนีย สองแผ่นเจาะรูสำหรับร้อยเชือก และมีสัญลักษณ์อักษรภาพสลักอยู่ ผลการหาอายุคาร์บอนกัมมันตรังสีของกระดูกที่พบในหลุมศพเดียวกันระบุว่ามีอายุย้อนไปถึง 5,300 ปีก่อนคริสตกาล (กว่า 7,300 ปีที่แล้ว) ซึ่งเก่าแก่กว่าอักษรคูนิฟอร์มของซูเมอร์และอักษรไฮเออโรกลีฟิกของอียิปต์เกือบ 2,000 ปี หากได้รับการพิสูจน์ว่าเป็นระบบการเขียนจริง นี่คือระบบตัวเขียนที่เก่าแก่ที่สุดในประวัติศาสตร์มนุษยชาติ',
      'Discovered in 1961 by archaeologist Nicolae Vlassa at a Neolithic burial pit in Tartaria, Romania, the Tartaria Tablets comprise three small incised clay tablets bearing pictographic engravings. Radiocarbon dating of associated human bones yielded an astonishing age of circa 5300 BCE, suggesting the Danube/Vinca culture possessed a proto-writing system predating Sumerian cuneiform and Egyptian hieroglyphs by over a millennium. The tablets spark ongoing global debate over the origins of human written literacy.',
      'หลุมศพที่ค้นพบเป็นของหญิงชราที่ถูกขนานนามว่า ''มิลาดี ทาร์ทาเรีย'' ซึ่งเชื่อว่าเป็นนักบวชหญิงหรือหมอผีประจำเผ่าวินชา (Vinca)',
      'The interred skeleton belonged to an arthritic elder woman termed ''Milady of Tartaria'', buried alongside ritual sacrificial offerings and charred bones.',
      'ห้ามเผาหรือใช้ความร้อนทดสอบแผ่นดินเผาโบราณทาร์ทาเรีย',
      'Never subject Neolithic clay artifacts to direct flame or rapid thermal shocks.',
      'https://i.ytimg.com/vi/o_9pajucH5A/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/o_9pajucH5A/hqdefault.jpg","title":"แผ่นจารึกทาร์ทาเรีย (อักษรโบราณเก่าแก่ที่สุดในยุโรปแห่งทรานซิลเวเนีย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=o_9pajucH5A","title":"The Tartaria Tablets: Rewriting the History of Writing","thumbnail":"https://i.ytimg.com/vi/o_9pajucH5A/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-phaistos-disc-minoan-enigma',
      'จานไพสตอส (แผ่นดินเผารหัสลับอารยธรรมมิโนอันแห่งครีต)',
      'The Phaistos Disc (The Unbroken Minoan Hieroglyphic Spiral)',
      'legend',
      'เฮราคลิออน',
      'Heraklion',
      'พระราชวังไพสตอส ครีต',
      'Phaistos Palace, Crete',
      35.0514,
      24.8142,
      'temple_bell',
      'จานดินเผาเคลือบไฟทรงกลมเส้นผ่านศูนย์กลาง 15 เซนติเมตร ค้นพบในปี 1908 ในพระราชวังมิโนอันโบราณแห่งไพสตอส บนเกาะครีต ประเทศกรีซ มีอายุประมาณ 1,700 ปีก่อนคริสตกาล บนแผ่นดินเผาทั้งสองด้านมีสัญลักษณ์ประทับตรา 241 ตัว เรียงตัวเป็นวงก้นหอยหมุนวนเข้าสู่จุดศูนย์กลาง สัญลักษณ์ประกอบด้วยรูปศีรษะประดับขนนก นก ปลา ขวานสองคม และพืชพันธุ์ ที่น่าทึ่งคือสัญลักษณ์เหล่านี้ไม่ได้วาดด้วยมือ แต่ใช้แม่พิมพ์ประทับลงบนดินเหนียวก่อนนำไปเผา ถือเป็นเทคโนโลยีการพิมพ์แบบเคลื่อนย้ายตัวพิมพ์ (Movable Type) ชิ้นแรกของโลก แต่รหัสลับของจานนี้ยังไม่เคยมีใครถอดรหัสได้สำเร็จ',
      'Unearthed in 1908 by Italian archaeologist Luigi Pernier at the Minoan palace of Phaistos on Crete, the Phaistos Disc is a fired clay disc roughly 15 cm across dating to circa 1700 BCE. Both faces feature a clockwise spiral of 241 stamped glyphic tokens partitioned into 61 distinct sign-groups. Astoundingly, the pictograms were stamped into soft clay using pre-formed movable seals—representing humanity''s earliest known typographic movable print technology. Its linguistic meaning remains an unsolved cryptological enigma.',
      'จานต้นฉบับได้รับการจัดแสดงในตู้กระจกนิรภัย ณ พิพิธภัณฑ์โบราณคดีเฮราคลิออน โดยมีทฤษฎีถอดรหัสตั้งแต่บทสวดสรรเสริญเทพีแห่งการเกิดจนถึงปฏิทินดาราศาสตร์',
      'Preserved in the Heraklion Archaeological Museum, proposed decryptions range from a Luwian prayer to an ancient nautical calendar, none achieving academic consensus.',
      'ห้ามแตะต้องหรือพยายามสร้างแม่พิมพ์ทาบลงบนรอยประทับดินเผาของจานไพสตอส',
      'Never attempt to cast molds or press materials directly against the unique Minoan clay stamps.',
      'https://i.ytimg.com/vi/IhkRJ4AQ7Lw/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/IhkRJ4AQ7Lw/hqdefault.jpg","title":"จานไพสตอส (แผ่นดินเผารหัสลับอารยธรรมมิโนอันแห่งครีต)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=IhkRJ4AQ7Lw","title":"The Phaistos Disc Nobody Can Read","thumbnail":"https://i.ytimg.com/vi/IhkRJ4AQ7Lw/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-roman-dodecahedron-bronze-enigma',
      'โดเดคาฮีดรอนแห่งจักรวรรดิโรมัน (วัตถุบรอนซ์สิบสองหน้าปริศนาแห่งกอล)',
      'The Roman Dodecahedron (The Gallo-Roman Bronze Twelve-Sided Enigma)',
      'legend',
      'นอร์เดิร์นแกลเลีย',
      'Northern Gaul',
      'ภูมิภาคไรน์ลันด์และกอลโบราณ',
      'Gallo-Roman Frontier',
      50.7753,
      6.0839,
      'jungle_curse',
      'หนึ่งในปริศนาที่ยิ่งใหญ่ที่สุดของโบราณคดียุโรป วัตถุหล่อสำริดกลวงทรงสิบสองหน้า (Dodecahedron) สร้างขึ้นในศตวรรษที่ 2 ถึง 4 มีการขุดพบมากกว่า 120 ชิ้นเฉพาะในดินแดนกอลและบริเตน (ภาคเหนือของจักรวรรดิโรมัน) แต่ละหน้าเป็นรูปห้าเหลี่ยมเจาะรูกลมขนาดไม่เท่ากัน และมีปุ่มกลมนูนที่มุมทั้ง 20 มุม ปริศนาคือไม่มีเอกสาร บันทึก หรือภาพวาดใดของโรมันกล่าวถึงวัตถุนี้เลย ทฤษฎีการใช้งานมีตั้งแต่ อุปกรณ์คำนวณดาราศาสตร์ทางการเกษตร เครื่องมือวัดระยะทางทหาร อุปกรณ์ถักถุงมือไหมพรม ไปจนถึงเครื่องรางทางไสยศาสตร์ของดรูอิด',
      'The Roman Dodecahedron is a small hollow bronze artifact featuring twelve flat pentagonal faces, each punctured with a circular hole of differing diameter, and topped with small knobs at every vertex. Over 120 specimens dating from the 2nd to 4th centuries CE have been unearthed across the northwestern Roman provinces (Gaul, Britain, Germany), yet not a single mention, diagram, or reference exists in contemporary classical literature. Guesses regarding their function span range-finding ballistics, astronomical sowing gauges, glove-knitting jigs, and Celtic occult talismans.',
      'หลายชิ้นถูกค้นพบในหลุมศพของสตรีและกองสมบัติเหรียญเงิน แสดงว่ามันเป็นสิ่งของที่มีมูลค่าสูงและผูกพันกับเจ้าของอย่างลึกซึ้ง',
      'Frequently found among luxury coin hoards and elite burials, archaeological consensus agrees they held high value to their Gallo-Roman owners.',
      'ห้ามใช้ความร้อนหรือดัดแปลงปุ่มสัมฤทธิ์โบราณของวัตถุสิบสองหน้าโรมัน',
      'Handle the delicate hollow bronze casting without applying bending stress to the vertex knobs.',
      'https://i.ytimg.com/vi/ZV0rPtzHYaY/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/ZV0rPtzHYaY/hqdefault.jpg","title":"โดเดคาฮีดรอนแห่งจักรวรรดิโรมัน (วัตถุบรอนซ์สิบสองหน้าปริศนาแห่งกอล)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=ZV0rPtzHYaY","title":"The UnXplained: Mystery of the Roman Dodecahedron (S6) | History","thumbnail":"https://i.ytimg.com/vi/ZV0rPtzHYaY/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-beale-ciphers-bedford-gold',
      'รหัสลับบีล (ลายแทงทองคำมหาศาลที่ซ่อนอยู่ในเบดฟอร์ดเคาน์ตี)',
      'The Beale Ciphers (The Uncracked Multimillion-Dollar Virginia Treasure)',
      'legend',
      'เวอร์จิเนีย',
      'Virginia',
      'เบดฟอร์ด มอนท์เวล',
      'Bedford County, Montvale',
      37.3889,
      -79.7222,
      'whisper',
      'เรื่องราวลายแทงสมบัติที่มีชื่อเสียงที่สุดของสหรัฐฯ เริ่มต้นในปี 1820 เมื่อ โทมัส เจ. บีล นำกล่องเหล็กล็อคกุญแจมาฝากไว้กับเจ้าของโรงแรมในเมืองลินช์เบิร์ก และไม่เคยกลับมาอีก เมื่อเปิดกล่องออกพบเอกสารรหัสตัวเลขสามชุด ชุดที่สองได้รับการถอดรหัสสำเร็จโดยใช้ ''คำประกาศอิสรภาพสหรัฐฯ'' เป็นกุญแจ ระบุว่าบีลและคณะค้นพบทองคำและเงินมูลค่ามหาศาลในนิวเม็กซิโกและนำมาฝังไว้ในห้องใต้ดินหินลึก 6 ฟุตในเบดฟอร์ดเคาน์ตี แต่แผ่นรหัสที่หนึ่ง (บอกตำแหน่งที่ซ่อนที่แน่นอน) และแผ่นที่สาม (ระบุรายชื่อผู้รับมรดก) ยังไม่เคยมีใครถอดรหัสได้จนถึงปัจจุบัน',
      'The Beale Ciphers are a set of three encrypted numerical texts published in an 1885 pamphlet in Virginia. Originating with Thomas J. Beale in 1820, Paper Number Two was successfully deciphered using the United States Declaration of Independence as a keytext, revealing the existence of a buried cache of thousands of pounds of gold, silver, and jewels concealed six feet underground in Bedford County. However, Cipher Number One—which details the exact physical vault location—and Cipher Number Three remain completely uncracked despite analysis by the NSA and master cryptanalysts.',
      'มูลค่าของทองคำและเงินที่ระบุในเอกสารหากมีอยู่จริงในปัจจุบันจะมีมูลค่ามากกว่า 65 ล้านดอลลาร์สหรัฐ ทำให้มีนักล่าสมบัติตะลุยขุดค้นหุบเขาบลูริดจ์มานานนับศตวรรษ',
      'Treasure hunters have excavated farmsteads and hillsides across the Blue Ridge Mountains for decades, inspiring countless cryptological studies and national television specials.',
      'ห้ามขุดค้นที่ดินส่วนบุคคลในเบดฟอร์ดเคาน์ตีโดยไม่ได้รับอนุญาตทางกฎหมาย',
      'Never trespass or conduct illegal excavations on private property across Bedford County.',
      'https://i.ytimg.com/vi/0A2H2dJ0d_c/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/0A2H2dJ0d_c/hqdefault.jpg","title":"รหัสลับบีล (ลายแทงทองคำมหาศาลที่ซ่อนอยู่ในเบดฟอร์ดเคาน์ตี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0A2H2dJ0d_c","title":"Beale Ciphers: The 200-Year-Old Unsolved Code Hiding A Buried Fortune","thumbnail":"https://i.ytimg.com/vi/0A2H2dJ0d_c/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-monster-grafton-monster-wv',
      'สัตว์ประหลาดกราฟตัน (อสูรยักษ์สีขาวไร้คอแห่งเวสต์เวอร์จิเนีย)',
      'The Grafton Monster (The Headless White Beast of Taylor County)',
      'monster',
      'เวสต์เวอร์จิเนีย',
      'West Virginia',
      'กราฟตัน เทย์เลอร์',
      'Grafton, Taylor County',
      39.3408,
      -80.0189,
      'creepy_wind',
      'ในคืนวันที่ 16 มิถุนายน 1965 โรเบิร์ต ค็อกแบล็ก นักข่าวนสพ. ท้องถิ่น ขับรถเลียบแม่น้ำไทการ์ตวัลเลย์ในเมืองกราฟตัน รัฐเวสต์เวอร์จิเนีย และได้เผชิญหน้ากับสิ่งมีชีวิตขนาดมหึมาสูงกว่า 8 ถึง 9 ฟุต ยืนอยู่ริมถนน ร่างกายของมันกว้างล่ำสัน ผิวหนังสีขาวเนียนไร้ขน และที่น่าขนลุกที่สุดคือมันดูคล้ายไม่มีหัวหรือคอ โดยส่วนศีรษะยุบตัวลงไปอยู่ระหว่างหัวไหล่หนา มันส่งเสียงฟ่อขู่คล้ายหม้อต้มน้ำเดือดก่อนจะเคลื่อนตัวหนีหายเข้าไปในป่ารกริมแม่น้ำอย่างรวดเร็ว',
      'On June 16, 1965, local newspaper reporter Robert Cockrell was driving along Riverside Drive beside the Tygart Valley River in Grafton, West Virginia, when he spotted an astonishing creature. Standing nearly nine feet tall with a colossal four-foot-wide torso, the bipedal entity possessed pale, hairless skin resembling a slick seal and appeared virtually headless, its facial features tucked flush between massive muscular shoulders. Whistling with low steam-like hisses, the beast melted into the dense riverbank brush.',
      'การพบเห็นนำไปสู่นักศึกษาและชาวบ้านติดอาวุธหลายสิบคนออกค้นหาในป่าริมแม่น้ำไทการ์ต และกลายเป็นตำนานสัตว์ประหลาดชื่อดังของเวสต์เวอร์จิเนียเคียงคู่มอธแมน',
      'Armed hunting parties of university students searched the river woods for weeks; today, Grafton celebrates its legendary headless white beast with statues and annual cryptid festivals.',
      'ห้ามเดินเลียบฝั่งแม่น้ำไทการ์ตคนเดียวในคืนที่อากาศร้อนอบอ้าว',
      'Avoid wandering the unlit Tygart riverbanks alone on sweltering summer nights.',
      'https://i.ytimg.com/vi/9-uHla8qZJo/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/9-uHla8qZJo/hqdefault.jpg","title":"สัตว์ประหลาดกราฟตัน (อสูรยักษ์สีขาวไร้คอแห่งเวสต์เวอร์จิเนีย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=9-uHla8qZJo","title":"The Grafton Monster","thumbnail":"https://i.ytimg.com/vi/9-uHla8qZJo/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-monster-tsuchinoko-fat-snake-japan',
      'ซึจิโนโกะ (อสรพิษอ้วนพุงป่องผู้กระโดดไกลแห่งญี่ปุ่น)',
      'Tsuchinoko (The Legendary Jumping Chubby Serpent of Japan)',
      'monster',
      'กิฟุ',
      'Gifu Prefecture',
      'ชิราคาวะ คาโมะ',
      'Shirakawa, Kamo District',
      35.5833,
      137.1833,
      'water_spirit',
      'สัตว์ประหลาดลึกลับในตำนานพื้นบ้านญี่ปุ่นที่มีการบันทึกมาตั้งแต่ยุคโจมง มีลักษณะคล้ายงูแต่ลำตัวช่วงกลางอ้วนป่องกลมคล้ายท่อนฟืนหรือค้อนทุบฟาง มีความยาวประมาณ 30 ถึง 80 เซนติเมตร ลำคอเรียวเล็ก เกล็ดสีน้ำตาลลายจุด มีตาสองข้างที่กะพริบได้เหมือนมนุษย์ สิ่งที่น่าอัศจรรย์คือมันสามารถกระโดดลอยตัวในอากาศได้ไกลกว่า 1 ถึง 2 เมตร สามารถกลิ้งตัวลงจากเนินเขาโดยการอมหางตัวเองเป็นวงล้อ และส่งเสียงร้องคล้ายคนกรนหรือเสียงนกหวีด',
      'The Tsuchinoko is Japan''s most famous elusive cryptid, documented in folklore since the prehistoric Jomon period. Described as a stout, heavy-bodied serpent between 1 and 3 feet long with a distinct slender neck and a disproportionately wide, barrel-shaped belly, witnesses report it can blink its eyes, emit chirping or snoring vocalizations, roll downhill by biting its tail in a hoop, and jump distances of up to six feet in the air.',
      'ในเมืองชิราคาวะ จังหวัดกิฟุ มีการตั้งเงินรางวัลตามล่าซึจิโนโกะตัวเป็นๆ สูงถึง 100 ล้านเยน และมีการจัดงานเทศกาลจับซึจิโนโกะเป็นประจำทุกปี',
      'Multiple Japanese municipalities, most famously Shirakawa in Gifu, have established standing bounties reaching over 100 million yen ($1M) for the live capture of a verified Tsuchinoko specimen.',
      'ห้ามรับประทานปลาแห้งหรือดื่มสาเกในป่าเพราะกลิ่นจะล่อซึจิโนโกะเข้ามา',
      'Do not leave open cups of dried fish or sake exposed in deep mountain bamboo groves.',
      'https://i.ytimg.com/vi/ksJ8CkrWwcg/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/ksJ8CkrWwcg/hqdefault.jpg","title":"ซึจิโนโกะ (อสรพิษอ้วนพุงป่องผู้กระโดดไกลแห่งญี่ปุ่น)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=ksJ8CkrWwcg","title":"Tsuchinoko — Japan’s Hidden Cryptid","thumbnail":"https://i.ytimg.com/vi/ksJ8CkrWwcg/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-monster-ningen-antarctic-humanoid-giant',
      'นิงเง็น (อสูรมนุษย์ยักษ์ผิวเผือกแห่งมหาสมุทรแอนตาร์กติก)',
      'The Ningen (The Colossal Pale Humanoid of Antarctic Seas)',
      'monster',
      'มหาสมุทรใต้',
      'Southern Ocean',
      'น่านน้ำแอนตาร์กติก',
      'Antarctic Waters',
      -65,
      -64,
      'jungle_curse',
      'ตำนานสิ่งมีชีวิตลี้ลับใต้ผืนน้ำแข็งขั้วโลกใต้ที่เริ่มเป็นที่พูดถึงในยุคทศวรรษ 1990 จากปากคำของลูกเรือประมงและนักวิจัยเรือล่าวาฬของรัฐบาลญี่ปุ่น ''นิงเง็น'' (คำในภาษาญี่ปุ่นแปลว่า มนุษย์) มีรูปร่างคล้ายสิ่งมีชีวิตครึ่งคนครึ่งสัตว์น้ำขนาดยักษ์ ความยาวกว่า 20 ถึง 30 เมตร ผิวหนังขาวเนียนไร้รอยต่อเหมือนหิมะ ลำตัวมีแขนยาวคล้ายมนุษย์ มีนิ้วมือ และมีหางคล้ายปลาวาฬหรือเงือก มักโผล่ขึ้นมาลอยตัวบนผิวน้ำในยามค่ำคืนและดำดิ่งลงสู่ก้นบึ้งอันมืดมิดเมื่อมีเรือแล่นเข้าไปใกล้',
      'The Ningen is an enigmatic cryptid reported in the freezing waters of the Antarctic by Japanese government whale research crews since the 1990s. Deriving its name from the Japanese word for ''human'', eyewitnesses describe a colossal aquatic mammal estimated between 60 to 90 feet long with completely smooth, porcelain-white skin. Possessing identifiable humanoid upper appendages, five-fingered hands, and a whale-like fluked tail, the phantom creature reportedly observes survey ships before silently vanishing beneath the pack ice.',
      'ภาพถ่ายจากดาวเทียม Google Earth ในแถบมหาสมุทรแอนตาร์กติกเคยจับภาพเงาร่างสีขาวขนาดยักษ์ที่มีรูปร่างคล้ายสิ่งมีชีวิตใต้ทะเลลึกที่ไม่สามารถระบุสายพันธุ์ได้',
      'Sonar contacts and purported satellite captures in the Drake Passage show immense, unclassified biological signatures exhibiting high swimming agility in sub-zero currents.',
      'ห้ามทอดสมอเรือวิจัยในร่องน้ำแข็งที่พบฟองคลื่นสีขาวขนาดมหึมา',
      'Never drift directly over open ice-leads where massive pale submerged silhouettes are sighted.',
      'https://i.ytimg.com/vi/dwn0NsYXQjw/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/dwn0NsYXQjw/hqdefault.jpg","title":"นิงเง็น (อสูรมนุษย์ยักษ์ผิวเผือกแห่งมหาสมุทรแอนตาร์กติก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=dwn0NsYXQjw","title":"Ningen - Monster of the Arctic | A Cryptid Documentary | Mystery Syndicate","thumbnail":"https://i.ytimg.com/vi/dwn0NsYXQjw/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-monster-enfield-monster-illinois',
      'สัตว์ประหลาดเอนฟิลด์ (อสูรสามขาตาเรืองแสงแห่งอิลลินอยส์)',
      'The Enfield Monster (The Three-Legged Horror of White County)',
      'monster',
      'อิลลินอยส์',
      'Illinois',
      'เอนฟิลด์ ไวต์',
      'Enfield, White County',
      38.0989,
      -88.3364,
      'creepy_wind',
      'ในเดือนเมษายน 1973 ณ เมืองเอนฟิลด์ รัฐอิลลินอยส์ เด็กชายเกร็ก การ์เร็ตต์ ถูกโจมตีโดยสิ่งมีชีวิตประหลาดขณะเล่นอยู่ในสวนหลังบ้าน ต่อมาในคืนเดียวกัน เฮนรี แม็คแดเนียล ได้ยินเสียงข่วนประตูหน้าบ้าน เมื่อเปิดออกเขาต้องตกตะลึงเมื่อพบสัตว์ประหลาดสูง 5 ฟุต ลำตัวผอมเกร็งสีเทา มีแขนสั้นกุดยื่นออกมาจากหน้าอก ดวงตาสีชมพูกลมโตเรืองแสงในความมืด และที่แปลกประหลาดที่สุดคือมันมี 3 ขา มันกระโดดข้ามรั้วสูงด้วยการกระโดดเพียงครั้งเดียวไกลถึง 40 ฟุต นำไปสู่การระดมกำลังล่าสัตว์ประหลาดของนายอำเภอและชาวบ้านกว่าร้อยคน',
      'In April 1973, terror gripped the small town of Enfield, Illinois. Henry McDaniel stepped onto his porch after hearing scratching sounds, coming face-to-face with a bizarre, five-foot-tall monstrosity sporting grey, slimy skin, short clawed arms protruding from its chest, large glowing pink reflective eyes, and three functional legs. McDaniel fired four rounds into the beast, which hissed like a wildcat before clearing forty feet in a single bound toward the nearby railroad embankment.',
      'นายอำเภอ รอย แวนเซ็นต์ ขู่ว่าจะจับกุมชาวบ้านที่ติดอาวุธและนักข่าวที่แห่กันเข้ามาในเมืองหลังมีการพบรอยเท้าสามนิ้วและรอยข่วนลึกบนแผ่นไม้ประตู',
      'Police and Western Illinois University researchers plaster-cast bizarre six-toed tracks bearing three clawed pads along the railway tracks before sightings abruptly ceased.',
      'ห้ามเปิดประตูหน้าบ้านในเวลากลางคืนหากได้ยินเสียงเล็บขูดเบาๆ',
      'Do not open external doors when subtle claw-scratching sounds echo on porch screens.',
      'https://i.ytimg.com/vi/7iMQm6tU-BI/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/7iMQm6tU-BI/hqdefault.jpg","title":"สัตว์ประหลาดเอนฟิลด์ (อสูรสามขาตาเรืองแสงแห่งอิลลินอยส์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=7iMQm6tU-BI","title":"The Three-Legged Creature that Terrorized This Town (Enfeild Monster)","thumbnail":"https://i.ytimg.com/vi/7iMQm6tU-BI/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-monster-honey-island-swamp-monster',
      'สัตว์ประหลาดบึงฮันนีไอส์แลนด์ (บิ๊กฟุตแห่งป่าพรุลุยเซียนา)',
      'The Honey Island Swamp Monster (The Cajun Sasquatch of the Bayou)',
      'monster',
      'ลุยเซียนา',
      'Louisiana',
      'บึงฮันนีไอส์แลนด์ เซนต์แทมมานี',
      'Honey Island Swamp, St. Tammany Parish',
      30.4167,
      -89.7,
      'water_spirit',
      'อสูรกายแห่งป่าพรุฮันนีไอส์แลนด์ หนึ่งในพื้นที่ชุ่มน้ำธรรมชาติที่ยังคงความดิบเถื่อนที่สุดในสหรัฐฯ ตำนานเคจุนเล่าว่าสิ่งมีชีวิตนี้เป็นสิ่งมีชีวิตกึ่งคนกึ่งลิง สูงประมาณ 7 ฟุต ขนสีเทาเข้มยาวรุงรัง มีดวงตาสีอำพันขนาดใหญ่ จุดเด่นเฉพาะตัวคือมีนิ้วเท้า 4 นิ้วที่มีพังผืดเชื่อมต่อกันสำหรับการว่ายน้ำในโคลนตม พรานล่าสัตว์ ฮาร์ลาน ฟอร์ด บันทึกวิดีโอ 8 มม. ในปี 1974 เผยให้เห็นเงาร่างล่ำสันเดินลุยโคลนในดงต้นไซเปรสโบราณ และมีรายงานการพบซากหมูป่าและจระเข้ที่ถูกฉีกคอด้วยพละกำลังมหาศาล',
      'Inhabiting the dense cypress-tupelo bayous of southeastern Louisiana, the Honey Island Swamp Monster (known locally as the ''Loup-Garou'' or ''Cajun Bigfoot'') is a bipedal cryptid standing over seven feet tall with matted slate-grey fur and piercing golden reptilian eyes. First widely reported by air traffic controller and wildlife tracker Harlan Ford in the 1960s, casts of its tracks reveal unique webbed, four-toed feet adapted for aquatic swamp ambushes, accompanied by a foul rotting-fish odor.',
      'ตำนานพื้นบ้านเคจุนเล่าขานว่าสัตว์ประหลาดตัวนี้อาจเกิดจากลิงชิมแปนซีคณะละครสัตว์ที่หลบหนีจากอุบัติเหตุรถไฟตกรางในปี 1915 และผสมข้ามสายพันธุ์กับจระเข้ในป่าพรุ',
      'Local folklore humorously alleges circus train car derailments in the early 20th century introduced chimpanzees that adapted and bred in the impenetrable 70,000-acre wilderness.',
      'ห้ามดับเครื่องยนต์เรือหางยาวขณะลอยลำในคุ้งน้ำลึกของบึงฮันนีไอส์แลนด์',
      'Keep motorboat engines idling while navigating the interior cypress backwaters at dusk.',
      'https://i.ytimg.com/vi/_X9eR83P6mY/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/_X9eR83P6mY/hqdefault.jpg","title":"สัตว์ประหลาดบึงฮันนีไอส์แลนด์ (บิ๊กฟุตแห่งป่าพรุลุยเซียนา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=_X9eR83P6mY","title":"Tales of the Honey Island Swamp Monster: Bigfoot Beyond the Trail","thumbnail":"https://i.ytimg.com/vi/_X9eR83P6mY/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-monster-bear-lake-monster-idaho-utah',
      'สัตว์ประหลาดแห่งแบร์เลก (มังกรน้ำจืดแห่งเทือกเขาร็อกกี้)',
      'The Bear Lake Monster (The Great Freshwater Serpent of the Rockies)',
      'monster',
      'ยูทาห์',
      'Utah',
      'การ์เดนซิตี ริช',
      'Garden City, Rich County',
      41.9333,
      -111.3333,
      'jungle_curse',
      'สัตว์ประหลาดในทะเลสาบน้ำจืดสีฟ้าเทอร์ควอยซ์ ''แบร์เลก'' บริเวณพรมแดนระหว่างรัฐยูทาห์และไอดาโฮ ชนเผ่าโชโชนีมีตำนานเตือนภัยเรื่องมังกรน้ำยักษ์ดุร้ายที่มักจับคนและม้าที่ลงไปว่ายน้ำ ต่อมาในทศวรรษ 1860 ผู้นำชุมชนมอร์มอน โจเซฟ ซี. ริช ได้บันทึกคำบอกเล่าของพยานหลายสิบคนที่เห็นสิ่งมีชีวิตลำตัวยาวคล้ายงูทะเล ยาวกว่า 50 ถึง 90 ฟุต ว่ายน้ำด้วยความเร็วสูงเร็วกว่าม้าควบ มีส่วนหัวคล้ายจระเข้หรือนากทะเลขนาดยักษ์ และมีครีบว่ายน้ำที่พ่นละอองน้ำเป็นระลอกคลื่นสูง',
      'Lurking in the deep, turquoise-blue waters of Bear Lake on the Utah-Idaho border, the Bear Lake Monster has been feared by indigenous Shoshone tribes for centuries as a man-eating aquatic dragon. In 1868, Mormon pioneer Joseph C. Rich published a series of articles detailing credible eyewitness encounters describing a creature up to 90 feet long with a crocodile-shaped head, cream-colored belly scales, and stubby legs allowing it to move swifter through the water than a galloping locomotive.',
      'การพบเห็นได้รับความสนใจจนบริแกม ยัง (Brigham Young) ผู้นำศาสนาจักรยานมอร์มอน ส่งคณะสำรวจพร้อมเชือกเส้นใหญ่และฉมวกมาเตรียมจับสัตว์ประหลาดตัวนี้',
      'Mormon Church president Brigham Young dispatched an expedition equipped with heavy maritime rope and whaling harpoons in an attempt to capture the beast alive.',
      'ห้ามพายเรือแคนูข้ามจุดลึกสุดของทะเลสาบแบร์เลกในวันที่น้ำนิ่งสนิท',
      'Never paddle small canoes across the deep eastern trenches when the water is mirror-calm.',
      'https://i.ytimg.com/vi/SOWmyUtfgAg/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/SOWmyUtfgAg/hqdefault.jpg","title":"สัตว์ประหลาดแห่งแบร์เลก (มังกรน้ำจืดแห่งเทือกเขาร็อกกี้)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=SOWmyUtfgAg","title":"The Bear Lake Monster: Is the star of Utah''s urban legend the same as the Loch Ness Monster?","thumbnail":"https://i.ytimg.com/vi/SOWmyUtfgAg/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-monster-cadborosaurus-caddy-bc',
      'แคดโบโรซอรัส (แคดดี้ พญางูทะเลแห่งแปซิฟิกตะวันตกเฉียงเหนือ)',
      'Cadborosaurus willsii (Caddy, The Pacific Coast Sea Serpent)',
      'monster',
      'บริติชโคลัมเบีย',
      'British Columbia',
      'อ่าวแคดโบโร วิกตอเรีย',
      'Cadboro Bay, Victoria',
      48.4597,
      -123.2944,
      'jungle_curse',
      'อสรพิษทะเลยักษ์แห่งชายฝั่งแปซิฟิกตะวันตกเฉียงเหนือ มีชื่อเล่นว่า ''แคดดี้'' (Caddy) ตามชื่ออ่าวแคดโบโรในเมืองวิกตอเรีย ชนเผ่าเฟิร์สต์เนชันส์มีภาพแกะสลักหินรูป ''ฮิยาฮิตลิก'' (งูทะเลยักษ์มีหัวคล้ายม้า) มาแต่โบราณ มีรายงานการพบเห็นโดยกะลาสีเรือและชาวประมงหลายร้อยครั้งตลอดศตวรรษที่ 20 บรรยายถึงสิ่งมีชีวิตลำตัวยาว 30 ถึง 60 ฟุต มีส่วนหัวคล้ายม้าหรืออูฐ คอยาวตั้งตรง มีครีบหน้าคล้ายใบพาย และมีสันหลังเป็นลอนคลื่น ในปี 1937 มีการผ่าท้องวาฬสเปิร์มที่สถานีล่าวาฬเกาะไฮดากวายและพบซากสิ่งมีชีวิตประหลาดที่ถูกบันทึกภาพถ่ายไว้',
      'Cadborosaurus willsii, affectionately known as ''Caddy'', is a marine cryptid repeatedly documented along the Pacific Northwest coast, particularly near Cadboro Bay, British Columbia. Venerated in Salish petroglyphs as ''Namun'', witnesses describe an aquatic reptile or primitive mammal 30 to 60 feet long with a camel-like head, prominent whiskers, and flipper-shaped appendages capable of moving at 40 knots. In 1937, whalers at Naden Harbour retrieved a bizarre, juvenile carcass from a sperm whale''s stomach, photographed before it mysteriously vanished.',
      'ภาพถ่ายซากสิ่งมีชีวิตที่นาเดนฮาร์เบอร์ในปี 1937 ยังคงเป็นหนึ่งในหลักฐานภาพถ่ายที่มีชื่อเสียงและถูกถกเถียงมากที่สุดในวงการสัตววิทยาลี้ลับโลก',
      'Described as a distinct zoological species by scientists Dr. Paul LeBlond and Edward Bousfield, peer-reviewed papers classify Caddy as an archaic plesiosaur or serpentine archaeocete.',
      'ห้ามเข้าใกล้หรือดึงซากสัตว์น้ำขนาดยักษ์ที่ไม่สามารถระบุชนิดได้ขึ้นเรือ',
      'Do not attempt to hoist unidentified serpentine marine carcasses onto fishing decks.',
      'https://i.ytimg.com/vi/a3wx8Fk2YMg/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/a3wx8Fk2YMg/hqdefault.jpg","title":"แคดโบโรซอรัส (แคดดี้ พญางูทะเลแห่งแปซิฟิกตะวันตกเฉียงเหนือ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=a3wx8Fk2YMg","title":"Cadborosaurus Mini Doc","thumbnail":"https://i.ytimg.com/vi/a3wx8Fk2YMg/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-monster-orang-pendek-sumatra',
      'โอรังเปนเดะก์ (มนุษย์วานรแคระขนทองแห่งป่าลึกสุมาตรา)',
      'Orang Pendek (The Ground-Dwelling Man-Ape of Kerinci Seblat)',
      'monster',
      'จัมบี',
      'Jambi',
      'อุทยานแห่งชาติเกรินจีเซอบลัต',
      'Kerinci Seblat National Park',
      -2.0833,
      101.4833,
      'jungle_curse',
      'สิ่งมีชีวิตลึกลับคล้ายมนุษย์วานรแคระที่อาศัยอยู่ในป่าดิบชื้นดึกดำบรรพ์ของเกาะสุมาตรา ประเทศอินโดนีเซีย มีรายงานการพบเห็นมาหลายร้อยปีตั้งแต่ยุคอาณานิคมดัตช์ ''โอรังเปนเดะก์'' (แปลว่า คนเตี้ย) มีความสูงประมาณ 80 ถึง 150 เซนติเมตร ลำตัวกำยำ แขนยาว ไหล่กว้าง และมีพละกำลังมหาศาลจนสามารถถอนต้นไม้เล็กๆ ได้ ร่างกายปกคลุมด้วยขนสั้นหนาสีน้ำตาลช็อกโกแลตหรือสีทอง ใบหน้าคล้ายมนุษย์ผสมลิงไร้หาง และที่น่าทึ่งคือมันเดินสองขาตัวตรงบนพื้นดินตลอดเวลา',
      'Inhabiting the dense, mountainous rainforests of Kerinci Seblat National Park in western Sumatra, the Orang Pendek (''Short Person'') is a bipedal cryptid hominid standing between 3 to 5 feet tall. Chronicled by indigenous tribes and Dutch colonists since the 19th century, it is described as exceptionally muscular with broad shoulders, short golden-brown fur, a human-like chest, and humanized facial contours. Unlike known arboreal orangutans, Orang Pendek walks habitually upright on the ground.',
      'นักวิจัยจากมหาวิทยาลัยเคมบริดจ์และเนชั่นแนล จีโอกราฟฟิก เคยเก็บตัวอย่างเส้นขนและรอยพิมพ์ฝ่าเท้าไปตรวจดีเอ็นเอ ซึ่งพบว่าเป็นไพรเมตที่ไม่ตรงกับสายพันธุ์ใดในฐานข้อมูลวิทยาศาสตร์',
      'Multi-year camera trap expeditions by conservationist Debbie Martyr produced plaster footprint casts and hair samples whose mitochondrial DNA matched no known species of primate or human.',
      'ห้ามเลียนเสียงร้องเคาะไม้ของโอรังเปนเดะก์ในป่าลึกเกรินจี',
      'Never mimic tree-trunk drumming vocalizations while tracking through primary Kerinci jungle.',
      'https://i.ytimg.com/vi/dBBJn3s4Vs8/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/dBBJn3s4Vs8/hqdefault.jpg","title":"โอรังเปนเดะก์ (มนุษย์วานรแคระขนทองแห่งป่าลึกสุมาตรา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=dBBJn3s4Vs8","title":"The Elusive Orang Pendek of the Sumatran Jungle","thumbnail":"https://i.ytimg.com/vi/dBBJn3s4Vs8/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-monster-chessie-chesapeake-bay',
      'เชสซี่ (พญางูยักษ์แห่งอ่าวเชซาพีก)',
      'Chessie (The Serpentine Beast of the Chesapeake Bay)',
      'monster',
      'แมริแลนด์',
      'Maryland',
      'อ่าวเชซาพีก เคนต์ไอส์แลนด์',
      'Chesapeake Bay, Kent Island',
      38.9833,
      -76.35,
      'jungle_curse',
      'สัตว์ประหลาดแห่งอ่าวเชซาพีก รัฐแมริแลนด์และเวอร์จิเนีย มีบันทึกการพบเห็นมาตั้งแต่ช่วงทศวรรษ 1930 และโด่งดังไปทั่วโลกในปี 1982 เมื่อครอบครัวโฟรว์ ถ่ายวิดีโอเทปสีความยาวกว่า 3 นาทีจากเกาะเคนต์ไอส์แลนด์ บันทึกภาพสิ่งมีชีวิตลำตัวยาวคล้ายงูทะเลสีน้ำตาลเข้ม ยาวประมาณ 30 ถึง 40 ฟุต ลำตัวหนาเท่าถังน้ำมัน เคลื่อนที่ด้วยการขดตัวเป็นลูกคลื่นขึ้นลงในแนวตั้งด้วยความเร็วสูง นักชีววิทยาทางทะเลของสถาบันสมิธโซเนียนเคยประชุมวิเคราะห์วิดีโอนี้และยืนยันว่าไม่ใช่ปลาหรือสัตว์น้ำทั่วไป',
      'Chessie is the fabled serpentine aquatic monster inhabiting the Chesapeake Bay. Achieving international fame in May 1982 when Robert Frew recorded a celebrated three-minute color video off Kent Island, Maryland, the footage clearly depicted a dark, undulating serpentine creature thirty to forty feet long moving swiftly through the waves. Marine biologists from the Smithsonian Institution convened to analyze the footage, verifying that the locomotion was characteristic of an unknown living aquatic animal.',
      'เจ้าหน้าที่หน่วยยามฝั่งสหรัฐฯ และนักบินเฮลิคอปเตอร์ตำรวจเคยรายงานการพบเห็นสิ่งมีชีวิตขนาดมหึมาแหวกว่ายอยู่ใต้ผิวน้ำใสของอ่าวหลายครั้ง',
      'Eyewitness reports surged throughout the 1980s, prompting Maryland state wildlife officials to publish official protective guidelines cautioning boaters not to harass Chessie.',
      'ห้ามแล่นเรือเร็วตัดหน้าระลอกคลื่นยักษ์ปริศนาในอ่าวเชซาพีก',
      'Do not steer high-speed watercraft across mysterious undulating wake lines in the bay.',
      'https://i.ytimg.com/vi/5aSpaMxAs0M/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/5aSpaMxAs0M/hqdefault.jpg","title":"เชสซี่ (พญางูยักษ์แห่งอ่าวเชซาพีก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=5aSpaMxAs0M","title":"Something In The Bay; The Tale Of Chessie. The Chesapeake''s Loch Ness.","thumbnail":"https://i.ytimg.com/vi/5aSpaMxAs0M/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-monster-dobhar-chu-irish-crocodile',
      'โดบาร์-ชู (สุนัขน้ำมรณะและจระเข้โบราณแห่งไอร์แลนด์)',
      'The Dobhar-chu (The Water Hound and King Otter of Glenade)',
      'monster',
      'ลีทริม',
      'County Leitrim',
      'ทะเลสาบเกลเนด ลีทริม',
      'Glenade Lough, Manorhamilton',
      54.3333,
      -8.2833,
      'water_spirit',
      'สัตว์ประหลาดดุร้ายในตำนานพื้นบ้านไอริช มีชื่อเรียกอีกอย่างว่า ''สุนัขน้ำ'' หรือ ''ราชาแห่งนาก'' (King Otter) มีลำตัวกึ่งสุนัขกึ่งนากขนาดใหญ่ แต่มีผิวหนังหนาและมีเกล็ดคล้ายจระเข้ ว่ายน้ำได้รวดเร็วและสามารถขึ้นมาล่าเหยื่อบนบกได้ เหตุการณ์ที่โด่งดังที่สุดเกิดขึ้นในปี 1722 ริมทะเลสาบเกลเนดล็อก เมื่อเกรซ คอนนอลลี่ ถูกอสูรโดบาร์-ชู จู่โจมสังหารขณะกำลังซักผ้า สามีของเธอตามมาพบศพและได้แทงสัตว์ร้ายตาย แต่ก่อนตายมันได้ส่งเสียงหวีดร้องเรียกคู่ของมันขึ้นมาจากน้ำเพื่อไล่ล่าเขาจนเกิดการต่อสู้ครั้งประวัติศาสตร์',
      'The Dobhar-chu, or ''water hound'', is an aggressive carnivorous cryptid of Irish Celtic folklore, described as a lethal hybrid of a giant otter, dog, and crocodile with sleek waterproof fur and deadly protective scales. The definitive historic encounter occurred in September 1722 at Glenade Lough in County Leitrim: Grace Connolly was attacked and devoured while washing clothes. Her grief-stricken husband pursued and slew the beast, whose dying whistle summoned a second, vengeful mate from the depths.',
      'ป้ายหลุมศพโบราณของเกรซ คอนนอลลี่ ในสุสานโคนวอลล์ (Conwall Cemetery) มีภาพสลักรูปอสูรโดบาร์-ชู ถูกหอกแทงทะลุคอเป็นพยานหลักฐานประวัติศาสตร์',
      'Grace Connolly''s 1722 tombstone in Conwall Cemetery bears a detailed relief carving of the dying Dobhar-chu pierced by a spear, standing as rare physical folklore documentation.',
      'ห้ามซักผ้าหรือยืนแช่น้ำริมตลิ่งทะเลสาบเกลเนดตามลำพังในยามเช้าตรู่',
      'Never wash clothes or stand isolated in the shallows of Glenade Lough at dawn.',
      'https://i.ytimg.com/vi/IGEt1j0Gd4Q/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/IGEt1j0Gd4Q/hqdefault.jpg","title":"โดบาร์-ชู (สุนัขน้ำมรณะและจระเข้โบราณแห่งไอร์แลนด์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=IGEt1j0Gd4Q","title":"The Dobhar-chu: Ireland''s Deadliest Cryptid Exposed","thumbnail":"https://i.ytimg.com/vi/IGEt1j0Gd4Q/hqdefault.jpg"}]'
    );